-- Acta full provisioning script (mssql), schema 'acta'. GENERATED by tools/Acta.Emit (`docs`
-- command); do not hand-edit here - edit the source SQL and regenerate. To relocate, replace the
-- schema name 'acta' throughout.
--
-- The same SQL the bootstrap migration runner applies: the migration history table, then every
-- migration in order (each records its own history row).
-- It takes the per-schema lock the runtime bootstrap takes before either reads the history, so
-- two installers, script or bootstrap, never interleave.
-- It also sets READ_COMMITTED_SNAPSHOT on the database, the way the runtime's own bootstrap
-- does: the first batch, outside the transaction, skipped on a fresh install and on a re-run
-- alike once the database has it on.
--
-- WHERE TO RUN IT. Run it on an empty database to install, or again on a database it already
-- provisioned: every statement is guarded or idempotent, so a re-run changes nothing that is
-- present and leaves the data in place. Over a database a newer release upgraded, the script stops
-- before changing anything. A later 1.x release upgrades a 1.x database with
-- its own migrations, carried in its own copy of this script. A database provisioned by a
-- release candidate (1.0.0-rc.x) has no upgrade path: provision a new one.
--
-- Run it with a client that stops at the first error, which is what makes the transaction below a
-- guarantee: sqlcmd -b, or SQLCMD mode with stop-on-error in SSMS. A client that runs on past a failed
-- batch would reach the history rows with an object it failed to replace still in place.
-- Run it under a DDL-capable principal; the application principal then needs only DML and
-- EXECUTE, with ApplyMigrationsOnStartup left false. Because the history rows are recorded by
-- the script itself, a bootstrap with migrations enabled also accepts the result and applies
-- nothing. Site-specific physical tuning (partitioning, tablespaces, compression) is yours to
-- add; keep the logical shape - tables, columns, constraints, routine signatures - intact.

-- READ_COMMITTED_SNAPSHOT is part of a provisioned Acta database rather than an optional
-- tuning knob: it is the configuration Acta certifies, and it is what keeps operator and
-- dashboard reads from taking shared locks and trading blocking with the claim path. Job
-- correctness does not depend on it - mutations are fenced by lock hints and
-- compare-and-swap - but reader-side operability does. ALTER DATABASE cannot run inside a
-- user transaction, hence this separate batch ahead of the one below. A database that
-- already has it on skips the statement entirely, on install and on re-run alike; when it
-- does run, WITH ROLLBACK IMMEDIATE disconnects the other sessions in the database, so run
-- this file in a maintenance window.
IF (SELECT is_read_committed_snapshot_on FROM sys.databases WHERE database_id = DB_ID()) = 0
    ALTER DATABASE CURRENT SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;
GO
SET XACT_ABORT ON;
BEGIN TRANSACTION;
GO
-- ===== the installer lock, held to commit =====
DECLARE @lock_rc INT;
EXEC @lock_rc = sp_getapplock N'acta-migrations', 'Exclusive', 'Transaction', 60000;
IF @lock_rc < 0
BEGIN
    RAISERROR(N'sp_getapplock failed acquiring the acta-migrations lock', 16, 1);
    IF @@TRANCOUNT > 0 ROLLBACK;
    SET NOEXEC ON;
END
GO
-- ===== migration history table =====
IF SCHEMA_ID(N'acta') IS NULL EXEC (N'CREATE SCHEMA acta');
IF OBJECT_ID(N'acta.migrations', N'U') IS NULL
    CREATE TABLE acta.migrations (
        name VARCHAR(256) NOT NULL,
        applied_at_utc DATETIME2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
        CONSTRAINT pk_migrations PRIMARY KEY (name)
    );
GO
-- ===== refuse a database a newer release already upgraded =====
IF EXISTS (
    SELECT 1 FROM acta.migrations
    WHERE name NOT IN ('M20261015185851_init', 'M20261016080729_claim_writes_no_started_event', 'M20261016085434_enqueue_probes_seek', 'M20261016094552_jobs_no_lock_escalation', 'M20261016095220_seeks_pinned', 'M20261016100113_runtimes_failed_index', 'M20261016133503_enqueue_probes_seek_both_keys', 'M20261016144619_dedup_key_lock', 'M20261016145839_sleep_timer_no_holdlock')
)
BEGIN
    RAISERROR(N'A newer Acta release already upgraded this database. Run the newest provisioning script; this one would move it backwards.', 16, 1);
    IF @@TRANCOUNT > 0 ROLLBACK;
    SET NOEXEC ON;
END
GO
-- ===== BEGIN M20261015185851_init =====
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

IF SCHEMA_ID('acta') IS NULL EXEC('CREATE SCHEMA acta');
GO

-- alerts
IF OBJECT_ID(N'acta.alerts', N'U') IS NULL
BEGIN
CREATE TABLE acta.alerts (
    id bigint IDENTITY(1,1) NOT NULL,
    alert_ref uniqueidentifier NOT NULL,
    namespace_id int NOT NULL,
    job_id bigint NULL,
    job_ref uniqueidentifier NULL,
    origin_code tinyint NOT NULL,
    severity_code tinyint NOT NULL,
    kind_code tinyint NOT NULL,
    title nvarchar(512) NOT NULL,
    message nvarchar(512) NOT NULL,
    channel_name varchar(128) NOT NULL,
    deduplication_key varchar(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    occurrence_count int NOT NULL,
    last_projected_event_id bigint NULL,
    resolved_at_utc datetime2(3) NULL,
    acknowledged_at_utc datetime2(3) NULL,
    delivery_status_code tinyint NOT NULL,
    retry_count int NOT NULL,
    retry_after_utc datetime2(3) NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_alerts PRIMARY KEY (id)
    , CONSTRAINT ck_alerts_job_ref_pair CHECK ((job_id IS NULL AND job_ref IS NULL) OR (job_id IS NOT NULL AND job_ref IS NOT NULL))
    , CONSTRAINT ck_alerts_occurrence_count CHECK (occurrence_count >= 1)
);
CREATE INDEX ix_alerts_deduplication_key_identity ON acta.alerts (namespace_id, deduplication_key) WHERE deduplication_key IS NOT NULL;
CREATE INDEX ix_alerts_delivery_due ON acta.alerts (namespace_id, delivery_status_code, retry_after_utc, id);
CREATE INDEX ix_alerts_namespace_created ON acta.alerts (namespace_id, created_at_utc DESC, id DESC);
CREATE INDEX ix_alerts_namespace_unresolved ON acta.alerts (namespace_id, created_at_utc DESC, id DESC) WHERE resolved_at_utc IS NULL;
CREATE INDEX ix_alerts_job ON acta.alerts (job_id, id) WHERE job_id IS NOT NULL;
CREATE UNIQUE INDEX ux_alerts_ref ON acta.alerts (alert_ref);
CREATE UNIQUE INDEX ux_alerts_deduplication_key ON acta.alerts (namespace_id, deduplication_key) WHERE deduplication_key IS NOT NULL AND resolved_at_utc IS NULL;
END
GO

-- definitions
IF OBJECT_ID(N'acta.definitions', N'U') IS NULL
BEGIN
CREATE TABLE acta.definitions (
    id int IDENTITY(1,1) NOT NULL,
    namespace_id int NOT NULL,
    name varchar(128) NOT NULL,
    status_code tinyint NOT NULL,
    definition_hash varchar(128) NOT NULL,
    manifest_generation_at_utc datetime2(3) NOT NULL,
    input_type_name varchar(512) NOT NULL,
    input_format_id tinyint NOT NULL,
    input_format_name varchar(128) NOT NULL,
    output_type_name varchar(512) NULL,
    output_format_id tinyint NOT NULL,
    output_format_name varchar(128) NOT NULL,
    tenant_requirement_code tinyint NOT NULL,
    priority_code tinyint NOT NULL,
    priority_code_override tinyint NULL,
    priority_code_effective AS (COALESCE(priority_code_override, priority_code)) PERSISTED,
    max_attempts int NOT NULL,
    max_attempts_override int NULL,
    max_attempts_effective AS (COALESCE(max_attempts_override, max_attempts)) PERSISTED,
    concurrency_limit int NULL,
    concurrency_limit_override int NULL,
    concurrency_limit_effective AS (COALESCE(concurrency_limit_override, concurrency_limit)) PERSISTED,
    rate_limit varchar(16) NULL,
    rate_limit_override varchar(16) NULL,
    rate_limit_effective AS (COALESCE(rate_limit_override, rate_limit)) PERSISTED,
    rate_name varchar(128) NULL,
    lane varchar(128) NULL,
    backoff nvarchar(64) NOT NULL,
    backoff_override nvarchar(64) NULL,
    backoff_effective AS (COALESCE(backoff_override, backoff)) PERSISTED,
    execution_timeout_seconds int NOT NULL,
    execution_timeout_seconds_override int NULL,
    execution_timeout_seconds_effective AS (COALESCE(execution_timeout_seconds_override, execution_timeout_seconds)) PERSISTED,
    deadline_seconds int NOT NULL,
    deadline_seconds_override int NULL,
    deadline_seconds_effective AS (COALESCE(deadline_seconds_override, deadline_seconds)) PERSISTED,
    deadline_behavior_code tinyint NOT NULL,
    deadline_behavior_code_override tinyint NULL,
    deadline_behavior_code_effective AS (COALESCE(deadline_behavior_code_override, deadline_behavior_code)) PERSISTED,
    retention_seconds int NOT NULL,
    retention_seconds_override int NULL,
    retention_seconds_effective AS (COALESCE(retention_seconds_override, retention_seconds)) PERSISTED,
    audit_level_code tinyint NOT NULL,
    audit_level_code_override tinyint NULL,
    audit_level_code_effective AS (COALESCE(audit_level_code_override, audit_level_code)) PERSISTED,
    alert_profile_code tinyint NOT NULL,
    alert_profile_code_override tinyint NULL,
    alert_profile_code_effective AS (COALESCE(alert_profile_code_override, alert_profile_code)) PERSISTED,
    alert_channel_name varchar(128) NULL,
    alert_channel_name_override varchar(128) NULL,
    alert_channel_name_effective AS (COALESCE(alert_channel_name_override, alert_channel_name)) PERSISTED,
    runbook_url varchar(512) NULL,
    runbook_url_override varchar(512) NULL,
    runbook_url_effective AS (COALESCE(runbook_url_override, runbook_url)) PERSISTED,
    display_name nvarchar(128) NULL,
    display_name_override nvarchar(128) NULL,
    display_name_effective AS (COALESCE(display_name_override, display_name)) PERSISTED,
    description nvarchar(512) NULL,
    description_override nvarchar(512) NULL,
    description_effective AS (COALESCE(description_override, description)) PERSISTED,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_definitions PRIMARY KEY (id)
    , CONSTRAINT ck_definitions_max_attempts CHECK (max_attempts >= 1)
    , CONSTRAINT ck_definitions_max_attempts_override CHECK (max_attempts_override IS NULL OR max_attempts_override >= 1)
    , CONSTRAINT ck_definitions_execution_timeout CHECK (execution_timeout_seconds > 0)
    , CONSTRAINT ck_definitions_execution_timeout_override CHECK (execution_timeout_seconds_override IS NULL OR execution_timeout_seconds_override > 0)
    , CONSTRAINT ck_definitions_deadline CHECK (deadline_seconds >= 0)
    , CONSTRAINT ck_definitions_deadline_override CHECK (deadline_seconds_override IS NULL OR deadline_seconds_override >= 0)
    , CONSTRAINT ck_definitions_retention CHECK (retention_seconds >= 0)
    , CONSTRAINT ck_definitions_retention_override CHECK (retention_seconds_override IS NULL OR retention_seconds_override >= 0)
);
CREATE UNIQUE INDEX ux_definitions_namespace_name ON acta.definitions (namespace_id, name);
END
GO

-- events
IF OBJECT_ID(N'acta.events', N'U') IS NULL
BEGIN
CREATE TABLE acta.events (
    id bigint IDENTITY(1,1) NOT NULL,
    event_code tinyint NOT NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    namespace_id int NOT NULL,
    actor_code tinyint NOT NULL,
    actor nvarchar(128) NULL,
    job_id bigint NULL,
    job_ref uniqueidentifier NULL,
    execution_number int NULL,
    lineage_root_id bigint NULL,
    definition_id int NULL,
    tenant_id int NULL,
    worker_id int NULL,
    from_status_code tinyint NULL,
    to_status_code tinyint NULL,
    execution_status_code tinyint NULL,
    duration_ms int NULL,
    reason_code tinyint NULL,
    reason_message nvarchar(512) NULL,
    detail_format_id tinyint DEFAULT 0 NOT NULL,
    detail varbinary(max) NULL
    , CONSTRAINT pk_events PRIMARY KEY (id) WITH (OPTIMIZE_FOR_SEQUENTIAL_KEY = ON)
    , CONSTRAINT ck_events_detail_pair CHECK ((detail_format_id = 0 AND detail IS NULL) OR (detail_format_id <> 0 AND detail IS NOT NULL))
) WITH (DATA_COMPRESSION = PAGE);
CREATE INDEX ix_events_lineage_timeline ON acta.events (lineage_root_id, created_at_utc, id) WHERE lineage_root_id IS NOT NULL;
CREATE INDEX ix_events_namespace_timeline ON acta.events (namespace_id, event_code, created_at_utc, id);
CREATE INDEX ix_events_job_timeline ON acta.events (job_id, created_at_utc, id) WHERE job_id IS NOT NULL;
CREATE INDEX ix_events_namespace_created ON acta.events (namespace_id, created_at_utc DESC, id DESC);
END
GO

-- jobs
IF OBJECT_ID(N'acta.jobs', N'U') IS NULL
BEGIN
CREATE TABLE acta.jobs (
    id bigint IDENTITY(1,1) NOT NULL,
    job_ref uniqueidentifier NOT NULL,
    namespace_id int NOT NULL,
    definition_id int NOT NULL,
    lineage_root_id bigint NULL,
    parent_id bigint NULL,
    tenant_id int NULL,
    deduplication_key varchar(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    correlation_key varchar(64) NULL,
    concurrency_key varchar(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    input_format_id tinyint NOT NULL,
    input varbinary(max) NULL,
    audit_level_code tinyint NOT NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL
    , CONSTRAINT pk_jobs PRIMARY KEY (id) WITH (OPTIMIZE_FOR_SEQUENTIAL_KEY = ON)
    , CONSTRAINT ck_jobs_input_pair CHECK ((input_format_id = 0 AND input IS NULL) OR (input_format_id <> 0 AND input IS NOT NULL))
);
CREATE INDEX ix_jobs_parent ON acta.jobs (parent_id) WHERE parent_id IS NOT NULL;
CREATE INDEX ix_jobs_namespace_created ON acta.jobs (namespace_id, created_at_utc DESC, id DESC);
CREATE UNIQUE INDEX ux_jobs_ref ON acta.jobs (job_ref);
CREATE UNIQUE INDEX ux_jobs_deduplication_key_root ON acta.jobs (namespace_id, deduplication_key) WHERE deduplication_key IS NOT NULL AND parent_id IS NULL;
CREATE UNIQUE INDEX ux_jobs_deduplication_key_child ON acta.jobs (parent_id, deduplication_key) WHERE deduplication_key IS NOT NULL AND parent_id IS NOT NULL;
END
