-- namespaces
IF OBJECT_ID(N'acta.namespaces', N'U') IS NULL
BEGIN
CREATE TABLE acta.namespaces (
    id int IDENTITY(1,1) NOT NULL,
    name varchar(128) NOT NULL,
    owner_team nvarchar(512) NULL,
    description nvarchar(512) NULL,
    status_code tinyint NOT NULL,
    catalog_hash varchar(128) NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL,
    recovery_due_at_utc datetime2(3) NULL
    , CONSTRAINT pk_namespaces PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ux_namespaces_name ON acta.namespaces (name);
END
GO

-- Seed: reserved system namespace (id=1, 'sys') for cross-namespace audit events. Collation-neutral.
IF NOT EXISTS (SELECT 1 FROM acta.namespaces WHERE id = 1)
BEGIN
    SET IDENTITY_INSERT acta.namespaces ON;
    INSERT INTO acta.namespaces (id, name, status_code, description, created_at_utc, modified_at_utc)
    VALUES (1, N'sys', 10, N'Reserved system namespace for cross-namespace audit events.', SYSUTCDATETIME(), SYSUTCDATETIME());
    SET IDENTITY_INSERT acta.namespaces OFF;
END
GO

-- results
IF OBJECT_ID(N'acta.results', N'U') IS NULL
BEGIN
CREATE TABLE acta.results (
    job_id bigint NOT NULL,
    execution_number int NOT NULL,
    result_format_id tinyint NOT NULL,
    result varbinary(max) NOT NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL
    , CONSTRAINT pk_results PRIMARY KEY (job_id, execution_number) WITH (OPTIMIZE_FOR_SEQUENTIAL_KEY = ON)
    , CONSTRAINT ck_results_format_not_none CHECK (result_format_id <> 0)
    , CONSTRAINT fk_results_jobs FOREIGN KEY (job_id) REFERENCES acta.jobs (id) ON DELETE CASCADE
);
END
GO

-- runtimes
IF OBJECT_ID(N'acta.runtimes', N'U') IS NULL
BEGIN
CREATE TABLE acta.runtimes (
    job_id bigint NOT NULL,
    namespace_id int NOT NULL,
    lane_id bigint NULL,
    status_code tinyint NOT NULL,
    priority_code tinyint NOT NULL,
    next_run_at_utc datetime2(3) NULL,
    execution_number int NOT NULL,
    failure_count int NOT NULL,
    leased_by_worker_id int NULL,
    lease_expires_at_utc datetime2(3) NULL,
    retention_until_utc datetime2(3) NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_runtimes PRIMARY KEY (job_id) WITH (OPTIMIZE_FOR_SEQUENTIAL_KEY = ON)
    , CONSTRAINT ck_runtimes_blocked_lane CHECK (status_code <> 15 OR lane_id IS NOT NULL)
    , CONSTRAINT ck_runtimes_lease_consistency CHECK ((leased_by_worker_id IS NULL AND lease_expires_at_utc IS NULL) OR (leased_by_worker_id IS NOT NULL AND lease_expires_at_utc IS NOT NULL))
    , CONSTRAINT ck_runtimes_counters CHECK (execution_number >= 0 AND failure_count >= 0)
    , CONSTRAINT ck_runtimes_status_lease CHECK (status_code = 50 OR leased_by_worker_id IS NULL)
    , CONSTRAINT ck_runtimes_inflight_leased CHECK (status_code <> 50 OR leased_by_worker_id IS NOT NULL)
    , CONSTRAINT ck_runtimes_ready_due CHECK (status_code <> 10 OR next_run_at_utc IS NOT NULL)
    , CONSTRAINT fk_runtimes_jobs FOREIGN KEY (job_id) REFERENCES acta.jobs (id) ON DELETE CASCADE
    , CONSTRAINT fk_runtimes_lanes FOREIGN KEY (lane_id) REFERENCES acta.lanes (id)
);
CREATE INDEX ix_runtimes_claim_ready ON acta.runtimes (namespace_id, priority_code DESC, next_run_at_utc, job_id, status_code) WHERE status_code IN (10, 20) AND next_run_at_utc IS NOT NULL;
CREATE INDEX ix_runtimes_worker_inflight ON acta.runtimes (leased_by_worker_id, job_id) WHERE leased_by_worker_id IS NOT NULL AND status_code = 50;
CREATE INDEX ix_runtimes_lane ON acta.runtimes (lane_id, job_id) WHERE lane_id IS NOT NULL AND status_code IN (10, 15, 20, 30, 50);
CREATE INDEX ix_runtimes_lane_member ON acta.runtimes (lane_id) WHERE lane_id IS NOT NULL;
END
GO

-- schedules
IF OBJECT_ID(N'acta.schedules', N'U') IS NULL
BEGIN
CREATE TABLE acta.schedules (
    id bigint IDENTITY(1,1) NOT NULL,
    namespace_id int NOT NULL,
    job_id bigint NOT NULL,
    definition_id int NOT NULL,
    name varchar(128) NOT NULL,
    origin_code tinyint NOT NULL,
    expression varchar(128) NOT NULL,
    expression_override varchar(128) NULL,
    expression_effective AS (COALESCE(expression_override, expression)) PERSISTED,
    time_zone_id varchar(128) NOT NULL,
    time_zone_id_override varchar(128) NULL,
    time_zone_id_effective AS (COALESCE(time_zone_id_override, time_zone_id)) PERSISTED,
    expression_kind_code tinyint NOT NULL,
    misfire_strategy_code tinyint NOT NULL,
    next_run_at_utc datetime2(3) NULL,
    last_occurrence_at_utc datetime2(3) NULL,
    status_code tinyint NOT NULL,
    paused_until_utc datetime2(3) NULL,
    description nvarchar(512) NULL,
    reason_message nvarchar(512) NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_schedules PRIMARY KEY (id)
    , CONSTRAINT ck_schedules_paused_pair CHECK (status_code = 30 OR paused_until_utc IS NULL)
    , CONSTRAINT ck_schedules_orphan_origin CHECK (origin_code = 40 OR status_code <> 230)
    , CONSTRAINT fk_schedules_jobs FOREIGN KEY (job_id) REFERENCES acta.jobs (id) ON DELETE CASCADE
    , CONSTRAINT fk_schedules_definitions FOREIGN KEY (definition_id) REFERENCES acta.definitions (id)
);
CREATE INDEX ix_schedules_namespace_next ON acta.schedules (namespace_id, next_run_at_utc, id) WHERE status_code <> 230;
CREATE UNIQUE INDEX ux_schedules_job_name ON acta.schedules (job_id, name);
END
GO

-- steps
IF OBJECT_ID(N'acta.steps', N'U') IS NULL
BEGIN
CREATE TABLE acta.steps (
    id bigint IDENTITY(1,1) NOT NULL,
    job_id bigint NOT NULL,
    name varchar(128) NOT NULL,
    status_code tinyint NOT NULL,
    attempt_number int NOT NULL,
    next_retry_at_utc datetime2(3) NULL,
    reason_code tinyint NULL,
    reason_message nvarchar(512) NULL,
    result_format_id tinyint NOT NULL,
    result varbinary(max) NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_steps PRIMARY KEY (id)
    , CONSTRAINT ck_steps_result_pair CHECK ((result_format_id = 0 AND result IS NULL) OR (result_format_id <> 0 AND result IS NOT NULL))
    , CONSTRAINT ck_steps_attempt_number CHECK (attempt_number >= 1)
    , CONSTRAINT ck_steps_terminal_no_retry CHECK (status_code NOT IN (100, 200, 230) OR next_retry_at_utc IS NULL)
    , CONSTRAINT ck_steps_result_succeeded CHECK (result_format_id = 0 OR status_code = 100)
    , CONSTRAINT ck_steps_reason_pair CHECK (reason_message IS NULL OR reason_code IS NOT NULL)
    , CONSTRAINT fk_steps_jobs FOREIGN KEY (job_id) REFERENCES acta.jobs (id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX ux_steps_job_name ON acta.steps (job_id, name);
END
GO

-- tags
IF OBJECT_ID(N'acta.tags', N'U') IS NULL
BEGIN
CREATE TABLE acta.tags (
    scope_code tinyint NOT NULL,
    scope_id bigint NOT NULL,
    namespace_id int NULL,
    name varchar(128) NOT NULL,
    value nvarchar(128) NULL,
    value_search nvarchar(128) NULL
    , CONSTRAINT pk_tags PRIMARY KEY (scope_code, scope_id, name)
    , CONSTRAINT ck_tags_scope_id CHECK (scope_id > 0)
    , CONSTRAINT ck_tags_namespace_id CHECK (namespace_id IS NULL OR namespace_id > 0)
    , CONSTRAINT ck_tags_scope_namespace CHECK ((scope_code = 20 AND namespace_id IS NULL) OR (scope_code = 30 AND namespace_id IS NOT NULL AND scope_id = namespace_id) OR (scope_code IN (40, 50, 60, 70, 80, 90) AND namespace_id IS NOT NULL))
    , CONSTRAINT ck_tags_value_search CHECK ((value IS NULL AND value_search IS NULL) OR (value IS NOT NULL AND value_search IS NOT NULL))
);
CREATE INDEX ix_tags_namespace_name_value_search ON acta.tags (namespace_id, name, value_search, scope_code, scope_id);
END
