-- workers
IF OBJECT_ID(N'acta.workers', N'U') IS NULL
BEGIN
CREATE TABLE acta.workers (
    id int IDENTITY(1,1) NOT NULL,
    worker_ref uniqueidentifier NOT NULL,
    namespace_id int NOT NULL,
    status_code tinyint NOT NULL,
    deployment_version varchar(128) NOT NULL,
    host varchar(256) NOT NULL,
    engine_version varchar(128) NULL,
    dotnet_version varchar(64) NULL,
    process_id int NULL,
    max_concurrency int NOT NULL,
    last_seen_at_utc datetime2(3) NOT NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_workers PRIMARY KEY (id)
    , CONSTRAINT ck_workers_max_concurrency CHECK (max_concurrency > 0)
    , CONSTRAINT fk_workers_namespaces FOREIGN KEY (namespace_id) REFERENCES acta.namespaces (id)
);
CREATE INDEX ix_workers_namespace_status_last_seen ON acta.workers (namespace_id, status_code, last_seen_at_utc);
CREATE INDEX ix_workers_status_last_seen ON acta.workers (status_code, last_seen_at_utc);
CREATE INDEX ix_workers_namespace_last_seen ON acta.workers (namespace_id, last_seen_at_utc DESC, id DESC);
CREATE UNIQUE INDEX ux_workers_ref ON acta.workers (worker_ref);
END
GO

-- checkpoints
IF OBJECT_ID(N'acta.checkpoints', N'U') IS NULL
BEGIN
CREATE TABLE acta.checkpoints (
    job_id bigint NOT NULL,
    kind_code tinyint NOT NULL,
    name varchar(128) NOT NULL,
    status_code tinyint NULL,
    due_at_utc datetime2(3) NULL,
    value_format_id tinyint DEFAULT 0 NOT NULL,
    value varbinary(max) NULL,
    created_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    modified_at_utc datetime2(3) DEFAULT SYSUTCDATETIME() NOT NULL,
    version int DEFAULT 0 NOT NULL
    , CONSTRAINT pk_checkpoints PRIMARY KEY (job_id, kind_code, name)
    , CONSTRAINT ck_checkpoints_value_pair CHECK ((value_format_id = 0 AND value IS NULL) OR (value_format_id <> 0 AND value IS NOT NULL))
    , CONSTRAINT ck_checkpoints_kind_shape CHECK ((kind_code IN (10, 40) AND status_code IS NULL AND due_at_utc IS NULL) OR (kind_code IN (20, 50) AND status_code IS NOT NULL AND status_code IN (10, 20, 30)) OR (kind_code = 30 AND status_code IS NOT NULL AND status_code IN (10, 100) AND due_at_utc IS NOT NULL))
    , CONSTRAINT fk_checkpoints_jobs FOREIGN KEY (job_id) REFERENCES acta.jobs (id) ON DELETE CASCADE
);
END
GO

-- TVP table types used by hot-path routines + their batched parameters.

-- Per-row enqueue batch: one row per Job to enqueue (1..5000 per call).
-- Consumed by acta.enqueue_jobs's @p_batch sproc parameter.
IF TYPE_ID(N'acta.enqueue_jobs_batch') IS NULL
EXEC(N'CREATE TYPE acta.enqueue_jobs_batch AS TABLE (
    ordinal           INT              NOT NULL,
    job_ref           UNIQUEIDENTIFIER NOT NULL,
    namespace_name    VARCHAR(128)     NOT NULL,
    job_name          VARCHAR(128)     NOT NULL,
    deduplication_key        VARCHAR(128)     COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    correlation_key    VARCHAR(64)      NULL,
    priority_override TINYINT          NULL,
    input_format_id   TINYINT          NOT NULL,
    input             VARBINARY(MAX)   NULL,
    concurrency_key   VARCHAR(128)     COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    next_run_at_utc   DATETIME2(3)     NULL,
    delay_seconds     INT              NULL,
    parent_id         BIGINT           NULL,
    tenant_name       VARCHAR(128)     NULL,
    tenant_override   BIT              NOT NULL,
    lane              VARCHAR(128)     NULL,
    PRIMARY KEY (ordinal)
);');
GO

-- Per-tag enqueue batch: zero-or-more rows per Job, joined to the main batch by ordinal.
-- Consumed by the @p_tag_batch sproc parameter of acta.enqueue_jobs and acta.enqueue_job.
IF TYPE_ID(N'acta.enqueue_tags_batch') IS NULL
EXEC(N'CREATE TYPE acta.enqueue_tags_batch AS TABLE (
    ordinal INT          NOT NULL,
    name    VARCHAR(128) NOT NULL,
    value   NVARCHAR(128) NULL,
    value_search NVARCHAR(128) NULL,
    PRIMARY KEY (ordinal, name)
);');
GO

-- Per-completion batch: one row per completion by one worker, whose id is a scalar.
-- Consumed by acta.complete_executions's @p_batch sproc parameter, which joins it by its key.
IF TYPE_ID(N'acta.complete_executions_batch') IS NULL
EXEC(N'CREATE TYPE acta.complete_executions_batch AS TABLE (
    job_id                   BIGINT         NOT NULL,
    execution_number         INT            NOT NULL,
    succeeded                BIT            NOT NULL,
    result_format_id         TINYINT        NOT NULL,
    result                   VARBINARY(MAX) NULL,
    reason_code              TINYINT        NULL,
    reason_message           NVARCHAR(512)  NULL,
    duration_ms              INT            NULL,
    failure_count            INT            NULL,
    retention_seconds        INT            NULL,
    reschedule_status_code   TINYINT        NULL,
    reschedule_delay_seconds INT            NULL,
    reschedule_resume_at_utc DATETIME2(3)   NULL,
    wait_signal_name         NVARCHAR(128)  NULL,
    handler_status_code      TINYINT        NULL,
    final_status             TINYINT        NULL,
    job_next_run_at_utc      DATETIME2(3)   NULL,
    recurring_result_cap     INT            NULL,
    PRIMARY KEY (job_id, execution_number)
);');
GO

-- Per-definition registration batch: one row per [Job] descriptor under a single namespace.
-- Consumed by acta.register_definitions's @p_definitions sproc parameter (one round trip per
-- worker regardless of definition count). name is the per-namespace natural key.
IF TYPE_ID(N'acta.register_definitions_batch') IS NULL
EXEC(N'CREATE TYPE acta.register_definitions_batch AS TABLE (
    name                                 VARCHAR(128)  NOT NULL,
    priority_code                        TINYINT       NOT NULL,
    max_attempts                         INT           NOT NULL,
    concurrency_limit                    INT           NULL,
    rate_limit                           VARCHAR(16)   NULL,
    rate_name                            VARCHAR(128)  NULL,
    backoff                              NVARCHAR(64)  NOT NULL,
    execution_timeout_seconds            INT           NOT NULL,
    deadline_seconds                     INT           NOT NULL,
    deadline_behavior_code               TINYINT       NOT NULL,
    retention_seconds                    INT           NOT NULL,
    input_type_name                      VARCHAR(512)  NOT NULL,
    output_type_name                     VARCHAR(512)  NULL,
    input_format_id                      TINYINT       NOT NULL,
    input_format_name                    VARCHAR(128)  NOT NULL,
    output_format_id                     TINYINT       NOT NULL,
    output_format_name                   VARCHAR(128)  NOT NULL,
    audit_level_code                     TINYINT       NOT NULL,
    alert_profile_code                   TINYINT       NOT NULL,
    alert_channel_name                   VARCHAR(128)  NULL,
    runbook_url                          VARCHAR(512)  NULL,
    display_name                         NVARCHAR(128) NULL,
    description                          NVARCHAR(512) NULL,
    definition_hash                      VARCHAR(128)  NOT NULL,
    tenant_requirement_code              TINYINT       NOT NULL,
    lane                                 VARCHAR(128)  NULL,
    PRIMARY KEY (name)
);');
GO

-- Per-definition recurring slot batch: one row per definition reconciled in a single
-- acta.register_schedules call (all definitions share one namespace, passed as a scalar).
-- deduplication_key is the slot job's natural key (the job name).
IF TYPE_ID(N'acta.register_slots_batch') IS NULL
EXEC(N'CREATE TYPE acta.register_slots_batch AS TABLE (
    definition_id    INT              NOT NULL PRIMARY KEY,
    job_ref              UNIQUEIDENTIFIER NOT NULL,
    deduplication_key           VARCHAR(128)     COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL,
    input_format_id      TINYINT        NOT NULL,
    input                VARBINARY(MAX) NULL,
    audit_level_code     TINYINT        NOT NULL,
    slot_status_code     TINYINT        NOT NULL,
    slot_next_run_at_utc DATETIME2(3)   NULL
);');
GO

-- All definitions' reconciled schedules for one acta.register_schedules call, tagged with
-- definition_id so each schedule links to its definition's slot. next_run_at_utc is the
-- C#-computed cursor; description is the optional operator note.
IF TYPE_ID(N'acta.register_schedules_batch') IS NULL
EXEC(N'CREATE TYPE acta.register_schedules_batch AS TABLE (
    definition_id             INT          NOT NULL,
    name                          VARCHAR(128) NOT NULL,
    expression                    VARCHAR(128) NOT NULL,
    time_zone_id                  VARCHAR(128) NOT NULL,
    expression_kind_code          TINYINT      NOT NULL,
    misfire_strategy_code         TINYINT      NOT NULL,
    next_run_at_utc               DATETIME2(3) NULL,
    description                   NVARCHAR(512) NULL,
    PRIMARY KEY (definition_id, name)
);');
GO

CREATE OR ALTER PROCEDURE acta.access_checkpoint
    @p_action SMALLINT,
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        IF
            @p_action IN (10 /* AccessCheckpointAction.Set */, 30 /* AccessCheckpointAction.GetOrSet */)
            AND (@p_value_format_id = 0 /* JobPayloadFormat.None */ OR @p_value IS NULL)
            THROW 50002, 'Variable payload must use a non-zero format id and non-NULL value.', 1;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @row TABLE (
            found INT NOT NULL,
            value_format_id TINYINT NULL,
            value VARBINARY(MAX) NULL,
            version INT NULL
        );

        IF @p_action = 10 /* AccessCheckpointAction.Set */
            BEGIN

                UPDATE jv
                SET
                    value_format_id = @p_value_format_id,
                    value = @p_value,
                    modified_at_utc = @now,
                    version = version + 1
                FROM acta.checkpoints AS jv WITH (UPDLOCK, HOLDLOCK)
                WHERE
                    jv.job_id = @p_job_id
                    AND jv.kind_code = @p_kind_code
                    AND jv.name = @p_name;

                IF @@ROWCOUNT = 0
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name,
                            value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name,
                            @p_value_format_id, @p_value,
                            @now, @now, 0
                        );
                    END

                INSERT INTO @row (found, value_format_id, value, version) VALUES (1, NULL, NULL, NULL);
            END
        ELSE IF @p_action = 20 /* AccessCheckpointAction.Get */
            BEGIN
                INSERT INTO @row (found, value_format_id, value, version)
                SELECT
                    1,
                    jv.value_format_id,
                    jv.value,
                    jv.version
                FROM acta.checkpoints AS jv
                WHERE
                    jv.job_id = @p_job_id
                    AND jv.kind_code = @p_kind_code
                    AND jv.name = @p_name;

                IF @@ROWCOUNT = 0
                    BEGIN
                        INSERT INTO @row (found, value_format_id, value, version) VALUES (0, NULL, NULL, NULL);
                    END
            END
        ELSE IF @p_action = 30 /* AccessCheckpointAction.GetOrSet */
            BEGIN

                INSERT INTO @row (found, value_format_id, value, version)
                SELECT
                    1,
                    jv.value_format_id,
                    jv.value,
                    jv.version
                FROM acta.checkpoints AS jv WITH (UPDLOCK, HOLDLOCK)
                WHERE
                    jv.job_id = @p_job_id
                    AND jv.kind_code = @p_kind_code
                    AND jv.name = @p_name;

                IF @@ROWCOUNT = 0
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name,
                            value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name,
                            @p_value_format_id, @p_value,
                            @now, @now, 0
                        );

                        INSERT INTO @row (found, value_format_id, value, version)
                        VALUES (1, @p_value_format_id, @p_value, 0);
                    END

            END
        ELSE IF @p_action = 40 /* AccessCheckpointAction.Exists */
            BEGIN
                INSERT INTO @row (found, value_format_id, value, version)
                SELECT
                    CASE WHEN EXISTS (
                        SELECT 1
                        FROM acta.checkpoints AS jv
                        WHERE
                            jv.job_id = @p_job_id
                            AND jv.kind_code = @p_kind_code
                            AND jv.name = @p_name
                    ) THEN 1 ELSE 0 END,
                    NULL,
                    NULL,
                    NULL;
            END
        ELSE IF @p_action = 50 /* AccessCheckpointAction.Delete */
            BEGIN
                DELETE FROM acta.checkpoints
                WHERE
                    job_id = @p_job_id
                    AND kind_code = @p_kind_code
                    AND name = @p_name;

                INSERT INTO @row (found, value_format_id, value, version)
                VALUES (CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END, NULL, NULL, NULL);
            END
        ELSE
            BEGIN
                THROW 50002, 'access_checkpoint received an unknown action.', 1;
            END

        SELECT
            found,
            value_format_id,
            value,
            version
        FROM @row;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.arm_or_consume_sleep_timer
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_delay_seconds INT = NULL,
    @p_resume_at_utc DATETIME2(3) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
        DECLARE @due DATETIME2(3) = COALESCE(@p_resume_at_utc, DATEADD(SECOND, @p_delay_seconds, @now));
        DECLARE @outcome SMALLINT;
        DECLARE @result_due DATETIME2(3) = NULL;
        DECLARE @existing_state TINYINT;
        DECLARE @existing_due DATETIME2(3);
        DECLARE @lock_id BIGINT;

        SELECT @lock_id = job_id
        FROM acta.runtimes WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id;

        SELECT
            @existing_state = status_code,
            @existing_due = due_at_utc
        FROM acta.checkpoints
        WHERE
            job_id = @p_job_id
            AND kind_code = 30 /* CheckpointKindCode.Timer */
            AND name = @p_name;

        IF @existing_state = 10 /* CheckpointStatusCode.Pending */ AND @existing_due > @now
            BEGIN

                SET @outcome = 1 /* ArmOrConsumeSleepTimerOutcomeCode.Suspend */;
                SET @result_due = @existing_due;
            END
        ELSE IF @existing_state = 10 /* CheckpointStatusCode.Pending */
            BEGIN

                UPDATE acta.checkpoints
                SET
                    status_code = 100 /* CheckpointStatusCode.Consumed */,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND kind_code = 30 /* CheckpointKindCode.Timer */ AND name = @p_name;

                /* Only the worker still executing may clear the instant. A reclaimed row is Ready again
                   on an instant the reclaim owns, and ck_runtimes_ready_due requires Ready to keep one. */
                UPDATE acta.runtimes
                SET
                    next_run_at_utc = NULL,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND status_code = 50 /* JobStatusCode.Executing */;

                SET @outcome = 2 /* ArmOrConsumeSleepTimerOutcomeCode.Continue */;
            END
        ELSE IF @existing_state IS NOT NULL
            BEGIN

                SET @outcome = 2 /* ArmOrConsumeSleepTimerOutcomeCode.Continue */;
            END
        ELSE IF @due <= @now
            BEGIN

                SET @outcome = 2 /* ArmOrConsumeSleepTimerOutcomeCode.Continue */;
            END
        ELSE IF
            EXISTS (
                SELECT 1 FROM acta.checkpoints
                WHERE
                    job_id = @p_job_id AND kind_code = 30 /* CheckpointKindCode.Timer */ AND status_code = 10
            /* CheckpointStatusCode.Pending */
            )
            BEGIN
                SET @outcome = 3 /* ArmOrConsumeSleepTimerOutcomeCode.Reject */;
            END
        ELSE
            BEGIN
                INSERT INTO acta.checkpoints (
                    job_id, kind_code, name, status_code, due_at_utc,
                    created_at_utc, modified_at_utc, version
                )
                VALUES (
                    @p_job_id, 30 /* CheckpointKindCode.Timer */, @p_name, 10 /* CheckpointStatusCode.Pending */, @due,
                    @now, @now, 0
                );

                SET @outcome = 1 /* ArmOrConsumeSleepTimerOutcomeCode.Suspend */;
                SET @result_due = @due;
            END

        SELECT
            @outcome AS outcome_code,
            @result_due AS due_at_utc;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.claim_jobs
    @p_namespace_id INT,
    @p_leased_by_worker_id INT,
    @p_claim_limit INT,
    @p_lease_ttl_seconds INT,
    @p_excluded_definition_ids NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @lease_expires DATETIME2(3) = DATEADD(SECOND, @p_lease_ttl_seconds, @now);
        /* Dueness compares at the column's DATETIME2(3) precision: enqueue rounds next_run_at_utc up to
           0.5 ms into the future, so a full-precision @now can transiently see a just-enqueued row as
           not yet due. Rounding is monotonic, so the same-precision comparison never can. */
        DECLARE @due_now DATETIME2(3) = @now;

        /* Rolling-deploy exclusion: the definitions this worker already bounced for want of a handler,
           passed as JSON array text. Expanded once here so neither the claim nor the horizon pays for
           OPENJSON per row, and counted so the healthy fleet's empty set short-circuits both. */
        DECLARE @excluded TABLE (definition_id INT NOT NULL PRIMARY KEY);
        IF @p_excluded_definition_ids IS NOT NULL
            INSERT INTO @excluded (definition_id)
            SELECT CAST(value AS INT) FROM OPENJSON(@p_excluded_definition_ids);
        DECLARE @excluded_count INT = (SELECT COUNT(*) FROM @excluded);

        DECLARE
            @claimed TABLE
            (
                id BIGINT NOT NULL PRIMARY KEY,
                job_ref UNIQUEIDENTIFIER NOT NULL,
                namespace_id INT NOT NULL,
                lineage_root_id BIGINT NULL,
                definition_id INT NOT NULL,
                tenant_id INT NULL,
                execution_number INT NOT NULL,
                deduplication_key VARCHAR(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
                correlation_key VARCHAR(64) NULL,
                concurrency_key VARCHAR(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
                input_format_id TINYINT NOT NULL,
                input VARBINARY(MAX) NULL,
                next_run_at_utc DATETIME2(3) NULL,
                created_at_utc DATETIME2(3) NOT NULL,
                audit_level_code TINYINT NOT NULL,
                failure_count INT NOT NULL,
                from_status TINYINT NOT NULL,
                lane_id BIGINT NULL,
                parent_id BIGINT NULL
            );

        /* Every JobPriorityCode, listed once: the claim seeks each band in turn and the horizon reads each band's head. */
        DECLARE @bands TABLE (priority_code TINYINT NOT NULL PRIMARY KEY);
        INSERT INTO @bands (priority_code)
        VALUES
            (100 /* JobPriorityCode.Realtime */),
            (85 /* JobPriorityCode.Critical */),
            (70 /* JobPriorityCode.High */),
            (50 /* JobPriorityCode.Normal */),
            (0 /* JobPriorityCode.Bulk */);

        DECLARE @candidates TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @remaining INT = @p_claim_limit;
        DECLARE @band TINYINT = (SELECT MAX(priority_code) FROM @bands);

        /* One seek per band, highest band first, each stopping at the band's first row not yet due. The
           UPDLOCK holds every candidate to the end of the transaction, so the update below finds each one
           as this loop left it. */
        WHILE @band IS NOT NULL AND @remaining > 0
            BEGIN
                /* Pure claim-index seek on ix_runtimes_claim_ready via the denormalized namespace; concurrency-key admission is
                   executor-owned (lock store) after the start CAS, and the one jobs lookup is the exclusion below. */
                INSERT INTO @candidates (id)
                SELECT TOP (@remaining) r.job_id
                FROM acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, READCOMMITTEDLOCK)
                WHERE
                    r.namespace_id = @p_namespace_id
                    AND r.priority_code = @band
                    /* ix_runtimes_claim_ready's filter restated whole: filtered-index matching takes top-level AND-terms
                       only, and without it the claim scans runtimes and widens its UPDLOCK footprint to match. Ready always
                       carries its due instant (ck_runtimes_ready_due); a Suspended NULL never comes due. */
                    AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */)
                    AND r.next_run_at_utc IS NOT NULL
                    AND r.next_run_at_utc <= @due_now
                    /* Empty on a healthy fleet, so the count test settles it before the jobs lookup and
                       the seek above stays as it was. */
                    AND (
                        @excluded_count = 0
                        OR NOT EXISTS (
                            SELECT 1
                            FROM acta.jobs j
                            WHERE j.id = r.job_id AND j.definition_id IN (SELECT e.definition_id FROM @excluded e)
                        )
                    )
                ORDER BY
                    r.next_run_at_utc ASC,
                    r.job_id ASC;

                SET @remaining -= @@ROWCOUNT;
                SET @band = (SELECT MAX(priority_code) FROM @bands WHERE priority_code < @band);
            END

        UPDATE r
        SET
            status_code = 50 /* JobStatusCode.Executing */,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = @p_leased_by_worker_id,
            lease_expires_at_utc = @lease_expires,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id,
            j.job_ref,
            j.namespace_id,
            j.lineage_root_id,
            j.definition_id,
            j.tenant_id,
            INSERTED.execution_number,
            j.deduplication_key,
            j.correlation_key,
            j.concurrency_key,
            j.input_format_id,
            j.input,
            INSERTED.next_run_at_utc,
            j.created_at_utc,
            j.audit_level_code,
            INSERTED.failure_count,
            DELETED.status_code,
            INSERTED.lane_id,
            j.parent_id
        INTO
            @claimed (
                id, job_ref, namespace_id, lineage_root_id, definition_id, tenant_id, execution_number,
                deduplication_key, correlation_key, concurrency_key,
                input_format_id, input, next_run_at_utc, created_at_utc,
                audit_level_code, failure_count, from_status, lane_id, parent_id
            )
        -- FORCESEEK keeps this update on a key seek instead of a lock-escalating scan of runtimes. The seek above holds
        -- claim-index keys, so READPAST skips a row a verb holds instead of waiting for it, which would invert the lock
        -- order (docs/internals/sql-execution-policy.md); a skipped candidate is simply not claimed.
        FROM acta.runtimes r WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK, READPAST)
        INNER JOIN @candidates c ON c.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            40 /* EventCode.JobExecutionStarted */,
            @now,
            c.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            c.id,
            c.job_ref,
            c.execution_number,
            COALESCE(c.lineage_root_id, c.id),
            c.definition_id,
            c.tenant_id,
            @p_leased_by_worker_id,
            c.from_status,
            50 /* JobStatusCode.Executing */,
            50 /* ExecutionStatusCode.Executing */,
            NULL,
            NULL,
            NULL
        FROM @claimed c
        WHERE c.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */;

        IF EXISTS (SELECT 1 FROM @claimed)
            BEGIN
                SELECT
                    id,
                    namespace_id,
                    definition_id,
                    execution_number,
                    deduplication_key,
                    correlation_key,
                    concurrency_key,
                    input_format_id,
                    input,
                    next_run_at_utc,
                    @lease_expires AS lease_expires_at_utc,
                    created_at_utc,
                    failure_count,
                    job_ref,
                    tenant_id,
                    CAST(NULL AS DATETIME2(7)) AS db_now,
                    CAST(NULL AS DATETIME2(3)) AS next_ready_at_utc,
                    lane_id,
                    parent_id
                FROM @claimed
                ORDER BY id;
            END
        ELSE
            BEGIN
                SELECT
                    CAST(NULL AS BIGINT) AS id,
                    CAST(NULL AS INT) AS namespace_id,
                    CAST(NULL AS INT) AS definition_id,
                    CAST(NULL AS INT) AS execution_number,
                    CAST(NULL AS VARCHAR(128)) AS deduplication_key,
                    CAST(NULL AS VARCHAR(64)) AS correlation_key,
                    CAST(NULL AS VARCHAR(128)) AS concurrency_key,
                    CAST(NULL AS TINYINT) AS input_format_id,
                    CAST(NULL AS VARBINARY(MAX)) AS input,
                    CAST(NULL AS DATETIME2(3)) AS next_run_at_utc,
                    CAST(NULL AS DATETIME2(3)) AS lease_expires_at_utc,
                    CAST(NULL AS DATETIME2(3)) AS created_at_utc,
                    CAST(NULL AS INT) AS failure_count,
                    CAST(NULL AS UNIQUEIDENTIFIER) AS job_ref,
                    CAST(NULL AS INT) AS tenant_id,
                    @now AS db_now,
                    /* The earliest head across the bands: each band's first index row is its earliest instant. */
                    (
                        SELECT MIN(head.next_run_at_utc)
                        FROM @bands b
                        CROSS APPLY (
                            SELECT TOP (1) r.next_run_at_utc
                            FROM acta.runtimes r
                            WHERE
                                r.namespace_id = @p_namespace_id
                                AND r.priority_code = b.priority_code
                                AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */)
                                AND r.next_run_at_utc IS NOT NULL
                                /* Excluded rows are invisible to this worker's horizon too: a horizon at or
                                   before now is what tells the caller to retry at the anti-spin floor, so
                                   counting rows this worker will never claim would spin it. */
                                AND (
                                    @excluded_count = 0
                                    OR NOT EXISTS (
                                        SELECT 1
                                        FROM acta.jobs j
                                        WHERE j.id = r.job_id AND j.definition_id IN (SELECT e.definition_id FROM @excluded e)
                                    )
                                )
                            ORDER BY r.next_run_at_utc ASC
                        ) head
                    ) AS next_ready_at_utc,
                    CAST(NULL AS BIGINT) AS lane_id,
                    CAST(NULL AS BIGINT) AS parent_id;
            END

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.complete_executions
    @p_leased_by_worker_id INT,
    @p_batch acta.complete_executions_batch READONLY,
    @p_plain BIT = 0,
    @p_schedule_advances NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @locked INT, @lanes BIT = 0, @children BIT = 0, @waits BIT = 0, @shapes BIT = 0, @recurring BIT = 0;
        DECLARE @rows TABLE (
            job_id BIGINT NOT NULL,
            execution_number INT NOT NULL,
            lane_id BIGINT NULL,
            parent_id BIGINT NULL,
            sig_state TINYINT NULL,
            sig_due DATETIME2(3) NULL,
            PRIMARY KEY (job_id, execution_number)
        );
        DECLARE @done TABLE (
            job_id BIGINT NOT NULL PRIMARY KEY,
            execution_number INT NOT NULL,
            status_code TINYINT NOT NULL,
            lane_id BIGINT NULL,
            parent_id BIGINT NULL,
            slot_wake DATETIME2(3) NULL,
            parent_released BIT NOT NULL DEFAULT 0,
            lane_promoted BIT NOT NULL DEFAULT 0
        );

        /* Each step is skipped when no row needs it, and a plain batch (the binder marks one with no shape, lane, or parent)
           reads no lane or parent and skips them all. Locks: lanes, awaited slots, own runtimes, schedules, parent latches and runtimes,
           each in key order (docs/internals/sql-execution-policy.md, "Lane lock order"); lane_id and parent_id never change. */
        IF @p_plain = 1
            INSERT INTO @rows (job_id, execution_number)
            SELECT c.job_id, c.execution_number
            FROM @p_batch c;
        ELSE
            INSERT INTO @rows (job_id, execution_number, lane_id, parent_id)
            SELECT c.job_id, c.execution_number, r.lane_id, j.parent_id
            FROM @p_batch c
            INNER JOIN acta.runtimes r ON r.job_id = c.job_id
            INNER JOIN acta.jobs j ON j.id = c.job_id;

        IF @p_plain = 0
            BEGIN
            SELECT
                @lanes = MAX(CASE WHEN lane_id IS NOT NULL THEN 1 ELSE 0 END),
                @children = MAX(CASE WHEN parent_id IS NOT NULL THEN 1 ELSE 0 END)
            FROM @rows;

            SELECT
                @waits = MAX(CASE WHEN wait_signal_name IS NOT NULL THEN 1 ELSE 0 END),
                @shapes = MAX(
                    CASE WHEN reschedule_status_code IS NOT NULL OR handler_status_code IS NOT NULL OR final_status IS NOT NULL THEN 1 ELSE 0 END
                ),
                @recurring = MAX(CASE WHEN final_status IS NOT NULL THEN 1 ELSE 0 END)
            FROM @p_batch;

            IF @lanes = 1
                BEGIN
                    CREATE TABLE #lanes (id BIGINT NOT NULL PRIMARY KEY);
                    INSERT INTO #lanes (id)
                    SELECT DISTINCT lane_id FROM @rows WHERE lane_id IS NOT NULL;

                    SELECT @locked = COUNT(*)
                    FROM #lanes x
                    INNER JOIN acta.lanes l WITH (UPDLOCK, ROWLOCK, FORCESEEK) ON l.id = x.id
                    OPTION (FORCE ORDER, LOOP JOIN);
                END

            -- The awaited slot is the only place a wait's deadline lives; the lock lets a raise that won the race land the job Ready.
            IF @waits = 1
                UPDATE x
                SET sig_state = s.status_code, sig_due = s.due_at_utc
                FROM @rows x
                INNER JOIN @p_batch c ON c.job_id = x.job_id AND c.execution_number = x.execution_number AND c.wait_signal_name IS NOT NULL
                INNER JOIN acta.checkpoints s WITH (UPDLOCK, HOLDLOCK, FORCESEEK)
                    ON
                        s.job_id = x.job_id
                        AND s.kind_code IN (20 /* CheckpointKindCode.Signal */, 50 /* CheckpointKindCode.ChildLatch */)
                        AND s.name = c.wait_signal_name
                OPTION (FORCE ORDER, LOOP JOIN);
            END

        /* Locks each row by its clustered key in job_id order. A row that re-arms, waits, is held, or fires on a schedule stays
           Executing and leased here and takes its status with its next run below: it enters ix_runtimes_claim_ready once, a
           timer consumed this attempt never meets ck_runtimes_ready_due, and a batch of landings never writes next_run_at_utc. */
        UPDATE r
        SET
            status_code = CASE WHEN s.shaped = 1 THEN r.status_code ELSE s.to_status END,
            failure_count = COALESCE(c.failure_count, r.failure_count),
            leased_by_worker_id = CASE WHEN s.shaped = 1 THEN r.leased_by_worker_id END,
            lease_expires_at_utc = CASE WHEN s.shaped = 1 THEN r.lease_expires_at_utc END,
            retention_until_utc = CASE
                WHEN
                    s.to_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    AND c.retention_seconds IS NOT NULL
                    THEN DATEADD(SECOND, c.retention_seconds, @now)
                ELSE r.retention_until_utc
            END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id, INSERTED.execution_number, s.to_status, x.lane_id, x.parent_id
        INTO @done (job_id, execution_number, status_code, lane_id, parent_id)
        FROM @rows x
        INNER JOIN acta.runtimes r WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK) ON r.job_id = x.job_id
        INNER JOIN @p_batch c ON c.job_id = x.job_id AND c.execution_number = x.execution_number
        CROSS APPLY (
            SELECT CASE
                WHEN c.wait_signal_name IS NOT NULL AND x.sig_state = 20 /* CheckpointStatusCode.Set */ THEN 10 /* JobStatusCode.Ready */
                WHEN c.wait_signal_name IS NOT NULL THEN 20 /* JobStatusCode.Suspended */
                WHEN c.reschedule_status_code IS NOT NULL THEN 10 /* JobStatusCode.Ready */
                WHEN c.handler_status_code IS NOT NULL THEN c.handler_status_code
                WHEN c.final_status IS NOT NULL THEN c.final_status
                WHEN c.succeeded = 1 THEN 100 /* JobStatusCode.Succeeded */
                ELSE 200 /* JobStatusCode.Failed */
            END AS to_status,
            CASE
                WHEN c.reschedule_status_code IS NOT NULL OR c.handler_status_code IS NOT NULL OR c.final_status IS NOT NULL THEN 1
                ELSE 0
            END AS shaped
        ) s
        WHERE
            r.execution_number = x.execution_number
            AND r.status_code = 50 /* JobStatusCode.Executing */
            AND r.leased_by_worker_id = @p_leased_by_worker_id
        OPTION (FORCE ORDER);

        -- A recurring fire takes both in its own step, from the schedules as they stand after the advance.
        IF @shapes = 1
            UPDATE r
            SET
                status_code = d.status_code,
                leased_by_worker_id = NULL,
                lease_expires_at_utc = NULL,
                next_run_at_utc = CASE
                    WHEN c.wait_signal_name IS NOT NULL AND x.sig_state = 20 /* CheckpointStatusCode.Set */ THEN @now
                    WHEN c.wait_signal_name IS NOT NULL THEN x.sig_due
                    WHEN c.reschedule_status_code IS NOT NULL
                        THEN COALESCE(c.reschedule_resume_at_utc, DATEADD(SECOND, c.reschedule_delay_seconds, @now))
                    -- A handler's pause keeps a next run, which marks it held (ScheduleWalker, "held").
                    WHEN c.handler_status_code = 30 /* JobStatusCode.Paused */ THEN @now
                    ELSE NULL
                END
            FROM @done d
            INNER JOIN @rows x ON x.job_id = d.job_id AND x.execution_number = d.execution_number
            INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
            INNER JOIN acta.runtimes r WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK) ON r.job_id = d.job_id
            WHERE (c.reschedule_status_code IS NOT NULL OR c.handler_status_code IS NOT NULL) AND c.final_status IS NULL;

        -- fk_results_jobs seeks each job by key (docs/internals/sql-execution-policy.md, "Foreign keys in set-based writes").
        INSERT INTO acta.results (job_id, execution_number, result_format_id, result, created_at_utc)
        SELECT d.job_id, d.execution_number, c.result_format_id, c.result, @now
        FROM @done d
        INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
        WHERE c.result_format_id <> 0 /* JobPayloadFormat.None */
        OPTION (LOOP JOIN);

        IF @p_plain = 0
            BEGIN
            IF @recurring = 1
                BEGIN
                    /* A fire advances its schedules: an edit made while it ran wins over the older plan, an operator pause
                       wins unless it was timed and has elapsed, and an orphaned schedule is left alone. The audit insert
                       shares the update's predicate, so the two agree. */
                    INSERT INTO acta.events (
                        event_code, created_at_utc, namespace_id,
                        actor_code, actor,
                        job_id, job_ref, execution_number,
                        lineage_root_id, definition_id, tenant_id,
                        worker_id,
                        from_status_code, to_status_code,
                        execution_status_code, duration_ms,
                        reason_code, reason_message
                    )
                    SELECT
                        102 /* EventCode.SchedulePauseExpired */, @now, j.namespace_id,
                        10 /* ActorCode.Sys */, NULL,
                        d.job_id, j.job_ref, d.execution_number,
                        COALESCE(j.lineage_root_id, d.job_id), j.definition_id, j.tenant_id,
                        NULL,
                        NULL, NULL,
                        NULL, NULL,
                        NULL, js.name
                    FROM OPENJSON(@p_schedule_advances) WITH (
                        schedule_id BIGINT '$.schedule_id', next_run_at_utc DATETIME2(3) '$.next_run_at_utc', expected_version INT '$.expected_version'
                    ) adv
                    INNER JOIN acta.schedules js ON js.id = adv.schedule_id
                    INNER JOIN @done d ON d.job_id = js.job_id
                    INNER JOIN acta.jobs j ON j.id = d.job_id
                    WHERE
                        (adv.expected_version IS NULL OR js.version = adv.expected_version)
                        AND j.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */
                        AND js.status_code = 30 /* ScheduleStatusCode.Paused */
                        AND js.paused_until_utc IS NOT NULL
                        AND js.paused_until_utc <= @now;

                    UPDATE js
                    SET
                        js.next_run_at_utc = adv.next_run_at_utc,
                        js.last_occurrence_at_utc = js.next_run_at_utc,
                        js.status_code = 10 /* ScheduleStatusCode.Active */,
                        js.paused_until_utc = NULL,
                        js.modified_at_utc = @now,
                        js.version = js.version + 1
                    FROM OPENJSON(@p_schedule_advances) WITH (
                        schedule_id BIGINT '$.schedule_id', next_run_at_utc DATETIME2(3) '$.next_run_at_utc', expected_version INT '$.expected_version'
                    ) adv
                    INNER JOIN acta.schedules js ON js.id = adv.schedule_id
                    INNER JOIN @done d ON d.job_id = js.job_id
                    WHERE
                        (adv.expected_version IS NULL OR js.version = adv.expected_version)
                        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
                        AND (
                            js.status_code <> 30 /* ScheduleStatusCode.Paused */
                            OR (js.paused_until_utc IS NOT NULL AND js.paused_until_utc <= @now)
                        );

                    -- The slot's next state is read from the schedules as they stand now, not from the plan made before the handler ran.
                    UPDATE d
                    SET
                        d.status_code = CASE WHEN w.wake IS NULL THEN 30 /* JobStatusCode.Paused */ ELSE 10 /* JobStatusCode.Ready */ END,
                        d.slot_wake = w.wake
                    FROM @done d
                    INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
                    OUTER APPLY (
                        SELECT
                            MIN(
                                CASE WHEN js.status_code = 30 /* ScheduleStatusCode.Paused */ THEN js.paused_until_utc ELSE js.next_run_at_utc END
                            ) AS wake
                        FROM acta.schedules js
                        WHERE js.job_id = d.job_id AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
                    ) w
                    WHERE c.final_status IS NOT NULL;

                    UPDATE r
                    SET status_code = d.status_code, next_run_at_utc = d.slot_wake, leased_by_worker_id = NULL, lease_expires_at_utc = NULL
                    FROM @done d
                    INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
                    INNER JOIN acta.runtimes r WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK) ON r.job_id = d.job_id
                    WHERE c.final_status IS NOT NULL;

                    DELETE res
                    FROM acta.results res
                    INNER JOIN (
                        SELECT
                            k.job_id,
                            k.execution_number,
                            c.recurring_result_cap AS cap,
                            ROW_NUMBER() OVER (PARTITION BY k.job_id ORDER BY k.execution_number DESC) AS newest
                        FROM @done d
                        INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
                        INNER JOIN acta.results k ON k.job_id = d.job_id
                        WHERE c.final_status IS NOT NULL AND c.recurring_result_cap > 0
                    ) old ON old.job_id = res.job_id AND old.execution_number = res.execution_number
                    WHERE old.newest > old.cap;
                END
            END

        /* At Failures a failure carrying no re-arm or handler hold is written, and a success only when it answers a
           recorded failure, which closes the incident: the job's newest finished event is not a success. One seek on
           the timeline index per row. */
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            41 /* EventCode.JobExecutionFinished */, @now, j.namespace_id,
            70 /* ActorCode.Worker */, NULL,
            d.job_id, j.job_ref, d.execution_number,
            COALESCE(j.lineage_root_id, d.job_id), j.definition_id, j.tenant_id,
            @p_leased_by_worker_id,
            50 /* JobStatusCode.Executing */, d.status_code,
            CASE
                WHEN c.reschedule_status_code IS NOT NULL THEN c.reschedule_status_code
                WHEN c.handler_status_code = 220 /* JobStatusCode.Cancelled */ THEN 220 /* ExecutionStatusCode.Cancelled */
                WHEN c.handler_status_code = 30 /* JobStatusCode.Paused */ THEN 152 /* ExecutionStatusCode.Paused */
                WHEN c.succeeded = 1 THEN 100 /* ExecutionStatusCode.Succeeded */
                ELSE 200 /* ExecutionStatusCode.Failed */
            END,
            c.duration_ms,
            c.reason_code, c.reason_message
        FROM @done d
        INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
        INNER JOIN acta.jobs j ON j.id = d.job_id
        WHERE
            j.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */
            OR (
                j.audit_level_code = 10 /* DefinitionAuditLevelCode.Failures */
                AND c.reschedule_status_code IS NULL
                AND (c.handler_status_code IS NULL OR c.handler_status_code NOT IN (220 /* JobStatusCode.Cancelled */, 30 /* JobStatusCode.Paused */))
                AND (
                    c.succeeded = 0
                    OR COALESCE((
                        SELECT TOP (1) e.execution_status_code FROM acta.events e
                        WHERE e.job_id = d.job_id AND e.event_code = 41 /* EventCode.JobExecutionFinished */
                        ORDER BY e.created_at_utc DESC, e.id DESC), 100) <> 100 /* ExecutionStatusCode.Succeeded */
                )
            );

        IF @p_plain = 0
            BEGIN
            -- At Audit each shape also says what it did: rolled over or paused a recurring slot, re-armed, or held by its handler.
            IF @shapes = 1
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                SELECT
                    k.event_code, @now, j.namespace_id,
                    70 /* ActorCode.Worker */, NULL,
                    d.job_id, j.job_ref, d.execution_number,
                    COALESCE(j.lineage_root_id, d.job_id), j.definition_id, j.tenant_id,
                    @p_leased_by_worker_id,
                    50 /* JobStatusCode.Executing */, d.status_code,
                    NULL, NULL,
                    c.reason_code, c.reason_message
                FROM @done d
                INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
                INNER JOIN acta.jobs j ON j.id = d.job_id
                CROSS APPLY (
                    VALUES
                    (
                        1,
                        CASE
                            WHEN c.final_status IN (10 /* JobStatusCode.Ready */, 30 /* JobStatusCode.Paused */)
                                THEN CASE
                                    WHEN d.status_code = 10 /* JobStatusCode.Ready */ THEN 50 /* EventCode.JobRecurringRolledOver */
                                    ELSE 71 /* EventCode.JobPaused */
                                END
                        END
                    ),
                    (
                        2,
                        -- A wait whose signal had already arrived landed Ready and re-armed nothing.
                        CASE
                            WHEN c.reschedule_status_code IS NOT NULL AND NOT (c.wait_signal_name IS NOT NULL AND d.status_code = 10 /* JobStatusCode.Ready */)
                                THEN CASE
                                    WHEN c.reschedule_status_code = 151 /* ExecutionStatusCode.Suspended */ THEN 60 /* EventCode.JobSuspended */
                                    ELSE 61 /* EventCode.JobRescheduled */
                                END
                        END
                    ),
                    (
                        3,
                        CASE
                            WHEN c.handler_status_code = 220 /* JobStatusCode.Cancelled */ THEN 70 /* EventCode.JobCancelled */
                            WHEN c.handler_status_code = 30 /* JobStatusCode.Paused */ THEN 71 /* EventCode.JobPaused */
                        END
                    )
                ) k (ord, event_code)
                WHERE j.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */ AND k.event_code IS NOT NULL
                ORDER BY d.job_id, k.ord;

            -- A child that landed terminal sets its latch on the parent and wakes a Suspended parent.
            IF @children = 1
                BEGIN
                    CREATE TABLE #parents (
                        parent_id BIGINT NOT NULL,
                        child_id BIGINT NOT NULL,
                        latch_name VARCHAR(128) NOT NULL,
                        envelope VARBINARY(MAX) NOT NULL,
                        reason_code TINYINT NULL,
                        reason_message NVARCHAR(512) NULL,
                        latch_state TINYINT NULL,
                        parent_status TINYINT NULL,
                        parent_execution INT NULL,
                        -- The latches' own key order: the name sorts as text, so child 10 comes before child 9.
                        PRIMARY KEY (parent_id, latch_name)
                    );

                    INSERT INTO #parents (parent_id, child_id, latch_name, envelope, reason_code, reason_message)
                    SELECT
                        d.parent_id,
                        d.job_id,
                        'sys.child.' + CAST(d.job_id AS VARCHAR(20)),
                        CAST(
                            CAST(
                                N'{"childJobId":' + CAST(d.job_id AS NVARCHAR(20)) + N',"status":' + CAST(d.status_code AS NVARCHAR(3)) + N'}'
                                AS VARCHAR(MAX)
                            ) COLLATE latin1_general_100_bin2_utf8 AS VARBINARY(MAX)
                        ),
                        c.reason_code,
                        c.reason_message
                    FROM @done d
                    INNER JOIN @p_batch c ON c.job_id = d.job_id AND c.execution_number = d.execution_number
                    WHERE
                        d.parent_id IS NOT NULL
                        AND d.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

                    UPDATE p
                    SET latch_state = s.status_code
                    FROM #parents p
                    LEFT JOIN acta.checkpoints s WITH (UPDLOCK, HOLDLOCK, FORCESEEK)
                        ON s.job_id = p.parent_id AND s.kind_code = 50 /* CheckpointKindCode.ChildLatch */ AND s.name = p.latch_name
                    OPTION (FORCE ORDER, LOOP JOIN);

                    UPDATE p
                    SET parent_status = pr.status_code, parent_execution = pr.execution_number
                    FROM #parents p
                    INNER JOIN acta.runtimes pr WITH (UPDLOCK, ROWLOCK, FORCESEEK) ON pr.job_id = p.parent_id
                    OPTION (FORCE ORDER, LOOP JOIN);

                    /* No revival: an Expired latch already timed the parent's wait out under this same slot lock, so a later
                       child writes no latch and wakes no one, though the audit event records it. A finished parent takes
                       nothing. */
                    UPDATE s
                    SET
                        status_code = 20 /* CheckpointStatusCode.Set */,
                        value_format_id = 1 /* JobPayloadFormat.Json */,
                        value = p.envelope,
                        modified_at_utc = @now,
                        version = s.version + 1
                    FROM #parents p
                    INNER JOIN acta.checkpoints s WITH (FORCESEEK)
                        ON s.job_id = p.parent_id AND s.kind_code = 50 /* CheckpointKindCode.ChildLatch */ AND s.name = p.latch_name
                    WHERE
                        p.latch_state <> 30 /* CheckpointStatusCode.Expired */
                        AND p.parent_status NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

                    INSERT INTO acta.checkpoints (
                        job_id, kind_code, name, status_code, value_format_id, value,
                        created_at_utc, modified_at_utc, version
                    )
                    SELECT
                        p.parent_id, 50 /* CheckpointKindCode.ChildLatch */, p.latch_name,
                        20 /* CheckpointStatusCode.Set */, 1 /* JobPayloadFormat.Json */, p.envelope,
                        @now, @now, 0
                    FROM #parents p
                    WHERE
                        p.latch_state IS NULL
                        AND p.parent_status NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    OPTION (LOOP JOIN);

                    -- Capped because the caller's message can already sit at the column width.
                    INSERT INTO acta.events (
                        event_code, created_at_utc, namespace_id,
                        actor_code, actor,
                        job_id, job_ref, execution_number,
                        lineage_root_id, definition_id, tenant_id,
                        worker_id,
                        from_status_code, to_status_code,
                        execution_status_code, duration_ms,
                        reason_code, reason_message
                    )
                    SELECT
                        80 /* EventCode.JobSignalRaised */, @now, pj.namespace_id,
                        10 /* ActorCode.Sys */, NULL,
                        p.parent_id, pj.job_ref, p.parent_execution,
                        COALESCE(pj.lineage_root_id, p.parent_id), pj.definition_id, pj.tenant_id,
                        NULL,
                        p.parent_status, p.parent_status,
                        NULL, NULL,
                        p.reason_code,
                        CASE
                            WHEN p.latch_state = 30 /* CheckpointStatusCode.Expired */
                                THEN LEFT(
                                    COALESCE(p.reason_message + N' ', N'') + N'Child outcome not applied: the wait had already expired.',
                                    512
                                )
                            ELSE p.reason_message
                        END
                    FROM #parents p
                    INNER JOIN acta.jobs pj ON pj.id = p.parent_id
                    WHERE
                        pj.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */
                        AND p.parent_status NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    ORDER BY p.parent_id, p.child_id;

                    UPDATE pr
                    SET
                        status_code = 10 /* JobStatusCode.Ready */,
                        next_run_at_utc = @now,
                        modified_at_utc = @now,
                        version = pr.version + 1
                    FROM (
                        SELECT DISTINCT parent_id
                        FROM #parents
                        WHERE
                            parent_status = 20 /* JobStatusCode.Suspended */
                            AND (latch_state IS NULL OR latch_state <> 30 /* CheckpointStatusCode.Expired */)
                    ) w
                    INNER JOIN acta.runtimes pr WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK) ON pr.job_id = w.parent_id
                    WHERE pr.status_code = 20 /* JobStatusCode.Suspended */;

                    INSERT INTO acta.events (
                        event_code, created_at_utc, namespace_id,
                        actor_code, actor,
                        job_id, job_ref, execution_number,
                        lineage_root_id, definition_id, tenant_id,
                        worker_id,
                        from_status_code, to_status_code,
                        execution_status_code, duration_ms,
                        reason_code, reason_message
                    )
                    SELECT
                        72 /* EventCode.JobResumed */, @now, pj.namespace_id,
                        10 /* ActorCode.Sys */, NULL,
                        w.parent_id, pj.job_ref, w.parent_execution,
                        COALESCE(pj.lineage_root_id, w.parent_id), pj.definition_id, pj.tenant_id,
                        NULL,
                        20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */,
                        NULL, NULL,
                        60 /* EventReasonCode.JobSignalReleased */, NULL
                    FROM (
                        SELECT DISTINCT parent_id, parent_execution
                        FROM #parents
                        WHERE
                            parent_status = 20 /* JobStatusCode.Suspended */
                            AND (latch_state IS NULL OR latch_state <> 30 /* CheckpointStatusCode.Expired */)
                    ) w
                    INNER JOIN acta.jobs pj ON pj.id = w.parent_id
                    WHERE pj.audit_level_code = 20 /* DefinitionAuditLevelCode.Audit */;

                    UPDATE d
                    SET parent_released = 1
                    FROM @done d
                    INNER JOIN #parents p ON p.child_id = d.job_id
                    WHERE
                        p.parent_status = 20 /* JobStatusCode.Suspended */
                        AND (p.latch_state IS NULL OR p.latch_state <> 30 /* CheckpointStatusCode.Expired */);
                END

            /* A laned job that finished, or that its handler paused, leaves the lane with no runner: the lowest-id
               unfinished member becomes Ready at its own due instant or now when it is Blocked, and any other head keeps
               the lane. The lane lock taken above makes the read and the write one step. */
            IF @lanes = 1
                BEGIN
                    CREATE TABLE #promoted (lane_id BIGINT NOT NULL PRIMARY KEY);

                    UPDATE m
                    SET
                        status_code = 10 /* JobStatusCode.Ready */,
                        next_run_at_utc = CASE WHEN m.next_run_at_utc > @now THEN m.next_run_at_utc ELSE @now END,
                        modified_at_utc = @now,
                        version = m.version + 1
                    OUTPUT INSERTED.lane_id INTO #promoted (lane_id)
                    FROM (
                        SELECT DISTINCT d.lane_id
                        FROM @done d
                        WHERE
                            d.lane_id IS NOT NULL
                            AND d.status_code IN (
                                30 /* JobStatusCode.Paused */, 100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */,
                                220 /* JobStatusCode.Cancelled */
                            )
                    ) settled
                    CROSS APPLY (
                        SELECT TOP (1) h.job_id, h.status_code
                        FROM acta.runtimes h WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                        WHERE
                            h.lane_id = settled.lane_id
                            AND h.lane_id IS NOT NULL
                            AND h.status_code IN (
                                10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                                30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                            )
                        ORDER BY h.job_id
                    ) head
                    INNER JOIN acta.runtimes m WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK) ON m.job_id = head.job_id
                    WHERE head.status_code = 15 /* JobStatusCode.Blocked */ AND m.status_code = 15 /* JobStatusCode.Blocked */;

                    UPDATE d
                    SET lane_promoted = 1
                    FROM @done d
                    INNER JOIN #promoted p ON p.lane_id = d.lane_id;
                END
            END

        SELECT
            c.job_id,
            c.execution_number,
            CASE
                WHEN d.job_id IS NOT NULL THEN 1 /* CompleteExecutionsAction.Completed */
                WHEN
                    r.status_code IS NULL
                    OR r.status_code IN (
                        100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */
                    )
                    THEN 3 /* CompleteExecutionsAction.AlreadyTerminal */
                WHEN r.leased_by_worker_id IS NULL OR r.leased_by_worker_id <> @p_leased_by_worker_id
                    THEN 2 /* CompleteExecutionsAction.NotOwner */
                ELSE 3 /* CompleteExecutionsAction.AlreadyTerminal */
            END AS action,
            r.status_code AS final_status_code,
            r.next_run_at_utc AS final_next_run_at_utc,
            @now AS db_now,
            CAST(COALESCE(d.parent_released, 0) AS TINYINT) AS parent_released,
            CAST(COALESCE(d.lane_promoted, 0) AS TINYINT) AS lane_promoted
        FROM @p_batch c
        LEFT JOIN @done d ON d.job_id = c.job_id AND d.execution_number = c.execution_number
        LEFT JOIN acta.runtimes r ON r.job_id = c.job_id;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.complete_step
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_succeeded BIT,
    @p_result_format_id TINYINT,
    @p_result VARBINARY(MAX),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512),
    @p_delay_seconds INT,
    @p_max_attempts INT,
    @p_retry_window_seconds INT,
    @p_version INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
        DECLARE @attempt INT;
        DECLARE @created DATETIME2(3);
        DECLARE @next DATETIME2(3);
        DECLARE @outcome SMALLINT;

        SELECT
            @attempt = attempt_number,
            @created = created_at_utc
        FROM acta.steps
        WHERE job_id = @p_job_id AND name = @p_name;

        IF @p_succeeded = 1
            BEGIN
                UPDATE acta.steps
                SET
                    status_code = 100 /* StepStatusCode.Succeeded */,
                    result_format_id = @p_result_format_id,
                    result = @p_result,
                    next_retry_at_utc = NULL,
                    /* A success supersedes any earlier failed attempt, so the row must not keep that attempt's
                       reason: a Succeeded row with a reason reads as a failure to every post-mortem query. */
                    reason_code = NULL,
                    reason_message = NULL,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                IF @@ROWCOUNT = 0
                    SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                ELSE
                    SET @outcome = 1 /* CompleteStepOutcomeCode.Succeeded */;
                SET @next = NULL;
            END
        ELSE
            BEGIN
                SET @next = DATEADD(SECOND, @p_delay_seconds, @now);

                IF
                    @attempt >= @p_max_attempts
                    OR (
                        @p_retry_window_seconds IS NOT NULL
                        AND @next > DATEADD(SECOND, @p_retry_window_seconds, @created)
                    )
                    BEGIN
                        UPDATE acta.steps
                        SET
                            status_code = 200 /* StepStatusCode.Exhausted */,
                            next_retry_at_utc = NULL,
                            reason_code = @p_reason_code,
                            reason_message = @p_reason_message,
                            modified_at_utc = @now,
                            version = version + 1
                        WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                        IF @@ROWCOUNT = 0
                            SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                        ELSE
                            SET @outcome = 3 /* CompleteStepOutcomeCode.Exhausted */;
                        SET @next = NULL;
                    END
                ELSE
                    BEGIN
                        UPDATE acta.steps
                        SET
                            next_retry_at_utc = @next,
                            reason_code = @p_reason_code,
                            reason_message = @p_reason_message,
                            modified_at_utc = @now,
                            version = version + 1
                        WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                        IF @@ROWCOUNT = 0
                            BEGIN
                                SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                                SET @next = NULL;
                            END
                        ELSE
                            SET @outcome = 2 /* CompleteStepOutcomeCode.RetryScheduled */;
                    END
            END

        SELECT
            @outcome AS outcome_code,
            @next AS next_retry_at_utc;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

-- Only @p_namespace_name and @p_job_name are required; other scalars default (@p_job_ref is
-- server-generated when omitted; @p_input_format_id defaults json/none by input presence). The tag TVP
-- has no default (SQL Server TVPs cannot); pass an empty table variable for a tag-free enqueue.
CREATE OR ALTER PROCEDURE acta.enqueue_job
    @p_job_ref UNIQUEIDENTIFIER = NULL,
    @p_namespace_name VARCHAR(128) = NULL,
    @p_job_name VARCHAR(128) = NULL,
    @p_deduplication_key VARCHAR(128) = NULL,
    @p_correlation_key VARCHAR(64) = NULL,
    @p_priority_override TINYINT = NULL,
    @p_input_format_id TINYINT = NULL,
    @p_input VARBINARY(MAX) = NULL,
    @p_concurrency_key VARCHAR(128) = NULL,
    @p_next_run_at_utc DATETIME2(3) = NULL,
    @p_delay_seconds INT = NULL,
    @p_parent_id BIGINT = NULL,
    @p_tenant_name VARCHAR(128) = NULL,
    @p_tenant_override BIT = 0,
    @p_tag_batch acta.enqueue_tags_batch READONLY,
    @p_lane VARCHAR(128) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @ns_id INT, @ns_status TINYINT, @def_id INT, @def_priority SMALLINT;
        DECLARE @def_audit TINYINT, @def_status TINYINT, @def_tenant_req TINYINT;
        DECLARE @tenant_id INT, @tenant_status TINYINT, @lineage BIGINT, @parent_corr VARCHAR(64), @parent_tenant INT;
        DECLARE @existing_id BIGINT, @existing_ref UNIQUEIDENTIFIER, @job_id BIGINT;
        DECLARE @lane VARCHAR(128), @lane_id BIGINT, @ancestor_lane_hits INT;

        -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
        -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
        -- on error rethrow and let the caller roll back the whole transaction.

        -- Server-generate the job ref when the caller omits it (a proc default cannot be NEWID()).
        SET @p_job_ref = COALESCE(@p_job_ref, NEWID());

        SELECT
            @ns_id = ns.id,
            @ns_status = ns.status_code,
            @def_id = jd.id,
            @def_priority = jd.priority_code_effective,
            @def_audit = jd.audit_level_code_effective,
            @def_status = jd.status_code,
            @def_tenant_req = jd.tenant_requirement_code,
            @lane = COALESCE(@p_lane, jd.lane)
        FROM acta.namespaces ns
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = @p_job_name
        WHERE ns.name = @p_namespace_name;

        IF @def_id IS NULL
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF @ns_status <> 10 /* NamespaceStatusCode.Active */
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF @def_status <> 10 /* DefinitionStatusCode.Active */
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF @p_tenant_name IS NOT NULL
            BEGIN
                SELECT
                    @tenant_id = t.id,
                    @tenant_status = t.status_code
                FROM acta.tenants t
                WHERE t.tenant_name = @p_tenant_name;

                IF @tenant_id IS NULL
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;

                IF @tenant_status <> 10 /* TenantStatusCode.Active */
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        IF @def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ AND @p_tenant_name IS NOT NULL
            BEGIN
                THROW 50008, 'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: the job definition forbids a tenant and the row names one.', 1;
            END;

        -- The lane row is the lane's mutex, held to commit (docs/internals/sql-execution-policy.md, "Lane
        -- lock order"). The name only resolves the id; the lock is taken by id, on the clustered key.
        -- Ready versus Blocked is read after the lane lock, which a SNAPSHOT transaction (level 5) never sees.
        IF @lane IS NOT NULL
            AND (SELECT s.transaction_isolation_level FROM sys.dm_exec_sessions s WHERE s.session_id = @@SPID) = 5
            THROW 50011, 'ACTA:ENQ_LANE_ISOLATION:Enqueue rejected: a laned enqueue cannot run in a SNAPSHOT caller transaction.', 1;

        DECLARE @lane_found BIGINT;
        WHILE @lane IS NOT NULL AND @lane_id IS NULL
            BEGIN
                SET @lane_found = NULL;
                SELECT @lane_found = l.id
                FROM acta.lanes l
                WHERE
                    l.namespace_id = @ns_id
                    AND l.name = @lane;

                IF @lane_found IS NOT NULL
                    SELECT @lane_id = l.id
                    FROM acta.lanes l WITH (UPDLOCK, ROWLOCK)
                    WHERE l.id = @lane_found;

                IF @lane_found IS NULL
                    BEGIN
                        SET XACT_ABORT OFF;
                        BEGIN TRY
                            INSERT INTO acta.lanes (namespace_id, name, created_at_utc)
                            VALUES (@ns_id, @lane, @now);
                        END TRY
                        BEGIN CATCH
                            SET XACT_ABORT ON;
                            IF ERROR_NUMBER() NOT IN (2601, 2627)
                                THROW;
                        END CATCH;
                        SET XACT_ABORT ON;
                    END;
            END;

        IF @p_deduplication_key IS NOT NULL
            BEGIN
                IF @p_parent_id IS NOT NULL
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                        WHERE
                            j.parent_id = @p_parent_id
                            AND j.deduplication_key = @p_deduplication_key;
                    END
                ELSE
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                        WHERE
                            j.namespace_id = @ns_id
                            AND j.deduplication_key = @p_deduplication_key
                            AND j.parent_id IS NULL;
                    END;
            END;

        IF @p_parent_id IS NOT NULL
            BEGIN
                SELECT
                    @lineage = COALESCE(pj.lineage_root_id, pj.id),
                    @parent_corr = pj.correlation_key,
                    @parent_tenant = pj.tenant_id
                FROM acta.jobs pj WITH (UPDLOCK, ROWLOCK)
                INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
                WHERE
                    pj.id = @p_parent_id
                    AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

                IF @lineage IS NULL
                    BEGIN
                        THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
                    END;

                IF @lane_id IS NOT NULL
                    BEGIN
                        WITH ancestors AS (
                            SELECT a.id, a.parent_id
                            FROM acta.jobs a
                            WHERE a.id = @p_parent_id
                            UNION ALL
                            SELECT a.id, a.parent_id
                            FROM acta.jobs a
                            INNER JOIN ancestors c ON a.id = c.parent_id
                        )

                        SELECT @ancestor_lane_hits = COUNT(*)
                        FROM ancestors c
                        INNER JOIN acta.runtimes ar ON ar.job_id = c.id
                        WHERE
                            ar.lane_id = @lane_id
                            AND ar.status_code IN (
                                10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                                30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                            )
                        -- A lineage has no depth bound, so neither has the walk.
                        OPTION (MAXRECURSION 0);

                        IF @ancestor_lane_hits > 0
                            BEGIN
                                DECLARE
                                    @ancestor_msg NVARCHAR(2048) = 'ACTA:ENQ_ANCESTOR_LANE:Enqueue rejected: a child names the lane of an'
                                    + ' unfinished ancestor, so it would wait behind the ancestor that waits for it.';
                                THROW 50010, @ancestor_msg, 1;
                            END;
                    END;
            END;

        IF @def_tenant_req = 10 /* DefinitionTenantRequirementCode.Required */ AND @tenant_id IS NULL AND @parent_tenant IS NULL
            BEGIN
                THROW 50007, 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: the job definition requires a tenant and the row carries none.', 1;
            END;

        IF @tenant_id IS NOT NULL AND @parent_tenant IS NOT NULL AND @tenant_id <> @parent_tenant AND @p_tenant_override = 0
            BEGIN
                THROW 50009,
                'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: a child TenantName differs from the parent tenant without an explicit override.',
                1;
            END;

        IF @existing_id IS NULL
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                VALUES (
                    @p_job_ref, @lineage, @p_parent_id,
                    @p_deduplication_key, COALESCE(@p_correlation_key, @parent_corr),
                    @ns_id, @def_id,
                    CASE
                        WHEN @def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(@tenant_id, @parent_tenant)
                    END,
                    COALESCE(
                        @p_input_format_id,
                        CASE WHEN @p_input IS NULL THEN 0 /* JobPayloadFormat.None */ ELSE 1 /* JobPayloadFormat.Json */ END
                    ),
                    @p_input,
                    @p_concurrency_key, @def_audit,
                    @now
                );

                SET @job_id = SCOPE_IDENTITY();

                -- A laned job enters Ready only when no member of its lane is unfinished; otherwise it waits
                -- as Blocked, keeping its due instant for when the settle ahead of it promotes it.
                DECLARE @status TINYINT = 10 /* JobStatusCode.Ready */;
                IF
                    @lane_id IS NOT NULL
                    AND EXISTS (
                        SELECT 1
                        FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                        WHERE
                            m.lane_id = @lane_id
                            AND m.lane_id IS NOT NULL
                            AND m.status_code IN (
                                10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                                30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                            )
                    )
                    SET @status = 15 /* JobStatusCode.Blocked */;

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, lane_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                VALUES (
                    @job_id, @ns_id, @lane_id, @status,
                    COALESCE(@p_priority_override, @def_priority),
                    COALESCE(@p_next_run_at_utc, DATEADD(SECOND, COALESCE(@p_delay_seconds, 0), @now)),
                    0, 0, NULL,
                    @now, 0
                );

                INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
                SELECT
                    50 /* TagScopeCode.Job */,
                    @job_id,
                    @ns_id,
                    t.name,
                    t.value,
                    t.value_search
                FROM @p_tag_batch t;
            END;

        SELECT
            0 AS ordinal,
            COALESCE(@job_id, @existing_id) AS job_id,
            CASE WHEN @job_id IS NOT NULL THEN @p_job_ref ELSE @existing_ref END AS job_ref,
            CASE
                WHEN @job_id IS NOT NULL
                    THEN 1 /* EnqueueJobAction.Inserted */
                ELSE 2 /* EnqueueJobAction.Deduplicated */
            END AS action;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

-- Lock order: the batch's lanes in id order, then job rows (docs/internals/sql-execution-policy.md,
-- "Lane lock order").
CREATE OR ALTER PROCEDURE acta.enqueue_jobs
    @p_batch acta.enqueue_jobs_batch READONLY,
    @p_tag_batch acta.enqueue_tags_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

        -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
        -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
        -- on error rethrow and let the caller roll back the whole transaction.

        DECLARE @resolved TABLE (
            ordinal INT PRIMARY KEY,
            ns_id INT NOT NULL,
            ns_status TINYINT NOT NULL,
            def_id INT NOT NULL,
            def_priority SMALLINT NOT NULL,
            def_audit_level TINYINT NOT NULL,
            def_status TINYINT NOT NULL,
            def_tenant_req TINYINT NOT NULL,
            tenant_id INT NULL,
            lane VARCHAR(128) NULL,
            lane_id BIGINT NULL,
            lane_head BIT NOT NULL DEFAULT 0
        );

        INSERT INTO @resolved (ordinal, ns_id, ns_status, def_id, def_priority, def_audit_level, def_status, def_tenant_req, lane)
        SELECT
            b.ordinal,
            ns.id,
            ns.status_code,
            jd.id,
            jd.priority_code_effective,
            jd.audit_level_code_effective,
            jd.status_code,
            jd.tenant_requirement_code,
            COALESCE(b.lane, jd.lane)
        FROM @p_batch b
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = b.job_name;

        IF (SELECT COUNT(*) FROM @resolved) < (SELECT COUNT(*) FROM @p_batch)
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE ns_status <> 10 /* NamespaceStatusCode.Active */
            )
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE def_status <> 10 /* DefinitionStatusCode.Active */
            )
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE tenant_name IS NOT NULL
            )
            BEGIN
                UPDATE r
                SET tenant_id = t.id
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN acta.tenants t
                    ON
                        t.tenant_name = b.tenant_name
                        AND t.status_code = 10 /* TenantStatusCode.Active */
                WHERE b.tenant_name IS NOT NULL;

                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b
                        WHERE
                            b.tenant_name IS NOT NULL
                            AND NOT EXISTS (
                                SELECT 1 FROM acta.tenants t
                                WHERE t.tenant_name = b.tenant_name
                            )
                    )
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;
                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b JOIN acta.tenants t ON t.tenant_name = b.tenant_name
                        WHERE b.tenant_name IS NOT NULL AND t.status_code <> 10 /* TenantStatusCode.Active */
                    )
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        -- Missing lanes are inserted in name order without a range lock, then every lane is locked one row
        -- at a time in id order (docs/internals/sql-execution-policy.md, "Lane lock order").
        DECLARE @lanes TABLE (
            ns_id INT NOT NULL,
            name VARCHAR(128) NOT NULL,
            id BIGINT NULL,
            PRIMARY KEY (ns_id, name)
        );

        INSERT INTO @lanes (ns_id, name)
        SELECT DISTINCT r.ns_id, r.lane
        FROM @resolved r
        WHERE r.lane IS NOT NULL;

        DECLARE @laned BIT = CASE WHEN EXISTS (SELECT 1 FROM @lanes) THEN 1 ELSE 0 END;
        DECLARE @lanes_pending BIT = @laned;
        DECLARE @lane_cursor BIGINT, @lane_next BIGINT, @lane_locked BIGINT;

        -- Ready versus Blocked is read after the lane locks, which a SNAPSHOT transaction (level 5) never sees.
        IF @lanes_pending = 1
            AND (SELECT s.transaction_isolation_level FROM sys.dm_exec_sessions s WHERE s.session_id = @@SPID) = 5
            THROW 50011, 'ACTA:ENQ_LANE_ISOLATION:Enqueue rejected: a laned enqueue cannot run in a SNAPSHOT caller transaction.', 1;

        WHILE @lanes_pending = 1
            BEGIN
                SET XACT_ABORT OFF;
                BEGIN TRY
                    INSERT INTO acta.lanes (namespace_id, name, created_at_utc)
                    SELECT e.ns_id, e.name, @now
                    FROM @lanes e
                    WHERE NOT EXISTS (
                        SELECT 1
                        FROM acta.lanes l
                        WHERE
                            l.namespace_id = e.ns_id
                            AND l.name = e.name
                    )
                    ORDER BY e.name;
                END TRY
                BEGIN CATCH
                    SET XACT_ABORT ON;
                    IF ERROR_NUMBER() NOT IN (2601, 2627)
                        THROW;
                END CATCH;
                SET XACT_ABORT ON;

                UPDATE e
                SET id = l.id
                FROM @lanes e
                LEFT JOIN acta.lanes l
                    ON
                        l.namespace_id = e.ns_id
                        AND l.name = e.name;

                SET @lanes_pending = CASE WHEN EXISTS (SELECT 1 FROM @lanes WHERE id IS NULL) THEN 1 ELSE 0 END;
                SET @lane_cursor = 0;
                WHILE @lanes_pending = 0
                    BEGIN
                        SET @lane_next = NULL;
                        SELECT TOP (1) @lane_next = e.id
                        FROM @lanes e
                        WHERE e.id > @lane_cursor
                        ORDER BY e.id;

                        IF @lane_next IS NULL
                            BREAK;

                        SET @lane_locked = NULL;
                        SELECT @lane_locked = l.id
                        FROM acta.lanes l WITH (UPDLOCK, ROWLOCK)
                        WHERE l.id = @lane_next;

                        IF @lane_locked IS NULL
                            SET @lanes_pending = 1;
                        SET @lane_cursor = @lane_next;
                    END;
            END;

        UPDATE r
        SET lane_id = e.id
        FROM @resolved r
        INNER JOIN @lanes e
            ON
                e.ns_id = r.ns_id
                AND e.name = r.lane;

        DECLARE @existing TABLE (
            ordinal INT PRIMARY KEY,
            id BIGINT NOT NULL,
            job_ref UNIQUEIDENTIFIER NOT NULL
        );

        -- Skip when no row has a key: the dedup probes' HOLDLOCK range locks (held to commit) would
        -- otherwise serialize every concurrent keyless enqueue on the namespace.
        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE deduplication_key IS NOT NULL
            )
            BEGIN
                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                    ON
                        j.parent_id = b.parent_id
                        AND j.deduplication_key = b.deduplication_key
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NOT NULL;

                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                    ON
                        j.namespace_id = r.ns_id
                        AND j.deduplication_key = b.deduplication_key
                        AND j.parent_id IS NULL
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NULL;
            END;

        DECLARE @parents TABLE (
            ordinal INT PRIMARY KEY,
            lineage_root_id BIGINT NOT NULL,
            correlation_key VARCHAR(64) NULL,
            tenant_id INT NULL
        );

        INSERT INTO @parents (ordinal, lineage_root_id, correlation_key, tenant_id)
        SELECT
            b.ordinal,
            COALESCE(pj.lineage_root_id, pj.id),
            pj.correlation_key,
            pj.tenant_id
        FROM @p_batch b
        INNER JOIN acta.jobs pj WITH (UPDLOCK, ROWLOCK) ON pj.id = b.parent_id
        INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
        WHERE
            b.parent_id IS NOT NULL
            AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
        ORDER BY pj.id DESC;

        IF (
            SELECT COUNT(*) FROM @parents) < (
            SELECT COUNT(*) FROM @p_batch
            WHERE parent_id IS NOT NULL
        )
            BEGIN
                THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.def_tenant_req = 10 /* DefinitionTenantRequirementCode.Required */
                    AND r.tenant_id IS NULL
                    AND p.tenant_id IS NULL
            )
            BEGIN
                THROW 50007,
                'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: one or more rows target a definition that requires a tenant and carry none.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                WHERE
                    r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */
                    AND b.tenant_name IS NOT NULL
            )
            BEGIN
                THROW 50008,
                'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: one or more rows target a definition that forbids a tenant and name one.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.tenant_id IS NOT NULL
                    AND p.tenant_id IS NOT NULL
                    AND r.tenant_id <> p.tenant_id
                    AND b.tenant_override = 0
            )
            BEGIN
                DECLARE
                    @tenant_msg NVARCHAR(2048) = 'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: one or more child rows name a'
                    + ' TenantName that differs from the parent tenant without an explicit override.';
                THROW 50009, @tenant_msg, 1;
            END;

        -- A child may not wait behind an unfinished ancestor in its own lane: the ancestor waits for it.
        DECLARE @ancestor_lane_hits INT = 0;
        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                WHERE
                    r.lane_id IS NOT NULL
                    AND b.parent_id IS NOT NULL
            )
            BEGIN
                WITH ancestors AS (
                    SELECT r.lane_id, a.id, a.parent_id
                    FROM @resolved r
                    INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                    INNER JOIN acta.jobs a ON a.id = b.parent_id
                    WHERE r.lane_id IS NOT NULL
                    UNION ALL
                    SELECT c.lane_id, a.id, a.parent_id
                    FROM acta.jobs a
                    INNER JOIN ancestors c ON a.id = c.parent_id
                )

                SELECT @ancestor_lane_hits = COUNT(*)
                FROM ancestors c
                INNER JOIN acta.runtimes ar ON ar.job_id = c.id
                WHERE
                    ar.lane_id = c.lane_id
                    AND ar.status_code IN (
                        10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                        30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                    )
                -- A lineage has no depth bound, so neither has the walk.
                OPTION (MAXRECURSION 0);
            END;

        IF @ancestor_lane_hits > 0
            BEGIN
                DECLARE
                    @ancestor_msg NVARCHAR(2048) = 'ACTA:ENQ_ANCESTOR_LANE:Enqueue rejected: one or more child rows name the lane of'
                    + ' an unfinished ancestor, so they would wait behind the ancestor that waits for them.';
                THROW 50010, @ancestor_msg, 1;
            END;

        DECLARE @map TABLE (
            job_ref UNIQUEIDENTIFIER PRIMARY KEY,
            id BIGINT NOT NULL
        );

        -- An unlaned batch runs the plain inserts; only a laned one pays for batch order and lane heads.
        -- Both runtimes inserts force nested loops so the foreign-key checks seek their parent rows
        -- (docs/internals/sql-execution-policy.md, "Foreign keys in set-based writes").
        IF @laned = 0
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                OUTPUT INSERTED.job_ref, INSERTED.id INTO @map (job_ref, id)
                SELECT
                    b.job_ref,
                    p.lineage_root_id,
                    b.parent_id,
                    b.deduplication_key,
                    COALESCE(b.correlation_key, p.correlation_key),
                    r.ns_id,
                    r.def_id,
                    CASE
                        WHEN r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(r.tenant_id, p.tenant_id)
                    END,
                    b.input_format_id,
                    b.input,
                    b.concurrency_key,
                    r.def_audit_level,
                    @now
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                LEFT JOIN @existing e ON e.ordinal = b.ordinal
                WHERE e.ordinal IS NULL;

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                SELECT
                    m.id,
                    r.ns_id,
                    10 /* JobStatusCode.Ready */,
                    COALESCE(b.priority_override, r.def_priority),
                    COALESCE(b.next_run_at_utc, DATEADD(SECOND, COALESCE(b.delay_seconds, 0), @now)),
                    0,
                    0,
                    NULL,
                    @now,
                    0
                FROM @map m
                INNER JOIN @p_batch b ON b.job_ref = m.job_ref
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                OPTION (LOOP JOIN);
            END
        ELSE
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                OUTPUT INSERTED.job_ref, INSERTED.id INTO @map (job_ref, id)
                SELECT
                    b.job_ref,
                    p.lineage_root_id,
                    b.parent_id,
                    b.deduplication_key,
                    COALESCE(b.correlation_key, p.correlation_key),
                    r.ns_id,
                    r.def_id,
                    CASE
                        WHEN r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(r.tenant_id, p.tenant_id)
                    END,
                    b.input_format_id,
                    b.input,
                    b.concurrency_key,
                    r.def_audit_level,
                    @now
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                LEFT JOIN @existing e ON e.ordinal = b.ordinal
                WHERE e.ordinal IS NULL
                -- Identity values follow this order, so job-id order equals the caller's batch order, which
                -- is the order a lane runs in.
                ORDER BY b.ordinal;

                -- A lane's head is its first inserted row, the lowest ordinal the dedup probe kept, and only
                -- when no unfinished member is already there; every other laned row waits as Blocked. The
                -- probe runs under the lane locks, before this batch has any runtimes row.
                UPDATE r
                SET lane_head = 1
                FROM @resolved r
                INNER JOIN (
                    SELECT MIN(h.ordinal) AS ordinal
                    FROM @resolved h
                    LEFT JOIN @existing x ON x.ordinal = h.ordinal
                    WHERE
                        h.lane_id IS NOT NULL
                        AND x.ordinal IS NULL
                    GROUP BY h.lane_id
                ) f ON f.ordinal = r.ordinal
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM acta.runtimes x WITH (FORCESEEK)
                    WHERE
                        x.lane_id = r.lane_id
                        AND x.lane_id IS NOT NULL
                        AND x.status_code IN (
                            10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                            30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                        )
                );

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, lane_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                SELECT
                    m.id,
                    r.ns_id,
                    r.lane_id,
                    CASE
                        WHEN r.lane_id IS NULL OR r.lane_head = 1 THEN 10 /* JobStatusCode.Ready */
                        ELSE 15 /* JobStatusCode.Blocked */
                    END,
                    COALESCE(b.priority_override, r.def_priority),
                    COALESCE(b.next_run_at_utc, DATEADD(SECOND, COALESCE(b.delay_seconds, 0), @now)),
                    0,
                    0,
                    NULL,
                    @now,
                    0
                FROM @map m
                INNER JOIN @p_batch b ON b.job_ref = m.job_ref
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                OPTION (LOOP JOIN);
            END;

        INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT
            50 /* TagScopeCode.Job */,
            m.id,
            r.ns_id,
            t.name,
            t.value,
            t.value_search
        FROM @p_tag_batch t
        INNER JOIN @p_batch b ON b.ordinal = t.ordinal
        INNER JOIN @map m ON m.job_ref = b.job_ref
        INNER JOIN @resolved r ON r.ordinal = t.ordinal;

        SELECT
            b.ordinal,
            COALESCE(m.id, e.id) AS job_id,
            COALESCE(m.job_ref, e.job_ref) AS job_ref,
            CASE
                WHEN m.id IS NOT NULL
                    THEN 1 /* EnqueueJobAction.Inserted */
                ELSE 2 /* EnqueueJobAction.Deduplicated */
            END AS action
        FROM @p_batch b
        LEFT JOIN @map m ON m.job_ref = b.job_ref
        LEFT JOIN @existing e ON e.ordinal = b.ordinal
        ORDER BY b.ordinal;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.extend_worker_leases
    @p_leased_by_worker_id INT,
    @p_lease_ttl_seconds INT,
    @p_draining BIT,
    @p_executions NVARCHAR(MAX),
    @p_locks NVARCHAR(MAX),
    @p_recovery_interval_seconds INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @new_expiry DATETIME2(7) = DATEADD(SECOND, @p_lease_ttl_seconds, @now);
        DECLARE @namespace_id INT = (SELECT w.namespace_id FROM acta.workers w WHERE w.id = @p_leased_by_worker_id);

        UPDATE acta.workers
        SET
            last_seen_at_utc = @now,
            -- A worker marked Dead through a database outage longer than its dead-after window is alive again the
            -- moment it heartbeats; Stopped stays Stopped.
            status_code = CASE
                WHEN @p_draining = 1 AND status_code IN (10 /* WorkerStatusCode.Active */, 200 /* WorkerStatusCode.Dead */)
                    THEN 80 /* WorkerStatusCode.Draining */
                WHEN status_code = 200 /* WorkerStatusCode.Dead */ THEN 10 /* WorkerStatusCode.Active */
                ELSE status_code
            END,
            modified_at_utc = @now,
            version = version + 1
        WHERE id = @p_leased_by_worker_id;

        /* The held executions and lock holds arrive as JSON array text, expanded once into keyed tables. A process
           can hold two executions of one job, or two holds on one key, while a stale attempt unwinds. */
        DECLARE @held TABLE (job_id BIGINT NOT NULL, execution_number INT NOT NULL, PRIMARY KEY (job_id, execution_number));
        INSERT INTO @held (job_id, execution_number)
        SELECT job_id, execution_number
        FROM OPENJSON(@p_executions) WITH (job_id BIGINT '$.job_id', execution_number INT '$.execution_number');

        DECLARE @lock_held TABLE (
            lock_key VARCHAR(256) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL,
            hold_token UNIQUEIDENTIFIER NOT NULL,
            PRIMARY KEY (lock_key, hold_token)
        );
        INSERT INTO @lock_held (lock_key, hold_token)
        SELECT lock_key, hold_token
        FROM OPENJSON(@p_locks) WITH (
            lock_key VARCHAR(256) COLLATE Latin1_General_100_BIN2_UTF8 '$.lock_key',
            hold_token UNIQUEIDENTIFIER '$.hold_token'
        );

        -- Lock holds renew first and never skip: no routine locks both locks and runtimes. A hold whose token
        -- moved is not answered, and the attempt that relied on it stops.
        DECLARE @lock_renewed TABLE (lock_key VARCHAR(256) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL PRIMARY KEY);
        UPDATE k
        SET expires_at_utc = @new_expiry
        OUTPUT INSERTED.lock_key INTO @lock_renewed (lock_key)
        FROM acta.locks k
        INNER JOIN @lock_held h ON h.lock_key = k.lock_key AND h.hold_token = k.hold_token;

        /* Push the held executions' leases forward. Only a row this worker still leases at the execution the
           process holds is answered, so a row the process lost lapses and recovery takes it. Deliberately no
           version bump: a lease refresh is not a claim-generation change. */
        -- Read the matched ids first so the update locks base rows only, never an index key;
        -- complete_executions locks in the other order. See docs/internals/sql-execution-policy.md.
        DECLARE @matched TABLE (job_id BIGINT NOT NULL PRIMARY KEY, execution_number INT NOT NULL);
        INSERT INTO @matched (job_id, execution_number)
        SELECT r.job_id, r.execution_number
        FROM acta.runtimes r
        INNER JOIN @held h ON h.job_id = r.job_id AND h.execution_number = r.execution_number
        WHERE
            r.leased_by_worker_id = @p_leased_by_worker_id
            AND r.status_code = 50 /* JobStatusCode.Executing */;

        -- A row another transaction holds is skipped and reported unrenewed, so the renewal never waits
        -- (docs/internals/sql-execution-policy.md, "Explicit exceptions and maintenance").
        DECLARE @renewed TABLE (job_id BIGINT NOT NULL PRIMARY KEY);
        UPDATE r
        SET lease_expires_at_utc = @new_expiry
        OUTPUT INSERTED.job_id INTO @renewed (job_id)
        FROM acta.runtimes r WITH (INDEX(pk_runtimes), FORCESEEK, ROWLOCK, READPAST)
        INNER JOIN @matched m ON m.job_id = r.job_id AND m.execution_number = r.execution_number
        WHERE
            r.leased_by_worker_id = @p_leased_by_worker_id
            AND r.status_code = 50 /* JobStatusCode.Executing */;

        -- Takes the namespace's recovery pass when it is due, moving the next one an interval out; this worker runs it.
        -- A namespace row another transaction holds is skipped, so the heartbeat never waits on it.
        DECLARE @recovery_claimed BIT = 0;
        IF @p_recovery_interval_seconds IS NOT NULL
            BEGIN
                UPDATE n
                SET recovery_due_at_utc = DATEADD(SECOND, @p_recovery_interval_seconds, @now)
                FROM acta.namespaces n WITH (ROWLOCK, READPAST)
                WHERE n.id = @namespace_id AND (n.recovery_due_at_utc IS NULL OR n.recovery_due_at_utc <= @now);
                SET @recovery_claimed = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END;
            END;

        SELECT
            CAST(NULL AS BIGINT) AS job_id,
            CAST(NULL AS INT) AS execution_number,
            l.lock_key,
            CAST(1 AS BIT) AS renewed,
            CAST(NULL AS DATETIME2(3)) AS definitions_modified_at_utc,
            CAST(0 AS BIT) AS recovery_claimed
        FROM @lock_renewed l
        UNION ALL
        SELECT
            m.job_id,
            m.execution_number,
            CAST(NULL AS VARCHAR(256)),
            CAST(CASE WHEN n.job_id IS NULL THEN 0 ELSE 1 END AS BIT),
            CAST(NULL AS DATETIME2(3)),
            CAST(0 AS BIT)
        FROM @matched m
        LEFT JOIN @renewed n ON n.job_id = m.job_id
        UNION ALL
        -- The namespace's newest definition change: the worker re-reads its catalog only when it moves.
        SELECT
            CAST(NULL AS BIGINT) AS job_id,
            CAST(NULL AS INT) AS execution_number,
            CAST(NULL AS VARCHAR(256)) AS lock_key,
            CAST(0 AS BIT) AS renewed,
            MAX(d.modified_at_utc) AS definitions_modified_at_utc,
            @recovery_claimed AS recovery_claimed
        FROM acta.definitions d
        WHERE d.namespace_id = @namespace_id;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

-- One section, one bounded atomic batch. Section numbers match RetentionSection.
CREATE OR ALTER PROCEDURE acta.purge_expired_data
    @p_namespace_id INT,
    @p_section INT,
    @p_cutoff_utc DATETIME2(7),
    @p_batch_size INT,
    @p_before_job_id BIGINT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        IF @p_batch_size <= 0 OR @p_section NOT BETWEEN 1 AND 8
            THROW 50002, 'Invalid retention section or batch size.', 1;

        DECLARE @rows INT = 0;
        DECLARE @next_job_id BIGINT = 0;
        DECLARE @del TABLE (id BIGINT NOT NULL);
        DECLARE @schedule_del TABLE (id BIGINT NOT NULL);
        DECLARE @lock_del TABLE (lock_key VARCHAR(256) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL);
        DECLARE @alert_del TABLE (id BIGINT NOT NULL PRIMARY KEY, deduplication_key VARCHAR(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL);
        DECLARE @alert_locked TABLE (id BIGINT NOT NULL PRIMARY KEY);

        IF @p_section = 1
            BEGIN
                DELETE @del;

                /* No retention index: walk runtimes downward from the cursor, ten batches a slice, and delete this
                   namespace's expired jobs in it; downward, so a walk has a fixed end however fast enqueues arrive.
                   A full batch ends the slice at its last delete; the oldest row answers zero, and the walk restarts. */
                DECLARE @below BIGINT = CASE WHEN @p_before_job_id = 0 THEN 9223372036854775807 ELSE @p_before_job_id END;
                DECLARE @slice_end BIGINT = (
                    SELECT MIN(s.job_id)
                    FROM (
                        SELECT TOP (@p_batch_size * 10) r.job_id
                        FROM acta.runtimes r
                        WHERE r.job_id < @below
                        ORDER BY r.job_id DESC
                    ) s
                );

                INSERT INTO @del (id)
                SELECT TOP (@p_batch_size) j.id
                FROM acta.runtimes r WITH (UPDLOCK, READPAST)
                INNER JOIN acta.jobs j WITH (UPDLOCK, READPAST) ON j.id = r.job_id
                WHERE
                    r.job_id < @below
                    AND r.job_id >= @slice_end
                    AND r.namespace_id = @p_namespace_id
                    AND r.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    AND r.retention_until_utc IS NOT NULL
                    AND r.retention_until_utc <= @p_cutoff_utc
                    -- Lineage guard: parent_id carries no FK, so purging a parent whose children still
                    -- exist would orphan their lineage (same rule as the manual purge_job). Only leaves
                    -- delete; a fully-expired subtree drains bottom-up across iterations.
                    AND NOT EXISTS (
                        SELECT 1 FROM acta.jobs c
                        WHERE c.parent_id = j.id
                    )
                    -- A completed child of a live parent is kept: the parent's replay dedupes onto its row
                    -- and reads its result, so purging it would run the child again. The tree drains once
                    -- the parent is terminal.
                    AND NOT EXISTS (
                        SELECT 1 FROM acta.runtimes p
                        WHERE p.job_id = j.parent_id
                            AND p.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    )
                    -- A stopped recurring job stays while its definition is live: the next start would register
                    -- its declaration as a new job and undo the cancel or failure. Retiring the definition lets
                    -- it drain.
                    AND NOT EXISTS (
                        SELECT 1 FROM acta.schedules s
                        INNER JOIN acta.definitions d ON d.id = j.definition_id
                        WHERE s.job_id = j.id AND d.status_code <> 240 /* DefinitionStatusCode.Retired */
                    )
                ORDER BY r.job_id DESC;

                SET @next_job_id = CASE
                    WHEN @slice_end IS NULL THEN 0
                    WHEN (SELECT COUNT(*) FROM @del) = @p_batch_size THEN (SELECT MIN(id) FROM @del)
                    ELSE @slice_end
                END;

                DELETE @schedule_del;
                INSERT INTO @schedule_del (id)
                SELECT s.id FROM acta.schedules s WITH (UPDLOCK, FORCESEEK)
                WHERE s.job_id IN (SELECT id FROM @del);

                DELETE FROM acta.tags
                WHERE
                    (scope_code = 50 /* TagScopeCode.Job */ AND scope_id IN (SELECT id FROM @del))
                    OR (scope_code = 60 /* TagScopeCode.Schedule */ AND scope_id IN (SELECT id FROM @schedule_del));

                -- Each delete below seeks its rows by job id, the jobs cascade included: an unhinted plan can scan
                -- the whole child table under update locks
                -- (docs/internals/sql-execution-policy.md, "Foreign keys in set-based writes").
                DELETE c FROM acta.checkpoints c WITH (FORCESEEK) INNER JOIN @del d ON d.id = c.job_id;
                DELETE r FROM acta.runtimes r WITH (FORCESEEK) INNER JOIN @del d ON d.id = r.job_id;
                DELETE s FROM acta.steps s WITH (FORCESEEK) INNER JOIN @del d ON d.id = s.job_id;
                DELETE x FROM acta.results x WITH (FORCESEEK) INNER JOIN @del d ON d.id = x.job_id;
                DELETE j FROM acta.jobs j WITH (FORCESEEK) INNER JOIN @del d ON d.id = j.id
                OPTION (LOOP JOIN);
                SET @rows = (SELECT COUNT(*) FROM @del);

            END;

        ELSE IF @p_section = 2
            BEGIN
                DELETE @del;

                INSERT INTO @del (id)
                SELECT TOP (@p_batch_size) id
                FROM acta.events WITH (UPDLOCK, READPAST)
                WHERE
                    namespace_id = @p_namespace_id
                    AND created_at_utc <= @p_cutoff_utc
                ORDER BY created_at_utc, id;
                DELETE FROM acta.tags
                WHERE scope_code = 90 /* TagScopeCode.Event */ AND scope_id IN (SELECT id FROM @del);
                DELETE e FROM acta.events e WITH (FORCESEEK) INNER JOIN @del d ON d.id = e.id;
                SET @rows = (SELECT COUNT(*) FROM @del);

            END;

        ELSE IF @p_section = 3
            BEGIN
                DELETE @alert_del;
                DELETE @alert_locked;

                INSERT INTO @alert_del (id, deduplication_key)
                SELECT TOP (@p_batch_size) id, deduplication_key
                FROM acta.alerts WITH (READPAST)
                WHERE
                    namespace_id = @p_namespace_id
                    AND created_at_utc <= @p_cutoff_utc
                    AND delivery_status_code IN (
                        30 /* AlertDeliveryStatusCode.Suppressed */,
                        100 /* AlertDeliveryStatusCode.Delivered */,
                        200 /* AlertDeliveryStatusCode.Failed */
                    )
                ORDER BY created_at_utc, id;

                -- Staged without locks, then each identity row is locked through its ix_alerts_deduplication_key_identity
                -- key before the row and the rest by key, skipping a row another transaction holds
                -- (docs/internals/sql-execution-policy.md, "Alert lock order").
                INSERT INTO @alert_locked (id)
                SELECT a.id
                FROM @alert_del d
                INNER JOIN acta.alerts a WITH (UPDLOCK, READPAST, FORCESEEK (ix_alerts_deduplication_key_identity (namespace_id, deduplication_key)))
                    ON
                        a.namespace_id = @p_namespace_id
                        AND a.deduplication_key = d.deduplication_key
                        AND a.id = d.id
                WHERE d.deduplication_key IS NOT NULL;
                INSERT INTO @alert_locked (id)
                SELECT a.id
                FROM @alert_del d
                INNER JOIN acta.alerts a WITH (UPDLOCK, READPAST, FORCESEEK) ON a.id = d.id
                WHERE d.deduplication_key IS NULL;

                DELETE FROM acta.tags
                WHERE scope_code = 80 /* TagScopeCode.Alert */ AND scope_id IN (SELECT id FROM @alert_locked);
                DELETE a
                FROM acta.alerts a WITH (FORCESEEK)
                INNER JOIN @alert_locked l ON l.id = a.id
                WHERE
                    a.created_at_utc <= @p_cutoff_utc
                    AND a.delivery_status_code IN (
                        30 /* AlertDeliveryStatusCode.Suppressed */,
                        100 /* AlertDeliveryStatusCode.Delivered */,
                        200 /* AlertDeliveryStatusCode.Failed */
                    );
                SET @rows = @@ROWCOUNT;

            END;

        ELSE IF @p_section = 4
            BEGIN
                DELETE @alert_del;
                DELETE @alert_locked;

                INSERT INTO @alert_del (id, deduplication_key)
                SELECT TOP (@p_batch_size) id, deduplication_key
                FROM acta.alerts WITH (READPAST)
                WHERE
                    namespace_id = @p_namespace_id
                    AND created_at_utc <= @p_cutoff_utc
                    AND delivery_status_code IN (
                        10 /* AlertDeliveryStatusCode.Pending */,
                        20 /* AlertDeliveryStatusCode.RetryAfter */
                    )
                ORDER BY created_at_utc, id;

                -- Staged without locks, then each identity row is locked through its ix_alerts_deduplication_key_identity
                -- key before the row and the rest by key, skipping a row another transaction holds
                -- (docs/internals/sql-execution-policy.md, "Alert lock order").
                INSERT INTO @alert_locked (id)
                SELECT a.id
                FROM @alert_del d
                INNER JOIN acta.alerts a WITH (UPDLOCK, READPAST, FORCESEEK (ix_alerts_deduplication_key_identity (namespace_id, deduplication_key)))
                    ON
                        a.namespace_id = @p_namespace_id
                        AND a.deduplication_key = d.deduplication_key
                        AND a.id = d.id
                WHERE d.deduplication_key IS NOT NULL;
                INSERT INTO @alert_locked (id)
                SELECT a.id
                FROM @alert_del d
                INNER JOIN acta.alerts a WITH (UPDLOCK, READPAST, FORCESEEK) ON a.id = d.id
                WHERE d.deduplication_key IS NULL;

                DELETE FROM acta.tags
                WHERE scope_code = 80 /* TagScopeCode.Alert */ AND scope_id IN (SELECT id FROM @alert_locked);
                DELETE a
                FROM acta.alerts a WITH (FORCESEEK)
                INNER JOIN @alert_locked l ON l.id = a.id
                WHERE
                    a.created_at_utc <= @p_cutoff_utc
                    AND a.delivery_status_code IN (
                        10 /* AlertDeliveryStatusCode.Pending */,
                        20 /* AlertDeliveryStatusCode.RetryAfter */
                    );
                SET @rows = @@ROWCOUNT;

            END;

        ELSE IF @p_section = 5
            BEGIN
                DECLARE @alerts_slot_id BIGINT = (
                    SELECT j.id
                    FROM acta.jobs j
                    WHERE
                        j.namespace_id = @p_namespace_id
                        AND j.deduplication_key = 'sys.alerts'
                        AND j.parent_id IS NULL);
                DELETE TOP (@p_batch_size) FROM acta.checkpoints
                WHERE
                    job_id = @alerts_slot_id
                    AND kind_code = 10 /* CheckpointKindCode.Variable */
                    AND name LIKE 'alerts-skip-%'
                    AND modified_at_utc <= @p_cutoff_utc;
                SET @rows = @@ROWCOUNT;
            END;

        ELSE IF @p_section = 6
            BEGIN
                DELETE @del;

                INSERT INTO @del (id)
                SELECT TOP (@p_batch_size) id
                FROM acta.workers WITH (UPDLOCK, READPAST)
                WHERE
                    namespace_id = @p_namespace_id
                    AND status_code IN (100 /* WorkerStatusCode.Stopped */, 200 /* WorkerStatusCode.Dead */)
                    AND last_seen_at_utc <= @p_cutoff_utc
                ORDER BY last_seen_at_utc, id;
                DELETE FROM acta.tags
                WHERE scope_code = 70 /* TagScopeCode.Worker */ AND scope_id IN (SELECT id FROM @del);
                DELETE w FROM acta.workers w WITH (FORCESEEK) INNER JOIN @del d ON d.id = w.id;
                SET @rows = (SELECT COUNT(*) FROM @del);

            END;

        ELSE IF @p_section = 7
            BEGIN
            -- The batch is staged without holding locks, then the delete seeks each row by clustered key, first
            -- as every lock writer does, skipping a row a writer holds and re-checking its expiry. Taking the
            -- expiry index key first deadlocks against reserve_rate moving a bucket's expiry.
                DELETE @lock_del;
                INSERT INTO @lock_del (lock_key)
                SELECT TOP (@p_batch_size) lock_key
                FROM acta.locks WITH (READPAST)
                WHERE
                    expires_at_utc <= @p_cutoff_utc
                ORDER BY expires_at_utc;
                DELETE t
                FROM acta.locks t WITH (READPAST, FORCESEEK (pk_locks (lock_key)))
                INNER JOIN @lock_del d ON d.lock_key = t.lock_key
                WHERE t.expires_at_utc <= @p_cutoff_utc;
                SET @rows = @@ROWCOUNT;
            END;

        ELSE IF @p_section = 8
            BEGIN
            -- Unreferenced lanes, locked by id on the clustered key skipping a lane an enqueue or settle
            -- holds, then re-checked under the lock (docs/internals/sql-execution-policy.md, "Lane lock order").
                DELETE @del;
                INSERT INTO @del (id)
                SELECT l.id
                FROM acta.lanes l WITH (UPDLOCK, READPAST, ROWLOCK, INDEX (pk_lanes))
                WHERE l.id IN (
                    SELECT TOP (@p_batch_size) c.id
                    FROM acta.lanes c
                    WHERE
                        c.namespace_id = @p_namespace_id
                        AND NOT EXISTS (SELECT 1 FROM acta.runtimes r WHERE r.lane_id = c.id)
                    ORDER BY c.id
                );
                DELETE l
                FROM acta.lanes l WITH (FORCESEEK)
                INNER JOIN @del d ON d.id = l.id
                WHERE NOT EXISTS (SELECT 1 FROM acta.runtimes r WHERE r.lane_id = l.id)
                OPTION (LOOP JOIN);
                SET @rows = @@ROWCOUNT;
            END;

        SELECT @rows AS deleted_count, @next_job_id AS next_job_id;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.raise_signal
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX),
    @p_actor_code TINYINT,
    @p_actor NVARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @existing TINYINT;
        DECLARE @expired BIT = 0;
        DECLARE @message NVARCHAR(512);
        DECLARE
            @from_status TINYINT, @namespace_id INT, @lineage_root_id BIGINT,
            @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
            @job_ref UNIQUEIDENTIFIER;

        SELECT @existing = status_code
        FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_job_id;

        IF @from_status IS NULL
            BEGIN

                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                GOTO Finish;
            END;

        IF @from_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
            BEGIN

                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                GOTO Finish;
            END;

        /* No revival: an Expired slot already resolved the wait TimedOut, so a late raise writes no
           slot and releases no job. The raise still happened, so it is still recorded: the event below
           carries a message saying why it changed nothing, and the verb reports the unchanged status. */
        SET @expired = CASE WHEN @existing = 30 /* CheckpointStatusCode.Expired */ THEN 1 ELSE 0 END;
        SET @message = CASE
            WHEN @expired = 1
                THEN LEFT(COALESCE(@p_reason_message + N' ', N'') + N'Signal not applied: the wait had already expired.', 512)
            ELSE @p_reason_message
        END;

        IF @expired = 0
            BEGIN
                IF @existing IS NULL
                    INSERT INTO acta.checkpoints (
                        job_id, kind_code, name, status_code, value_format_id, value,
                        created_at_utc, modified_at_utc, version
                    )
                    VALUES (@p_job_id, @p_kind_code, @p_name, 20 /* CheckpointStatusCode.Set */, @p_value_format_id, @p_value, @now, @now, 0);
                ELSE
                    UPDATE acta.checkpoints
                    SET
                        status_code = 20 /* CheckpointStatusCode.Set */,
                        value_format_id = @p_value_format_id,
                        value = @p_value,
                        modified_at_utc = @now,
                        version = version + 1
                    WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;
            END

        IF @audit_level = 20 /* DefinitionAuditLevelCode.Audit */
            INSERT INTO acta.events (
                event_code, created_at_utc, namespace_id,
                actor_code, actor,
                job_id, job_ref, execution_number,
                lineage_root_id, definition_id, tenant_id,
                worker_id,
                from_status_code, to_status_code,
                execution_status_code, duration_ms,
                reason_code, reason_message
            )
            VALUES (
                80 /* EventCode.JobSignalRaised */, @now, @namespace_id,
                @p_actor_code, @p_actor,
                @p_job_id, @job_ref, @execution_number,
                COALESCE(@lineage_root_id, @p_job_id), @definition_id, @tenant_id,
                NULL,
                @from_status, @from_status,
                NULL, NULL,
                @p_reason_code, @message
            );

        IF @from_status = 20 /* JobStatusCode.Suspended */ AND @expired = 0
            BEGIN
                UPDATE acta.runtimes
                SET
                    status_code = 10 /* JobStatusCode.Ready */,
                    next_run_at_utc = @now,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id;

                IF @audit_level = 20 /* DefinitionAuditLevelCode.Audit */
                    INSERT INTO acta.events (
                        event_code, created_at_utc, namespace_id,
                        actor_code, actor,
                        job_id, job_ref, execution_number,
                        lineage_root_id, definition_id, tenant_id,
                        worker_id,
                        from_status_code, to_status_code,
                        execution_status_code, duration_ms,
                        reason_code, reason_message
                    )
                    VALUES (
                        72 /* EventCode.JobResumed */, @now, @namespace_id,
                        @p_actor_code, @p_actor,
                        @p_job_id, @job_ref, @execution_number,
                        COALESCE(@lineage_root_id, @p_job_id), @definition_id, @tenant_id,
                        NULL,
                        20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */,
                        NULL, NULL,
                        @p_reason_code, @p_reason_message
                    );

                SELECT
                    CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
                    CAST(10 /* JobStatusCode.Ready */ AS TINYINT) AS status_code;
                GOTO Finish;
            END

        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @from_status AS status_code;

    Finish:

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.reclaim_stuck_jobs
    @p_namespace_id INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

        DECLARE
            @reclaimed TABLE
            (
                id BIGINT NOT NULL PRIMARY KEY,
                job_ref UNIQUEIDENTIFIER NOT NULL,
                namespace_id INT NOT NULL,
                execution_number INT NOT NULL,
                lineage_root_id BIGINT NULL,
                definition_id INT NOT NULL,
                tenant_id INT NULL,
                from_status_code TINYINT NOT NULL,
                to_status_code TINYINT NOT NULL,
                audit_level_code TINYINT NOT NULL,
                parent_id BIGINT NULL
            );

        /* A pass visits at most 1,000 of the namespace's lanes from a random lane id with wrap and repairs at
           most 100 stranded ones in visiting order (docs/internals/sql-execution-policy.md, "Lane lock order").
           Each head is sought through ix_runtimes_lane, named because a small runtimes table tempts a scan. */
        DECLARE @window TABLE (ord INT IDENTITY (1, 1) PRIMARY KEY, id BIGINT NOT NULL);
        DECLARE @stranded TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @repaired TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @min_lane BIGINT, @max_lane BIGINT, @start_lane BIGINT, @window_count INT;
        SELECT @min_lane = MIN(l.id), @max_lane = MAX(l.id) FROM acta.lanes l;
        IF @max_lane IS NOT NULL
            BEGIN
                SET @start_lane = @min_lane + CAST(FLOOR(RAND(CHECKSUM(NEWID())) * (@max_lane - @min_lane + 1)) AS BIGINT);
                INSERT INTO @window (id)
                SELECT TOP (1000) l.id
                FROM acta.lanes l
                WHERE l.namespace_id = @p_namespace_id AND l.id >= @start_lane
                ORDER BY l.id;
                SET @window_count = @@ROWCOUNT;
                INSERT INTO @window (id)
                SELECT TOP (1000 - @window_count) l.id
                FROM acta.lanes l
                WHERE l.namespace_id = @p_namespace_id AND l.id < @start_lane
                ORDER BY l.id;

                INSERT INTO @stranded (id)
                SELECT TOP (100) w.id
                FROM @window w
                CROSS APPLY (
                    SELECT TOP (1) m.status_code
                    FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                    WHERE
                        m.lane_id = w.id
                        AND m.lane_id IS NOT NULL
                        AND m.status_code IN (
                            10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                            30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                        )
                    ORDER BY m.job_id
                ) h
                WHERE
                    h.status_code = 15 /* JobStatusCode.Blocked */
                    AND NOT EXISTS (
                        SELECT 1
                        FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                        WHERE
                            o.lane_id = w.id
                            AND o.lane_id IS NOT NULL
                            AND o.status_code IN (
                                10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                                50 /* JobStatusCode.Executing */
                            )
                    )
                ORDER BY w.ord;
            END;

        /* Stuck candidates are read through the filtered ix_runtimes_worker_inflight without holding locks,
           and only those rows are locked below, by primary key: the index is shared by every namespace, so
           holding its keys would make another namespace's sweep skip its own rows under READPAST. */
        DECLARE @stuck TABLE (id BIGINT NOT NULL PRIMARY KEY, lane_id BIGINT NULL);
        INSERT INTO @stuck (id, lane_id)
        SELECT r.job_id, r.lane_id
        FROM acta.runtimes r WITH (INDEX (ix_runtimes_worker_inflight), READPAST)
        WHERE
            r.status_code = 50 /* JobStatusCode.Executing */
            AND r.leased_by_worker_id IS NOT NULL
            AND r.lease_expires_at_utc < @now
            AND r.namespace_id = @p_namespace_id;

        /* Lanes are locked one UPDLOCK seek at a time in id order, skipping a lane another transaction holds,
           whose stuck rows and repair wait for a later pass. */
        DECLARE @candidates TABLE (id BIGINT NOT NULL PRIMARY KEY);
        INSERT INTO @candidates (id)
        SELECT k.lane_id
        FROM @stuck k
        WHERE k.lane_id IS NOT NULL
        UNION
        SELECT s.id
        FROM @stranded s;

        DECLARE @lanes TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @lane_cursor BIGINT = 0, @lane_next BIGINT, @lane_locked BIGINT;
        WHILE 1 = 1
            BEGIN
                SET @lane_next = NULL;
                SELECT TOP (1) @lane_next = c.id
                FROM @candidates c
                WHERE c.id > @lane_cursor
                ORDER BY c.id;

                IF @lane_next IS NULL
                    BREAK;

                SET @lane_locked = NULL;
                SELECT @lane_locked = l.id
                FROM acta.lanes l WITH (UPDLOCK, READPAST, ROWLOCK)
                WHERE l.id = @lane_next;

                IF @lane_locked IS NOT NULL
                    INSERT INTO @lanes (id) VALUES (@lane_locked);

                SET @lane_cursor = @lane_next;
            END;

        /* The walk read without locks, so each stranded lane's head is re-read under its lock and promoted
           only while it is still Blocked and no member runs. */
        UPDATE r
        SET
            status_code = 10 /* JobStatusCode.Ready */,
            next_run_at_utc = CASE WHEN r.next_run_at_utc > @now THEN r.next_run_at_utc ELSE @now END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT INSERTED.job_id INTO @repaired (id)
        FROM @stranded s
        INNER JOIN @lanes e ON e.id = s.id
        CROSS APPLY (
            SELECT TOP (1) m.job_id, m.status_code
            FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
            WHERE
                m.lane_id = s.id
                AND m.lane_id IS NOT NULL
                AND m.status_code IN (
                    10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                    30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                )
            ORDER BY m.job_id
        ) h
        INNER JOIN acta.runtimes r WITH (FORCESEEK) ON r.job_id = h.job_id
        WHERE
            h.status_code = 15 /* JobStatusCode.Blocked */
            AND r.status_code = 15 /* JobStatusCode.Blocked */
            AND NOT EXISTS (
                SELECT 1
                FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                WHERE
                    o.lane_id = s.id
                    AND o.lane_id IS NOT NULL
                    AND o.status_code IN (
                        10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                        50 /* JobStatusCode.Executing */
                    )
            );

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            72 /* EventCode.JobResumed */,
            @now,
            j.namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            j.id,
            j.job_ref,
            r.execution_number,
            COALESCE(j.lineage_root_id, j.id),
            j.definition_id,
            j.tenant_id,
            NULL,
            15 /* JobStatusCode.Blocked */,
            10 /* JobStatusCode.Ready */,
            NULL,
            NULL,
            67 /* EventReasonCode.JobLaneRepaired */,
            N'Lane had no live head; crash recovery released its lowest Blocked member.'
        FROM @repaired x
        INNER JOIN acta.jobs j ON j.id = x.id
        INNER JOIN acta.runtimes r ON r.job_id = x.id
        WHERE j.audit_level_code IN (10 /* DefinitionAuditLevelCode.Failures */, 20 /* DefinitionAuditLevelCode.Audit */);

        WITH stuck AS (
            SELECT
                r.job_id AS id,
                r.status_code AS from_status,
                r.failure_count + 1 AS new_failure_count,
                jd.max_attempts_effective AS max_attempts,
                jd.retention_seconds_effective AS retention_seconds,
                /* The job was parked on THIS slot: the suspend copied the slot's due into
                   next_run_at_utc, so the equality names the wait this attempt woke for, and an
                   unbounded wait (NULL due) matches nothing. Expired means the timeout had resolved. */
                CASE WHEN EXISTS (
                    SELECT 1
                    FROM acta.checkpoints c
                    WHERE
                        c.job_id = r.job_id
                        AND c.kind_code IN (20 /* CheckpointKindCode.Signal */, 50 /* CheckpointKindCode.ChildLatch */)
                        AND c.status_code = 30 /* CheckpointStatusCode.Expired */
                        AND c.due_at_utc = r.next_run_at_utc
                ) THEN 1 ELSE 0 END AS wait_resolved,
                /* MaxAttempts is the one-off retry budget and a slot's failure_count accumulates
                   across occurrences, so a recurring reclaim always re-arms Ready instead of
                   terminally failing the schedule - mirroring ComputeRecurringOutcome on the worker path. */
                CASE WHEN EXISTS (
                    SELECT 1
                    FROM acta.schedules sc
                    WHERE sc.job_id = r.job_id
                ) THEN 1 ELSE 0 END AS is_recurring
            FROM @stuck k
            INNER JOIN acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, FORCESEEK) ON r.job_id = k.id
            INNER JOIN acta.jobs j ON j.id = r.job_id
            INNER JOIN acta.definitions jd ON jd.id = j.definition_id
            WHERE
                r.status_code = 50 /* JobStatusCode.Executing */
                AND r.leased_by_worker_id IS NOT NULL
                AND r.lease_expires_at_utc < @now
                AND r.namespace_id = @p_namespace_id
                AND (r.lane_id IS NULL OR r.lane_id IN (SELECT e.id FROM @lanes e))
        )

        /* Budget-neutral for a resolved wait: the surviving path would have ended this attempt at no
           cost, so the job goes back to Suspended on the same past deadline, unclaimed and uncharged,
           and the replay lands whatever outcome the waiting overload chooses. */
        UPDATE r
        SET
            status_code = CASE
                WHEN s.wait_resolved = 1
                    THEN 20 /* JobStatusCode.Suspended */
                WHEN s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN 200 /* JobStatusCode.Failed */
                ELSE 10  /* JobStatusCode.Ready */
            END,
            failure_count = CASE
                WHEN s.wait_resolved = 1
                    THEN r.failure_count
                ELSE s.new_failure_count
            END,
            next_run_at_utc = CASE
                WHEN s.wait_resolved = 1
                    THEN r.next_run_at_utc
                WHEN s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN r.next_run_at_utc
                ELSE @now
            END,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE
                WHEN s.wait_resolved = 0 AND s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN DATEADD(SECOND, s.retention_seconds, @now)
                ELSE r.retention_until_utc
            END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id, j.job_ref, j.namespace_id, INSERTED.execution_number,
            j.lineage_root_id, j.definition_id, j.tenant_id,
            DELETED.status_code, INSERTED.status_code, j.audit_level_code,
            j.parent_id
        INTO
            @reclaimed (
                id, job_ref, namespace_id, execution_number, lineage_root_id,
                definition_id, tenant_id, from_status_code, to_status_code, audit_level_code, parent_id
            )
        -- FORCESEEK keeps this update on a key seek instead of a lock-escalating scan of runtimes;
        -- see docs/internals/sql-execution-policy.md.
        FROM acta.runtimes r WITH (FORCESEEK)
        INNER JOIN stuck s ON s.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            @now,
            namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            id,
            job_ref,
            execution_number,
            COALESCE(lineage_root_id, id),
            definition_id,
            tenant_id,
            NULL,
            from_status_code,
            to_status_code,
            230 /* ExecutionStatusCode.Orphaned */,
            NULL,
            21 /* EventReasonCode.JobLeaseExpired */,
            /* Suspended is reachable only through the resolved-wait arm above, so the landed status is
               what tells the two messages apart. */
            CASE WHEN to_status_code = 20 /* JobStatusCode.Suspended */
                THEN N'Worker lease expired while an expired wait was resolving; re-armed on the same deadline with no attempt charged.'
                ELSE N'Worker lease expired; reclaimed by crash recovery.'
            END
        FROM @reclaimed
        WHERE audit_level_code IN (10 /* DefinitionAuditLevelCode.Failures */, 20 /* DefinitionAuditLevelCode.Audit */);

        /* A head reclaimed to Failed hands its lane on; a head re-armed Ready keeps it. Promotion runs
           under the lane locks and re-reads each head rather than trusting the walk. */
        UPDATE r
        SET
            status_code = 10 /* JobStatusCode.Ready */,
            next_run_at_utc = CASE WHEN r.next_run_at_utc > @now THEN r.next_run_at_utc ELSE @now END,
            modified_at_utc = @now,
            version = r.version + 1
        FROM @lanes e
        CROSS APPLY (
            SELECT TOP (1) m.job_id, m.status_code
            FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
            WHERE
                m.lane_id = e.id
                AND m.lane_id IS NOT NULL
                AND m.status_code IN (
                    10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                    30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                )
            ORDER BY m.job_id
        ) h
        INNER JOIN acta.runtimes r WITH (FORCESEEK) ON r.job_id = h.job_id
        WHERE
            h.status_code = 15 /* JobStatusCode.Blocked */
            AND r.status_code = 15 /* JobStatusCode.Blocked */
            AND NOT EXISTS (
                SELECT 1
                FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                WHERE
                    o.lane_id = e.id
                    AND o.lane_id IS NOT NULL
                    AND o.status_code IN (
                        10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                        50 /* JobStatusCode.Executing */
                    )
            );

        SELECT
            id AS job_id,
            to_status_code AS to_status,
            parent_id,
            CAST(0 AS TINYINT) AS lane_repaired
        FROM @reclaimed
        UNION ALL
        SELECT
            id AS job_id,
            CAST(10 /* JobStatusCode.Ready */ AS TINYINT) AS to_status,
            NULL AS parent_id,
            CAST(1 AS TINYINT) AS lane_repaired
        FROM @repaired;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

-- GCRA with a reservation; the full contract is on Locks.ReserveRateAsync. A turn is honoured
-- while it is fresh, one second past its instant (one interval when that is longer); a stale one goes
-- back through the meter, so a queue of overdue jobs cannot all start at once after a long stall.

-- The IF NOT EXISTS probe below takes UPDLOCK, HOLDLOCK before the row exists and holds it to commit;
-- the sweep's WITH (UPDLOCK, READPAST) then skips rather than races it, so the charge this call books
-- is always persisted before it admits anything.

-- The clock is read once the bucket row is locked, not when the call began: judged against a stale
-- instant, every call a convoy on this meter delayed would be admitted together the moment the lock
-- freed, four times the contract in one second under a flood of metered claims.
CREATE OR ALTER PROCEDURE acta.reserve_rate
    @p_lock_key VARCHAR(256),
    @p_job_id BIGINT,
    @p_rate_interval_ms INT,
    @p_rate_burst INT,
    @p_grace_seconds INT,
    @p_hold_token UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        -- Everything is judged at the column's precision: a 7-digit reading rounds when it is stored,
        -- so a meter read back can sit half a millisecond ahead of an unrounded now and refuse a
        -- burst's last job. PostgreSQL and SQLite keep one precision in both places by construction.
        DECLARE @now DATETIME2(3);
        DECLARE @reservation VARCHAR(256) = @p_lock_key + '.' + CAST(@p_job_id AS VARCHAR(20));
        -- How far behind now an idle meter is allowed to be, which is what hands out the burst: one
        -- interval short of a whole period, so the burst-th request lands on now and the next waits.
        DECLARE @lookback_ms INT = (@p_rate_burst - 1) * @p_rate_interval_ms;
        -- How long a booked turn stays valid past its instant: a second covers the claim-path pickup
        -- at any rate, and a slower meter keeps its whole interval, so the window is the larger.
        DECLARE @window_ms INT = CASE WHEN @p_rate_interval_ms > 1000 THEN @p_rate_interval_ms ELSE 1000 END;
        DECLARE @consumed TABLE (expires_at_utc DATETIME2(3));
        DECLARE @stored DATETIME2(3);
        DECLARE @due DATETIME2(3);
        DECLARE @turn DATETIME2(3);

        -- The bucket stores the arrival time plus the lookback, so the row expires exactly when an
        -- idle meter stops saying anything a missing one would not. A missing meter starts at now.
        IF NOT EXISTS (SELECT 1 FROM acta.locks WITH (UPDLOCK, HOLDLOCK) WHERE lock_key = @p_lock_key)
            INSERT INTO acta.locks (lock_key, job_id, expires_at_utc, hold_token)
            VALUES (@p_lock_key, @p_job_id, SYSUTCDATETIME(), @p_hold_token);

        -- Held for the rest of the call, so consume, hand back and allocate all decide against one
        -- serialized meter and no instant is ever handed to two jobs.
        SELECT @stored = b.expires_at_utc
        FROM acta.locks AS b WITH (UPDLOCK, HOLDLOCK)
        WHERE b.lock_key = @p_lock_key;

        SET @now = SYSUTCDATETIME();

        -- The OUTPUT decides consumption, never a later absence: the sweep cannot slip between a read
        -- and the delete and give away a free admission. A stale turn is spent here too, then re-metered.
        DELETE FROM acta.locks
        OUTPUT DELETED.expires_at_utc INTO @consumed
        WHERE
            lock_key = @reservation
            AND expires_at_utc <= DATEADD(SECOND, @p_grace_seconds, @now);

        SELECT @due = DATEADD(SECOND, -@p_grace_seconds, c.expires_at_utc) FROM @consumed AS c;

        IF @due IS NOT NULL AND @due >= DATEADD(MILLISECOND, -@window_ms, @now)
            -- Back on time: the bucket counted this job when it allocated the turn, so charging it
            -- again would meter one job twice.
            SELECT @due AS resume_at_utc, CAST(1 AS INT) AS admitted, CAST(0 AS BIGINT) AS wait_ms;
        ELSE
            BEGIN
                IF @due IS NULL
                    -- A turn still ahead of now: the job is early, not owed a new instant.
                    SELECT @turn = DATEADD(SECOND, -@p_grace_seconds, r.expires_at_utc)
                    FROM acta.locks AS r
                    WHERE r.lock_key = @reservation;

                IF @turn IS NOT NULL
                    SELECT @turn AS resume_at_utc, CAST(0 AS INT) AS admitted, DATEDIFF_BIG(MILLISECOND, @now, @turn) AS wait_ms;
                ELSE
                    BEGIN
                        IF @stored < @now
                            SET @stored = @now;
                        SET @turn = DATEADD(MILLISECOND, -@lookback_ms, @stored);

                        UPDATE acta.locks
                        SET
                            job_id = @p_job_id,
                            expires_at_utc = DATEADD(MILLISECOND, @p_rate_interval_ms, @stored),
                            hold_token = @p_hold_token
                        WHERE lock_key = @p_lock_key;

                        IF @turn <= @now
                            SELECT @turn AS resume_at_utc, CAST(1 AS INT) AS admitted, CAST(0 AS BIGINT) AS wait_ms;
                        ELSE
                            BEGIN
                                UPDATE acta.locks
                                SET
                                    job_id = @p_job_id,
                                    expires_at_utc = DATEADD(SECOND, @p_grace_seconds, @turn),
                                    hold_token = @p_hold_token
                                WHERE lock_key = @reservation;

                                IF @@ROWCOUNT = 0
                                    INSERT INTO acta.locks (lock_key, job_id, expires_at_utc, hold_token)
                                    VALUES (@reservation, @p_job_id, DATEADD(SECOND, @p_grace_seconds, @turn), @p_hold_token);

                                -- Measured on this clock so the caller never subtracts a host reading from a database one.
                                SELECT @turn AS resume_at_utc, CAST(0 AS INT) AS admitted, DATEDIFF_BIG(MILLISECOND, @now, @turn) AS wait_ms;
                            END;
                    END;
            END;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.start_step
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_at_most_once BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
        DECLARE @outcome SMALLINT;
        DECLARE @attempt INT;
        DECLARE @version INT;
        DECLARE @next DATETIME2(3) = NULL;
        DECLARE @rfid TINYINT = 0;
        DECLARE @result VARBINARY(MAX) = NULL;
        DECLARE @rcode SMALLINT = NULL;
        DECLARE @rmsg NVARCHAR(512) = NULL;
        DECLARE @state TINYINT;
        DECLARE @existing_next DATETIME2(3);

        SELECT
            @state = status_code,
            @attempt = attempt_number,
            @version = version,
            @existing_next = next_retry_at_utc,
            @rfid = result_format_id,
            @result = result,
            @rcode = reason_code,
            @rmsg = reason_message
        FROM acta.steps WITH (UPDLOCK, HOLDLOCK, INDEX (ux_steps_job_name))
        WHERE job_id = @p_job_id AND name = @p_name;

        IF @state IS NULL
            BEGIN
                INSERT INTO acta.steps (
                    job_id, name, status_code, attempt_number,
                    result_format_id, created_at_utc, modified_at_utc, version
                )
                VALUES (
                    @p_job_id, @p_name, 10 /* StepStatusCode.Pending */, 1,
                    0 /* JobPayloadFormat.None */, @now, @now, 0
                );

                SET @outcome = 1 /* StartStepOutcomeCode.Invoke */;
                SET @attempt = 1;
                SET @version = 0;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
                SET @next = NULL;
            END
        ELSE IF @state = 100 /* StepStatusCode.Succeeded */
            BEGIN
                SET @outcome = 3 /* StartStepOutcomeCode.ReplaySuccess */;
                SET @next = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @state = 200 /* StepStatusCode.Exhausted */
            BEGIN
                SET @outcome = 4 /* StartStepOutcomeCode.Exhausted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
            END
        ELSE IF @state = 230 /* StepStatusCode.Interrupted */
            BEGIN
            -- Terminal at-most-once ambiguity from an earlier replay; re-throw consistently, no mutation.
                SET @outcome = 5 /* StartStepOutcomeCode.Interrupted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @existing_next IS NOT NULL AND @existing_next > @now
            BEGIN
                SET @outcome = 2 /* StartStepOutcomeCode.Suspend */;
                SET @next = @existing_next;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @p_at_most_once = 1
            BEGIN
            -- Pending slot re-entered on replay under AtMostOnce: the worker died after start_step recorded
            -- the pending row but before complete_step. Do not re-invoke; terminalize the row Interrupted
            -- (one transition, one version bump) and let the orchestration throw StepInterruptedException.
                UPDATE acta.steps
                SET
                    status_code = 230 /* StepStatusCode.Interrupted */,
                    next_retry_at_utc = NULL,
                    reason_code = 63 /* EventReasonCode.JobStepInterrupted */,
                    reason_message = N'At-most-once step re-entered before completion; outcome unknown.',
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name;

                SET @version = @version + 1;
                SET @outcome = 5 /* StartStepOutcomeCode.Interrupted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE
            BEGIN
                UPDATE acta.steps
                SET
                    attempt_number = attempt_number + 1,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name;

                SET @attempt = @attempt + 1;
                SET @version = @version + 1;
                SET @outcome = 1 /* StartStepOutcomeCode.Invoke */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END

        SELECT
            @outcome AS outcome_code,
            @attempt AS attempt_number,
            @version AS version,
            @next AS next_retry_at_utc,
            @rfid AS result_format_id,
            @result AS result,
            @rcode AS reason_code,
            @rmsg AS reason_message;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

/* Slot-locked arbiter for one durable wait: Set wins even past the due, an overdue Pending flips to
   Expired, Expired replays TimedOut forever. */
/* Arming is one-directional. A NULL due_at_utc is armed when the caller carries a timeout, so code
   redeployed with a bound can un-strand a wait suspended without one; a stored due is never
   overwritten, never extended, and never cleared by a subsequent unbounded call. */
/* The read below needs no re-read after a lost insert the way pg's does: (UPDLOCK, HOLDLOCK) takes a
   key-range lock over the absent slot, so a concurrent first arrival waits here and then reads the
   winner's row, arriving at the same resolution instead of racing the insert. */
/* A wait this call armed suspends once, even with an already-elapsed deadline: the arm is the last
   act of its branch, so only a wait armed by an earlier call can expire. Pg states the same rule. */
CREATE OR ALTER PROCEDURE acta.wait_signal
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128),
    @p_timeout_seconds INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
        DECLARE @state TINYINT, @fmt TINYINT = 0;
        DECLARE @val VARBINARY(MAX) = NULL;
        DECLARE @due DATETIME2(3) = NULL;
        DECLARE @outcome SMALLINT;

        SELECT
            @state = status_code,
            @fmt = value_format_id,
            @val = value,
            @due = due_at_utc
        FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

        IF @state = 20 /* CheckpointStatusCode.Set */
            BEGIN
                SET @outcome = 2 /* WaitSignalOutcomeCode.ContinueSet */;
            END
        ELSE IF @state = 30 /* CheckpointStatusCode.Expired */
            BEGIN
                SET @outcome = 3 /* WaitSignalOutcomeCode.TimedOut */;
                SET @fmt = 0 /* JobPayloadFormat.None */;
                SET @val = NULL;
            END
        ELSE IF @state = 10 /* CheckpointStatusCode.Pending */ AND @due IS NOT NULL AND @due <= @now
            BEGIN
                UPDATE acta.checkpoints
                SET
                    status_code = 30 /* CheckpointStatusCode.Expired */,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

                SET @outcome = 3 /* WaitSignalOutcomeCode.TimedOut */;
                SET @fmt = 0 /* JobPayloadFormat.None */;
                SET @val = NULL;
            END
        ELSE
            BEGIN
                IF @state IS NULL
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name, status_code, due_at_utc, value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name, 10 /* CheckpointStatusCode.Pending */,
                            CASE WHEN @p_timeout_seconds IS NULL THEN NULL ELSE DATEADD(SECOND, @p_timeout_seconds, @now) END,
                            0 /* JobPayloadFormat.None */, NULL, @now, @now, 0
                        );
                    END
                ELSE IF @state = 10 /* CheckpointStatusCode.Pending */ AND @due IS NULL AND @p_timeout_seconds IS NOT NULL
                    BEGIN
                        UPDATE acta.checkpoints
                        SET
                            due_at_utc = DATEADD(SECOND, @p_timeout_seconds, @now),
                            modified_at_utc = @now,
                            version = version + 1
                        WHERE
                            job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name
                            AND status_code = 10 /* CheckpointStatusCode.Pending */
                            AND due_at_utc IS NULL;
                    END
                SET @outcome = 1 /* WaitSignalOutcomeCode.SuspendPending */;
                SET @fmt = 0 /* JobPayloadFormat.None */;
                SET @val = NULL;
            END

        SELECT
            @outcome AS outcome_code,
            @fmt AS value_format_id,
            @val AS value;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER VIEW acta.alerts_view AS
SELECT
    a.id AS alert_id,
    a.alert_ref,
    ns.name AS namespace,
    a.job_id,
    a.job_ref,
    j.definition_id,
    d.name AS job_name,
    CASE a.origin_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'automatic' WHEN 20 THEN 'manual' END AS origin,
    a.origin_code,
    CASE a.severity_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'info' WHEN 20 THEN 'warning' WHEN 30 THEN 'error' WHEN 40 THEN 'critical' END AS severity,
    a.severity_code,
    CASE a.kind_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'first-failure' WHEN 20 THEN 'threshold-reached' WHEN 30 THEN 'final-failure' WHEN 40 THEN 'manual' END AS kind,
    a.kind_code,
    CASE a.delivery_status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'pending' WHEN 20 THEN 'retry-after' WHEN 30 THEN 'suppressed' WHEN 100 THEN 'delivered' WHEN 200 THEN 'failed' END AS delivery_status,
    a.delivery_status_code,
    a.title,
    a.message,
    a.channel_name,
    a.deduplication_key,
    a.occurrence_count,
    a.resolved_at_utc,
    a.retry_count,
    a.retry_after_utc,
    a.created_at_utc,
    a.modified_at_utc,
    a.version
FROM acta.alerts AS a
JOIN acta.namespaces AS ns ON ns.id = a.namespace_id
LEFT JOIN acta.jobs AS j ON j.id = a.job_id
LEFT JOIN acta.definitions AS d ON d.id = j.definition_id
GO

CREATE OR ALTER VIEW acta.checkpoints_view AS
SELECT
    c.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    c.name AS checkpoint_name,
    CASE c.kind_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'variable' WHEN 20 THEN 'signal' WHEN 30 THEN 'timer' WHEN 40 THEN 'progress' WHEN 50 THEN 'child-latch' END AS kind,
    c.kind_code,
    CASE c.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'pending' WHEN 20 THEN 'set' WHEN 30 THEN 'expired' WHEN 100 THEN 'consumed' END AS state,
    c.status_code,
    c.due_at_utc,
    CASE c.value_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', c.value_format_id)
    END AS value_format,
    CASE
        WHEN
            c.value_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(c.value AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS value_text,
    c.created_at_utc,
    c.modified_at_utc,
    c.version
FROM acta.checkpoints AS c
JOIN acta.jobs AS j ON j.id = c.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
GO

CREATE OR ALTER VIEW acta.definitions_view AS
SELECT
    d.id AS definition_id,
    ns.name AS namespace,
    d.name AS job_name,
    CASE d.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'active' WHEN 240 THEN 'retired' END AS status,
    d.status_code,
    d.definition_hash,
    d.manifest_generation_at_utc,
    d.input_type_name,
    d.input_format_name,
    d.output_type_name,
    d.output_format_name,
    CASE d.priority_code_effective WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    d.priority_code_effective AS priority_code,
    d.priority_code AS priority_default_code,
    d.priority_code_override AS priority_override_code,
    d.max_attempts_effective AS max_attempts,
    d.max_attempts AS max_attempts_default,
    d.max_attempts_override,
    d.concurrency_limit_effective AS concurrency_limit,
    d.concurrency_limit AS concurrency_limit_default,
    d.concurrency_limit_override,
    d.rate_limit_effective AS rate_limit,
    d.rate_limit AS rate_limit_default,
    d.rate_limit_override,
    d.rate_name,
    d.backoff_effective AS backoff,
    d.backoff AS backoff_default,
    d.backoff_override,
    d.execution_timeout_seconds_effective AS execution_timeout_seconds,
    d.execution_timeout_seconds AS execution_timeout_seconds_default,
    d.execution_timeout_seconds_override,
    d.deadline_seconds_effective AS deadline_seconds,
    d.deadline_seconds AS deadline_seconds_default,
    d.deadline_seconds_override,
    CASE d.deadline_behavior_code_effective WHEN 0 THEN 'unspecified' WHEN 10 THEN 'strict' WHEN 20 THEN 'advisory' END AS deadline_behavior,
    d.deadline_behavior_code_effective AS deadline_behavior_code,
    d.deadline_behavior_code AS deadline_behavior_default_code,
    d.deadline_behavior_code_override AS deadline_behavior_override_code,
    d.retention_seconds_effective AS retention_seconds,
    d.retention_seconds AS retention_seconds_default,
    d.retention_seconds_override,
    CASE d.audit_level_code_effective WHEN 0 THEN 'off' WHEN 10 THEN 'failures' WHEN 20 THEN 'audit' END AS audit_level,
    d.audit_level_code_effective AS audit_level_code,
    d.audit_level_code AS audit_level_default_code,
    d.audit_level_code_override AS audit_level_override_code,
    CASE d.alert_profile_code_effective WHEN 0 THEN 'none' WHEN 10 THEN 'on-failure' WHEN 20 THEN 'info' WHEN 30 THEN 'on-terminal' WHEN 40 THEN 'sys-critical' END AS alert_profile,
    d.alert_profile_code_effective AS alert_profile_code,
    d.alert_profile_code AS alert_profile_default_code,
    d.alert_profile_code_override AS alert_profile_override_code,
    d.alert_channel_name_effective AS alert_channel_name,
    d.alert_channel_name AS alert_channel_name_default,
    d.alert_channel_name_override,
    d.runbook_url_effective AS runbook_url,
    d.runbook_url AS runbook_url_default,
    d.runbook_url_override,
    d.created_at_utc,
    d.modified_at_utc,
    d.version
FROM acta.definitions AS d
JOIN acta.namespaces AS ns ON ns.id = d.namespace_id
GO

CREATE OR ALTER VIEW acta.events_view AS
SELECT
    e.id AS event_id,
    e.created_at_utc,
    ns.name AS namespace,
    e.job_id,
    e.job_ref,
    e.lineage_root_id AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    e.definition_id,
    d.name AS job_name,
    CASE e.event_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'tenant.suspended' WHEN 11 THEN 'tenant.resumed' WHEN 12 THEN 'tenant.updated' WHEN 20 THEN 'namespace.suspended' WHEN 21 THEN 'namespace.resumed' WHEN 22 THEN 'namespace.updated' WHEN 30 THEN 'definition.overrides-updated' WHEN 31 THEN 'definition.retired' WHEN 40 THEN 'job.execution-started' WHEN 41 THEN 'job.execution-finished' WHEN 50 THEN 'job.recurring-rolled-over' WHEN 60 THEN 'job.suspended' WHEN 61 THEN 'job.rescheduled' WHEN 70 THEN 'job.cancelled' WHEN 71 THEN 'job.paused' WHEN 72 THEN 'job.resumed' WHEN 73 THEN 'job.restarted' WHEN 74 THEN 'job.reprioritized' WHEN 75 THEN 'job.purged' WHEN 76 THEN 'job.input-amended' WHEN 80 THEN 'job.signal-raised' WHEN 81 THEN 'job.state-reset' WHEN 90 THEN 'job.note-recorded' WHEN 100 THEN 'schedule.paused' WHEN 101 THEN 'schedule.resumed' WHEN 102 THEN 'schedule.pause-expired' WHEN 103 THEN 'schedule.overrides-updated' WHEN 104 THEN 'schedule.triggered' WHEN 120 THEN 'worker.started' WHEN 121 THEN 'worker.stopped' WHEN 122 THEN 'worker.died' WHEN 140 THEN 'alert.acknowledged' WHEN 141 THEN 'alert.resolved' WHEN 180 THEN 'outbox.requeued' WHEN 181 THEN 'outbox.discarded' END AS event,
    e.event_code,
    CASE e.actor_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'sys' WHEN 20 THEN 'operator' WHEN 50 THEN 'job' WHEN 70 THEN 'worker' END AS actor_kind,
    e.actor_code,
    e.actor,
    CASE e.from_status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'ready' WHEN 15 THEN 'blocked' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS from_status,
    e.from_status_code,
    CASE e.to_status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'ready' WHEN 15 THEN 'blocked' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS to_status,
    e.to_status_code,
    CASE e.execution_status_code WHEN 0 THEN 'unspecified' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 150 THEN 'rescheduled' WHEN 151 THEN 'suspended' WHEN 152 THEN 'paused' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' WHEN 230 THEN 'orphaned' END AS execution_status,
    e.execution_status_code,
    CASE e.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.concurrency-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 65 THEN 'job.wait-timed-out' WHEN 66 THEN 'job.rate-limited' WHEN 67 THEN 'job.lane-repaired' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    e.reason_code,
    e.reason_message,
    CASE e.detail_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', e.detail_format_id)
    END AS detail_format,
    CASE
        WHEN
            e.detail_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(e.detail AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS detail_text,
    e.worker_id,
    wkr.worker_ref,
    e.execution_number,
    e.duration_ms,
    e.tenant_id
FROM acta.events AS e
JOIN acta.namespaces AS ns ON ns.id = e.namespace_id
LEFT JOIN acta.definitions AS d ON d.id = e.definition_id
LEFT JOIN acta.jobs AS root ON root.id = e.lineage_root_id
LEFT JOIN acta.workers AS wkr ON wkr.id = e.worker_id
GO

CREATE OR ALTER VIEW acta.jobs_view AS
SELECT
    j.id AS job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    CASE r.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'ready' WHEN 15 THEN 'blocked' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS status,
    r.status_code,
    j.deduplication_key,
    j.correlation_key,
    j.concurrency_key,
    j.parent_id,
    COALESCE(j.lineage_root_id, j.id) AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    j.tenant_id,
    t.tenant_name,
    CASE r.priority_code WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    r.priority_code,
    CASE j.input_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', j.input_format_id)
    END AS input_format,
    CASE
        WHEN
            j.input_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(j.input AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS input_text,
    lr.execution_number AS last_result_execution_number,
    CASE lr.result_format_id
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CASE WHEN lr.result_format_id IS NULL THEN NULL ELSE CONCAT('custom-', lr.result_format_id) END
    END AS last_result_format,
    CASE
        WHEN
            lr.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(lr.result AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS last_result_text,
    lr.created_at_utc AS last_result_created_at_utc,
    r.next_run_at_utc,
    r.execution_number,
    r.failure_count,
    r.leased_by_worker_id,
    w.host AS leased_by_worker_host,
    r.lease_expires_at_utc,
    r.retention_until_utc,
    j.created_at_utc,
    r.modified_at_utc,
    r.version,
    lane.name AS lane
FROM acta.jobs AS j
JOIN acta.runtimes AS r ON r.job_id = j.id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
LEFT JOIN acta.jobs AS root ON root.id = COALESCE(j.lineage_root_id, j.id)
LEFT JOIN acta.tenants AS t ON t.id = j.tenant_id
LEFT JOIN acta.workers AS w ON w.id = r.leased_by_worker_id
LEFT JOIN acta.lanes AS lane ON lane.id = r.lane_id
LEFT JOIN acta.results AS lr
    ON
        lr.job_id = j.id
        AND lr.execution_number = (
            SELECT MAX(rr.execution_number) FROM acta.results AS rr
            WHERE rr.job_id = j.id
        )
GO

CREATE OR ALTER VIEW acta.schedules_view AS
SELECT
    s.id AS schedule_id,
    ns.name AS namespace,
    s.job_id,
    j.job_ref,
    s.definition_id,
    d.name AS job_name,
    s.name AS schedule_name,
    CASE s.origin_code WHEN 0 THEN 'unspecified' WHEN 20 THEN 'operator' WHEN 40 THEN 'definition' END AS origin,
    s.origin_code,
    CASE s.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'active' WHEN 30 THEN 'paused' WHEN 230 THEN 'orphaned' END AS status,
    s.status_code,
    s.expression_effective,
    s.expression,
    s.expression_override,
    s.time_zone_id_effective,
    s.time_zone_id,
    s.time_zone_id_override,
    CASE s.expression_kind_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'cron' WHEN 20 THEN 'interval' END AS expression_kind,
    s.expression_kind_code,
    CASE s.misfire_strategy_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'catch-up-once' WHEN 20 THEN 'skip' END AS misfire_strategy,
    s.misfire_strategy_code,
    s.next_run_at_utc,
    s.last_occurrence_at_utc,
    s.paused_until_utc,
    s.description,
    s.reason_message,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.schedules AS s
JOIN acta.namespaces AS ns ON ns.id = s.namespace_id
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.definitions AS d ON d.id = s.definition_id
GO

CREATE OR ALTER VIEW acta.steps_view AS
SELECT
    s.id AS step_id,
    s.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    s.name AS step_name,
    CASE s.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'pending' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'exhausted' WHEN 230 THEN 'interrupted' END AS state,
    s.status_code,
    s.attempt_number,
    s.next_retry_at_utc,
    CASE s.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.concurrency-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 65 THEN 'job.wait-timed-out' WHEN 66 THEN 'job.rate-limited' WHEN 67 THEN 'job.lane-repaired' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    s.reason_code,
    s.reason_message,
    CASE s.result_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', s.result_format_id)
    END AS result_format,
    CASE
        WHEN
            s.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(s.result AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS result_text,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.steps AS s
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
GO

CREATE OR ALTER VIEW acta.tags_view AS
SELECT
    CASE t.scope_code WHEN 0 THEN 'unspecified' WHEN 20 THEN 'tenant' WHEN 30 THEN 'namespace' WHEN 40 THEN 'definition' WHEN 50 THEN 'job' WHEN 60 THEN 'schedule' WHEN 70 THEN 'worker' WHEN 80 THEN 'alert' WHEN 90 THEN 'event' END AS scope,
    t.scope_code,
    t.scope_id,
    ns.name AS namespace,
    t.namespace_id,
    t.name AS tag_name,
    t.value AS tag_value,
    t.value_search AS tag_value_search
FROM acta.tags AS t
LEFT JOIN acta.namespaces AS ns ON ns.id = t.namespace_id
GO

CREATE OR ALTER VIEW acta.workers_view AS
SELECT
    w.id AS worker_id,
    w.worker_ref,
    ns.name AS namespace,
    CASE w.status_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'active' WHEN 80 THEN 'draining' WHEN 100 THEN 'stopped' WHEN 200 THEN 'dead' END AS status,
    w.status_code,
    w.deployment_version,
    w.host,
    w.engine_version,
    w.dotnet_version,
    w.process_id,
    w.max_concurrency,
    w.last_seen_at_utc,
    w.created_at_utc,
    w.modified_at_utc,
    w.version
FROM acta.workers AS w
JOIN acta.namespaces AS ns ON ns.id = w.namespace_id
GO


