SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO


CREATE OR ALTER PROCEDURE acta.claim_jobs
    @p_namespace_id INT,
    @p_leased_by_worker_id INT,
    @p_claim_limit INT,
    @p_lease_ttl_seconds INT,
    @p_excluded_definition_ids NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @lease_expires DATETIME2(3) = DATEADD(SECOND, @p_lease_ttl_seconds, @now);
        /* Dueness compares at the column's DATETIME2(3) precision: enqueue rounds next_run_at_utc up to
           0.5 ms into the future, so a full-precision @now can transiently see a just-enqueued row as
           not yet due. Rounding is monotonic, so the same-precision comparison never can. */
        DECLARE @due_now DATETIME2(3) = @now;

        /* Rolling-deploy exclusion: the definitions this worker already bounced for want of a handler,
           passed as JSON array text. Expanded once here so neither the claim nor the horizon pays for
           OPENJSON per row, and counted so the healthy fleet's empty set short-circuits both. */
        DECLARE @excluded TABLE (definition_id INT NOT NULL PRIMARY KEY);
        IF @p_excluded_definition_ids IS NOT NULL
            INSERT INTO @excluded (definition_id)
            SELECT CAST(value AS INT) FROM OPENJSON(@p_excluded_definition_ids);
        DECLARE @excluded_count INT = (SELECT COUNT(*) FROM @excluded);

        DECLARE
            @claimed TABLE
            (
                id BIGINT NOT NULL PRIMARY KEY,
                job_ref UNIQUEIDENTIFIER NOT NULL,
                namespace_id INT NOT NULL,
                definition_id INT NOT NULL,
                tenant_id INT NULL,
                execution_number INT NOT NULL,
                deduplication_key VARCHAR(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
                correlation_key VARCHAR(64) NULL,
                concurrency_key VARCHAR(128) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
                input_format_id TINYINT NOT NULL,
                input VARBINARY(MAX) NULL,
                next_run_at_utc DATETIME2(3) NULL,
                created_at_utc DATETIME2(3) NOT NULL,
                failure_count INT NOT NULL,
                lane_id BIGINT NULL,
                parent_id BIGINT NULL
            );

        /* Every JobPriorityCode, listed once: the claim seeks each band in turn and the horizon reads each band's head. */
        DECLARE @bands TABLE (priority_code TINYINT NOT NULL PRIMARY KEY);
        INSERT INTO @bands (priority_code)
        VALUES
            (100 /* JobPriorityCode.Realtime */),
            (85 /* JobPriorityCode.Critical */),
            (70 /* JobPriorityCode.High */),
            (50 /* JobPriorityCode.Normal */),
            (0 /* JobPriorityCode.Bulk */);

        DECLARE @candidates TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @remaining INT = @p_claim_limit;
        DECLARE @band TINYINT = (SELECT MAX(priority_code) FROM @bands);

        /* One seek per band, highest band first, each stopping at the band's first row not yet due. The
           UPDLOCK holds every candidate to the end of the transaction, so the update below finds each one
           as this loop left it. */
        WHILE @band IS NOT NULL AND @remaining > 0
            BEGIN
                /* Pure claim-index seek on ix_runtimes_claim_ready via the denormalized namespace; concurrency-key admission is
                   executor-owned (lock store) after the start CAS, and the one jobs lookup is the exclusion below. */
                INSERT INTO @candidates (id)
                SELECT TOP (@remaining) r.job_id
                FROM acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, READCOMMITTEDLOCK)
                WHERE
                    r.namespace_id = @p_namespace_id
                    AND r.priority_code = @band
                    /* ix_runtimes_claim_ready's filter restated whole: filtered-index matching takes top-level AND-terms
                       only, and without it the claim scans runtimes and widens its UPDLOCK footprint to match. Ready always
                       carries its due instant (ck_runtimes_ready_due); a Suspended NULL never comes due. */
                    AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */)
                    AND r.next_run_at_utc IS NOT NULL
                    AND r.next_run_at_utc <= @due_now
                    /* Empty on a healthy fleet, so the count test settles it before the jobs lookup and
                       the seek above stays as it was. */
                    AND (
                        @excluded_count = 0
                        OR NOT EXISTS (
                            SELECT 1
                            FROM acta.jobs j
                            WHERE j.id = r.job_id AND j.definition_id IN (SELECT e.definition_id FROM @excluded e)
                        )
                    )
                ORDER BY
                    r.next_run_at_utc ASC,
                    r.job_id ASC;

                SET @remaining -= @@ROWCOUNT;
                SET @band = (SELECT MAX(priority_code) FROM @bands WHERE priority_code < @band);
            END

        UPDATE r
        SET
            status_code = 50 /* JobStatusCode.Executing */,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = @p_leased_by_worker_id,
            lease_expires_at_utc = @lease_expires,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id,
            j.job_ref,
            j.namespace_id,
            j.definition_id,
            j.tenant_id,
            INSERTED.execution_number,
            j.deduplication_key,
            j.correlation_key,
            j.concurrency_key,
            j.input_format_id,
            j.input,
            INSERTED.next_run_at_utc,
            j.created_at_utc,
            INSERTED.failure_count,
            INSERTED.lane_id,
            j.parent_id
        INTO
            @claimed (
                id, job_ref, namespace_id, definition_id, tenant_id, execution_number,
                deduplication_key, correlation_key, concurrency_key,
                input_format_id, input, next_run_at_utc, created_at_utc,
                failure_count, lane_id, parent_id
            )
        -- FORCESEEK keeps this update on a key seek instead of a lock-escalating scan of runtimes. The seek above holds
        -- claim-index keys, so READPAST skips a row a verb holds instead of waiting for it, which would invert the lock
        -- order (docs/internals/sql-execution-policy.md); a skipped candidate is simply not claimed.
        FROM acta.runtimes r WITH (INDEX (pk_runtimes), FORCESEEK, ROWLOCK, READPAST)
        INNER JOIN @candidates c ON c.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        IF EXISTS (SELECT 1 FROM @claimed)
            BEGIN
                SELECT
                    id,
                    namespace_id,
                    definition_id,
                    execution_number,
                    deduplication_key,
                    correlation_key,
                    concurrency_key,
                    input_format_id,
                    input,
                    next_run_at_utc,
                    @lease_expires AS lease_expires_at_utc,
                    created_at_utc,
                    failure_count,
                    job_ref,
                    tenant_id,
                    CAST(NULL AS DATETIME2(7)) AS db_now,
                    CAST(NULL AS DATETIME2(3)) AS next_ready_at_utc,
                    lane_id,
                    parent_id
                FROM @claimed
                ORDER BY id;
            END
        ELSE
            BEGIN
                SELECT
                    CAST(NULL AS BIGINT) AS id,
                    CAST(NULL AS INT) AS namespace_id,
                    CAST(NULL AS INT) AS definition_id,
                    CAST(NULL AS INT) AS execution_number,
                    CAST(NULL AS VARCHAR(128)) AS deduplication_key,
                    CAST(NULL AS VARCHAR(64)) AS correlation_key,
                    CAST(NULL AS VARCHAR(128)) AS concurrency_key,
                    CAST(NULL AS TINYINT) AS input_format_id,
                    CAST(NULL AS VARBINARY(MAX)) AS input,
                    CAST(NULL AS DATETIME2(3)) AS next_run_at_utc,
                    CAST(NULL AS DATETIME2(3)) AS lease_expires_at_utc,
                    CAST(NULL AS DATETIME2(3)) AS created_at_utc,
                    CAST(NULL AS INT) AS failure_count,
                    CAST(NULL AS UNIQUEIDENTIFIER) AS job_ref,
                    CAST(NULL AS INT) AS tenant_id,
                    @now AS db_now,
                    /* The earliest head across the bands: each band's first index row is its earliest instant. */
                    (
                        SELECT MIN(head.next_run_at_utc)
                        FROM @bands b
                        CROSS APPLY (
                            SELECT TOP (1) r.next_run_at_utc
                            FROM acta.runtimes r
                            WHERE
                                r.namespace_id = @p_namespace_id
                                AND r.priority_code = b.priority_code
                                AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */)
                                AND r.next_run_at_utc IS NOT NULL
                                /* Excluded rows are invisible to this worker's horizon too: a horizon at or
                                   before now is what tells the caller to retry at the anti-spin floor, so
                                   counting rows this worker will never claim would spin it. */
                                AND (
                                    @excluded_count = 0
                                    OR NOT EXISTS (
                                        SELECT 1
                                        FROM acta.jobs j
                                        WHERE j.id = r.job_id AND j.definition_id IN (SELECT e.definition_id FROM @excluded e)
                                    )
                                )
                            ORDER BY r.next_run_at_utc ASC
                        ) head
                    ) AS next_ready_at_utc,
                    CAST(NULL AS BIGINT) AS lane_id,
                    CAST(NULL AS BIGINT) AS parent_id;
            END

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE acta.reclaim_stuck_jobs
    @p_namespace_id INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

        DECLARE
            @reclaimed TABLE
            (
                id BIGINT NOT NULL PRIMARY KEY,
                job_ref UNIQUEIDENTIFIER NOT NULL,
                namespace_id INT NOT NULL,
                execution_number INT NOT NULL,
                lineage_root_id BIGINT NULL,
                definition_id INT NOT NULL,
                tenant_id INT NULL,
                worker_id INT NOT NULL,
                from_status_code TINYINT NOT NULL,
                to_status_code TINYINT NOT NULL,
                audit_level_code TINYINT NOT NULL,
                parent_id BIGINT NULL
            );

        /* A pass visits at most 1,000 of the namespace's lanes from a random lane id with wrap and repairs at
           most 100 stranded ones in visiting order (docs/internals/sql-execution-policy.md, "Lane lock order").
           Each head is sought through ix_runtimes_lane, named because a small runtimes table tempts a scan. */
        DECLARE @window TABLE (ord INT IDENTITY (1, 1) PRIMARY KEY, id BIGINT NOT NULL);
        DECLARE @stranded TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @repaired TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @min_lane BIGINT, @max_lane BIGINT, @start_lane BIGINT, @window_count INT;
        SELECT @min_lane = MIN(l.id), @max_lane = MAX(l.id) FROM acta.lanes l;
        IF @max_lane IS NOT NULL
            BEGIN
                SET @start_lane = @min_lane + CAST(FLOOR(RAND(CHECKSUM(NEWID())) * (@max_lane - @min_lane + 1)) AS BIGINT);
                INSERT INTO @window (id)
                SELECT TOP (1000) l.id
                FROM acta.lanes l
                WHERE l.namespace_id = @p_namespace_id AND l.id >= @start_lane
                ORDER BY l.id;
                SET @window_count = @@ROWCOUNT;
                INSERT INTO @window (id)
                SELECT TOP (1000 - @window_count) l.id
                FROM acta.lanes l
                WHERE l.namespace_id = @p_namespace_id AND l.id < @start_lane
                ORDER BY l.id;

                INSERT INTO @stranded (id)
                SELECT TOP (100) w.id
                FROM @window w
                CROSS APPLY (
                    SELECT TOP (1) m.status_code
                    FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                    WHERE
                        m.lane_id = w.id
                        AND m.lane_id IS NOT NULL
                        AND m.status_code IN (
                            10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                            30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                        )
                    ORDER BY m.job_id
                ) h
                WHERE
                    h.status_code = 15 /* JobStatusCode.Blocked */
                    AND NOT EXISTS (
                        SELECT 1
                        FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                        WHERE
                            o.lane_id = w.id
                            AND o.lane_id IS NOT NULL
                            AND o.status_code IN (
                                10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                                50 /* JobStatusCode.Executing */
                            )
                    )
                ORDER BY w.ord;
            END;

        /* Stuck candidates are read through the filtered ix_runtimes_worker_inflight without holding locks,
           and only those rows are locked below, by primary key: the index is shared by every namespace, so
           holding its keys would make another namespace's sweep skip its own rows under READPAST. */
        DECLARE @stuck TABLE (id BIGINT NOT NULL PRIMARY KEY, lane_id BIGINT NULL);
        INSERT INTO @stuck (id, lane_id)
        SELECT r.job_id, r.lane_id
        FROM acta.runtimes r WITH (INDEX (ix_runtimes_worker_inflight), READPAST)
        WHERE
            r.status_code = 50 /* JobStatusCode.Executing */
            AND r.leased_by_worker_id IS NOT NULL
            AND r.lease_expires_at_utc < @now
            AND r.namespace_id = @p_namespace_id;

        /* Lanes are locked one UPDLOCK seek at a time in id order, skipping a lane another transaction holds,
           whose stuck rows and repair wait for a later pass. */
        DECLARE @candidates TABLE (id BIGINT NOT NULL PRIMARY KEY);
        INSERT INTO @candidates (id)
        SELECT k.lane_id
        FROM @stuck k
        WHERE k.lane_id IS NOT NULL
        UNION
        SELECT s.id
        FROM @stranded s;

        DECLARE @lanes TABLE (id BIGINT NOT NULL PRIMARY KEY);
        DECLARE @lane_cursor BIGINT = 0, @lane_next BIGINT, @lane_locked BIGINT;
        WHILE 1 = 1
            BEGIN
                SET @lane_next = NULL;
                SELECT TOP (1) @lane_next = c.id
                FROM @candidates c
                WHERE c.id > @lane_cursor
                ORDER BY c.id;

                IF @lane_next IS NULL
                    BREAK;

                SET @lane_locked = NULL;
                SELECT @lane_locked = l.id
                FROM acta.lanes l WITH (UPDLOCK, READPAST, ROWLOCK)
                WHERE l.id = @lane_next;

                IF @lane_locked IS NOT NULL
                    INSERT INTO @lanes (id) VALUES (@lane_locked);

                SET @lane_cursor = @lane_next;
            END;

        /* The walk read without locks, so each stranded lane's head is re-read under its lock and promoted
           only while it is still Blocked and no member runs. */
        UPDATE r
        SET
            status_code = 10 /* JobStatusCode.Ready */,
            next_run_at_utc = CASE WHEN r.next_run_at_utc > @now THEN r.next_run_at_utc ELSE @now END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT INSERTED.job_id INTO @repaired (id)
        FROM @stranded s
        INNER JOIN @lanes e ON e.id = s.id
        CROSS APPLY (
            SELECT TOP (1) m.job_id, m.status_code
            FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
            WHERE
                m.lane_id = s.id
                AND m.lane_id IS NOT NULL
                AND m.status_code IN (
                    10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                    30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                )
            ORDER BY m.job_id
        ) h
        INNER JOIN acta.runtimes r WITH (FORCESEEK) ON r.job_id = h.job_id
        WHERE
            h.status_code = 15 /* JobStatusCode.Blocked */
            AND r.status_code = 15 /* JobStatusCode.Blocked */
            AND NOT EXISTS (
                SELECT 1
                FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                WHERE
                    o.lane_id = s.id
                    AND o.lane_id IS NOT NULL
                    AND o.status_code IN (
                        10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                        50 /* JobStatusCode.Executing */
                    )
            );

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            72 /* EventCode.JobResumed */,
            @now,
            j.namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            j.id,
            j.job_ref,
            r.execution_number,
            COALESCE(j.lineage_root_id, j.id),
            j.definition_id,
            j.tenant_id,
            NULL,
            15 /* JobStatusCode.Blocked */,
            10 /* JobStatusCode.Ready */,
            NULL,
            NULL,
            67 /* EventReasonCode.JobLaneRepaired */,
            N'Lane had no live head; crash recovery released its lowest Blocked member.'
        FROM @repaired x
        INNER JOIN acta.jobs j ON j.id = x.id
        INNER JOIN acta.runtimes r ON r.job_id = x.id
        WHERE j.audit_level_code IN (10 /* DefinitionAuditLevelCode.Failures */, 20 /* DefinitionAuditLevelCode.Audit */);

        WITH stuck AS (
            SELECT
                r.job_id AS id,
                r.status_code AS from_status,
                r.failure_count + 1 AS new_failure_count,
                jd.max_attempts_effective AS max_attempts,
                jd.retention_seconds_effective AS retention_seconds,
                /* The job was parked on THIS slot: the suspend copied the slot's due into
                   next_run_at_utc, so the equality names the wait this attempt woke for, and an
                   unbounded wait (NULL due) matches nothing. Expired means the timeout had resolved. */
                CASE WHEN EXISTS (
                    SELECT 1
                    FROM acta.checkpoints c
                    WHERE
                        c.job_id = r.job_id
                        AND c.kind_code IN (20 /* CheckpointKindCode.Signal */, 50 /* CheckpointKindCode.ChildLatch */)
                        AND c.status_code = 30 /* CheckpointStatusCode.Expired */
                        AND c.due_at_utc = r.next_run_at_utc
                ) THEN 1 ELSE 0 END AS wait_resolved,
                /* MaxAttempts is the one-off retry budget and a slot's failure_count accumulates
                   across occurrences, so a recurring reclaim always re-arms Ready instead of
                   terminally failing the schedule - mirroring ComputeRecurringOutcome on the worker path. */
                CASE WHEN EXISTS (
                    SELECT 1
                    FROM acta.schedules sc
                    WHERE sc.job_id = r.job_id
                ) THEN 1 ELSE 0 END AS is_recurring
            FROM @stuck k
            INNER JOIN acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, FORCESEEK) ON r.job_id = k.id
            INNER JOIN acta.jobs j ON j.id = r.job_id
            INNER JOIN acta.definitions jd ON jd.id = j.definition_id
            WHERE
                r.status_code = 50 /* JobStatusCode.Executing */
                AND r.leased_by_worker_id IS NOT NULL
                AND r.lease_expires_at_utc < @now
                AND r.namespace_id = @p_namespace_id
                AND (r.lane_id IS NULL OR r.lane_id IN (SELECT e.id FROM @lanes e))
        )

        /* Budget-neutral for a resolved wait: the surviving path would have ended this attempt at no
           cost, so the job goes back to Suspended on the same past deadline, unclaimed and uncharged,
           and the replay lands whatever outcome the waiting overload chooses. */
        UPDATE r
        SET
            status_code = CASE
                WHEN s.wait_resolved = 1
                    THEN 20 /* JobStatusCode.Suspended */
                WHEN s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN 200 /* JobStatusCode.Failed */
                ELSE 10  /* JobStatusCode.Ready */
            END,
            failure_count = CASE
                WHEN s.wait_resolved = 1
                    THEN r.failure_count
                ELSE s.new_failure_count
            END,
            next_run_at_utc = CASE
                WHEN s.wait_resolved = 1
                    THEN r.next_run_at_utc
                WHEN s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN r.next_run_at_utc
                ELSE @now
            END,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE
                WHEN s.wait_resolved = 0 AND s.is_recurring = 0 AND s.new_failure_count >= s.max_attempts
                    THEN DATEADD(SECOND, s.retention_seconds, @now)
                ELSE r.retention_until_utc
            END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id, j.job_ref, j.namespace_id, INSERTED.execution_number,
            j.lineage_root_id, j.definition_id, j.tenant_id, DELETED.leased_by_worker_id,
            DELETED.status_code, INSERTED.status_code, j.audit_level_code,
            j.parent_id
        INTO
            @reclaimed (
                id, job_ref, namespace_id, execution_number, lineage_root_id,
                definition_id, tenant_id, worker_id, from_status_code, to_status_code, audit_level_code, parent_id
            )
        -- FORCESEEK keeps this update on a key seek instead of a lock-escalating scan of runtimes;
        -- see docs/internals/sql-execution-policy.md.
        FROM acta.runtimes r WITH (FORCESEEK)
        INNER JOIN stuck s ON s.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            @now,
            namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            id,
            job_ref,
            execution_number,
            COALESCE(lineage_root_id, id),
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            230 /* ExecutionStatusCode.Orphaned */,
            NULL,
            21 /* EventReasonCode.JobLeaseExpired */,
            /* Suspended is reachable only through the resolved-wait arm above, so the landed status is
               what tells the two messages apart. */
            CASE WHEN to_status_code = 20 /* JobStatusCode.Suspended */
                THEN N'Worker lease expired while an expired wait was resolving; re-armed on the same deadline with no attempt charged.'
                ELSE N'Worker lease expired; reclaimed by crash recovery.'
            END
        FROM @reclaimed
        WHERE audit_level_code IN (10 /* DefinitionAuditLevelCode.Failures */, 20 /* DefinitionAuditLevelCode.Audit */);

        /* A head reclaimed to Failed hands its lane on; a head re-armed Ready keeps it. Promotion runs
           under the lane locks and re-reads each head rather than trusting the walk. */
        UPDATE r
        SET
            status_code = 10 /* JobStatusCode.Ready */,
            next_run_at_utc = CASE WHEN r.next_run_at_utc > @now THEN r.next_run_at_utc ELSE @now END,
            modified_at_utc = @now,
            version = r.version + 1
        FROM @lanes e
        CROSS APPLY (
            SELECT TOP (1) m.job_id, m.status_code
            FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
            WHERE
                m.lane_id = e.id
                AND m.lane_id IS NOT NULL
                AND m.status_code IN (
                    10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                    30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                )
            ORDER BY m.job_id
        ) h
        INNER JOIN acta.runtimes r WITH (FORCESEEK) ON r.job_id = h.job_id
        WHERE
            h.status_code = 15 /* JobStatusCode.Blocked */
            AND r.status_code = 15 /* JobStatusCode.Blocked */
            AND NOT EXISTS (
                SELECT 1
                FROM acta.runtimes o WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                WHERE
                    o.lane_id = e.id
                    AND o.lane_id IS NOT NULL
                    AND o.status_code IN (
                        10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */,
                        50 /* JobStatusCode.Executing */
                    )
            );

        SELECT
            id AS job_id,
            to_status_code AS to_status,
            parent_id,
            CAST(0 AS TINYINT) AS lane_repaired
        FROM @reclaimed
        UNION ALL
        SELECT
            id AS job_id,
            CAST(10 /* JobStatusCode.Ready */ AS TINYINT) AS to_status,
            NULL AS parent_id,
            CAST(1 AS TINYINT) AS lane_repaired
        FROM @repaired;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO


IF NOT EXISTS (SELECT 1 FROM acta.migrations WHERE name = 'M20261016080729_claim_writes_no_started_event')
INSERT INTO acta.migrations (name)
VALUES ('M20261016080729_claim_writes_no_started_event');
GO
-- ===== END M20261016080729_claim_writes_no_started_event =====
GO
-- ===== BEGIN M20261016085434_enqueue_probes_seek =====
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO


-- Only @p_namespace_name and @p_job_name are required; other scalars default (@p_job_ref is
-- server-generated when omitted; @p_input_format_id defaults json/none by input presence). The tag TVP
-- has no default (SQL Server TVPs cannot); pass an empty table variable for a tag-free enqueue.
CREATE OR ALTER PROCEDURE acta.enqueue_job
    @p_job_ref UNIQUEIDENTIFIER = NULL,
    @p_namespace_name VARCHAR(128) = NULL,
    @p_job_name VARCHAR(128) = NULL,
    @p_deduplication_key VARCHAR(128) = NULL,
    @p_correlation_key VARCHAR(64) = NULL,
    @p_priority_override TINYINT = NULL,
    @p_input_format_id TINYINT = NULL,
    @p_input VARBINARY(MAX) = NULL,
    @p_concurrency_key VARCHAR(128) = NULL,
    @p_next_run_at_utc DATETIME2(3) = NULL,
    @p_delay_seconds INT = NULL,
    @p_parent_id BIGINT = NULL,
    @p_tenant_name VARCHAR(128) = NULL,
    @p_tenant_override BIT = 0,
    @p_tag_batch acta.enqueue_tags_batch READONLY,
    @p_lane VARCHAR(128) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
        DECLARE @ns_id INT, @ns_status TINYINT, @def_id INT, @def_priority SMALLINT;
        DECLARE @def_audit TINYINT, @def_status TINYINT, @def_tenant_req TINYINT;
        DECLARE @tenant_id INT, @tenant_status TINYINT, @lineage BIGINT, @parent_corr VARCHAR(64), @parent_tenant INT;
        DECLARE @existing_id BIGINT, @existing_ref UNIQUEIDENTIFIER, @job_id BIGINT;
        DECLARE @lane VARCHAR(128), @lane_id BIGINT, @ancestor_lane_hits INT;

        -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
        -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
        -- on error rethrow and let the caller roll back the whole transaction.

        -- Server-generate the job ref when the caller omits it (a proc default cannot be NEWID()).
        SET @p_job_ref = COALESCE(@p_job_ref, NEWID());

        SELECT
            @ns_id = ns.id,
            @ns_status = ns.status_code,
            @def_id = jd.id,
            @def_priority = jd.priority_code_effective,
            @def_audit = jd.audit_level_code_effective,
            @def_status = jd.status_code,
            @def_tenant_req = jd.tenant_requirement_code,
            @lane = COALESCE(@p_lane, jd.lane)
        FROM acta.namespaces ns
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = @p_job_name
        WHERE ns.name = @p_namespace_name;

        IF @def_id IS NULL
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF @ns_status <> 10 /* NamespaceStatusCode.Active */
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF @def_status <> 10 /* DefinitionStatusCode.Active */
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF @p_tenant_name IS NOT NULL
            BEGIN
                SELECT
                    @tenant_id = t.id,
                    @tenant_status = t.status_code
                FROM acta.tenants t
                WHERE t.tenant_name = @p_tenant_name;

                IF @tenant_id IS NULL
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;

                IF @tenant_status <> 10 /* TenantStatusCode.Active */
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        IF @def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ AND @p_tenant_name IS NOT NULL
            BEGIN
                THROW 50008, 'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: the job definition forbids a tenant and the row names one.', 1;
            END;

        -- The lane row is the lane's mutex, held to commit (docs/internals/sql-execution-policy.md, "Lane
        -- lock order"). The name only resolves the id; the lock is taken by id, on the clustered key.
        -- Ready versus Blocked is read after the lane lock, which a SNAPSHOT transaction (level 5) never sees.
        IF @lane IS NOT NULL
            AND (SELECT s.transaction_isolation_level FROM sys.dm_exec_sessions s WHERE s.session_id = @@SPID) = 5
            THROW 50011, 'ACTA:ENQ_LANE_ISOLATION:Enqueue rejected: a laned enqueue cannot run in a SNAPSHOT caller transaction.', 1;

        DECLARE @lane_found BIGINT;
        WHILE @lane IS NOT NULL AND @lane_id IS NULL
            BEGIN
                SET @lane_found = NULL;
                SELECT @lane_found = l.id
                FROM acta.lanes l
                WHERE
                    l.namespace_id = @ns_id
                    AND l.name = @lane;

                IF @lane_found IS NOT NULL
                    SELECT @lane_id = l.id
                    FROM acta.lanes l WITH (UPDLOCK, ROWLOCK)
                    WHERE l.id = @lane_found;

                IF @lane_found IS NULL
                    BEGIN
                        SET XACT_ABORT OFF;
                        BEGIN TRY
                            INSERT INTO acta.lanes (namespace_id, name, created_at_utc)
                            VALUES (@ns_id, @lane, @now);
                        END TRY
                        BEGIN CATCH
                            SET XACT_ABORT ON;
                            IF ERROR_NUMBER() NOT IN (2601, 2627)
                                THROW;
                        END CATCH;
                        SET XACT_ABORT ON;
                    END;
            END;

        IF @p_deduplication_key IS NOT NULL
            BEGIN
                -- Each probe seeks its dedup index, the index's filter restated: under HOLDLOCK a scan locks every row
                -- it reads and escalates to a table lock on jobs, which a stale row estimate makes the cheaper plan.
                IF @p_parent_id IS NOT NULL
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK, FORCESEEK, INDEX (ux_jobs_deduplication_key_child))
                        WHERE
                            j.parent_id = @p_parent_id
                            AND j.deduplication_key = @p_deduplication_key
                            AND j.parent_id IS NOT NULL
                            AND j.deduplication_key IS NOT NULL;
                    END
                ELSE
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK, FORCESEEK, INDEX (ux_jobs_deduplication_key_root))
                        WHERE
                            j.namespace_id = @ns_id
                            AND j.deduplication_key = @p_deduplication_key
                            AND j.parent_id IS NULL
                            AND j.deduplication_key IS NOT NULL;
                    END;
            END;

        IF @p_parent_id IS NOT NULL
            BEGIN
                SELECT
                    @lineage = COALESCE(pj.lineage_root_id, pj.id),
                    @parent_corr = pj.correlation_key,
                    @parent_tenant = pj.tenant_id
                FROM acta.jobs pj WITH (UPDLOCK, ROWLOCK, FORCESEEK)
                INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
                WHERE
                    pj.id = @p_parent_id
                    AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

                IF @lineage IS NULL
                    BEGIN
                        THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
                    END;

                IF @lane_id IS NOT NULL
                    BEGIN
                        WITH ancestors AS (
                            SELECT a.id, a.parent_id
                            FROM acta.jobs a
                            WHERE a.id = @p_parent_id
                            UNION ALL
                            SELECT a.id, a.parent_id
                            FROM acta.jobs a
                            INNER JOIN ancestors c ON a.id = c.parent_id
                        )

                        SELECT @ancestor_lane_hits = COUNT(*)
                        FROM ancestors c
                        INNER JOIN acta.runtimes ar ON ar.job_id = c.id
                        WHERE
                            ar.lane_id = @lane_id
                            AND ar.status_code IN (
                                10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                                30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                            )
                        -- A lineage has no depth bound, so neither has the walk.
                        OPTION (MAXRECURSION 0);

                        IF @ancestor_lane_hits > 0
                            BEGIN
                                DECLARE
                                    @ancestor_msg NVARCHAR(2048) = 'ACTA:ENQ_ANCESTOR_LANE:Enqueue rejected: a child names the lane of an'
                                    + ' unfinished ancestor, so it would wait behind the ancestor that waits for it.';
                                THROW 50010, @ancestor_msg, 1;
                            END;
                    END;
            END;

        IF @def_tenant_req = 10 /* DefinitionTenantRequirementCode.Required */ AND @tenant_id IS NULL AND @parent_tenant IS NULL
            BEGIN
                THROW 50007, 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: the job definition requires a tenant and the row carries none.', 1;
            END;

        IF @tenant_id IS NOT NULL AND @parent_tenant IS NOT NULL AND @tenant_id <> @parent_tenant AND @p_tenant_override = 0
            BEGIN
                THROW 50009,
                'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: a child TenantName differs from the parent tenant without an explicit override.',
                1;
            END;

        IF @existing_id IS NULL
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                VALUES (
                    @p_job_ref, @lineage, @p_parent_id,
                    @p_deduplication_key, COALESCE(@p_correlation_key, @parent_corr),
                    @ns_id, @def_id,
                    CASE
                        WHEN @def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(@tenant_id, @parent_tenant)
                    END,
                    COALESCE(
                        @p_input_format_id,
                        CASE WHEN @p_input IS NULL THEN 0 /* JobPayloadFormat.None */ ELSE 1 /* JobPayloadFormat.Json */ END
                    ),
                    @p_input,
                    @p_concurrency_key, @def_audit,
                    @now
                );

                SET @job_id = SCOPE_IDENTITY();

                -- A laned job enters Ready only when no member of its lane is unfinished; otherwise it waits
                -- as Blocked, keeping its due instant for when the settle ahead of it promotes it.
                DECLARE @status TINYINT = 10 /* JobStatusCode.Ready */;
                IF
                    @lane_id IS NOT NULL
                    AND EXISTS (
                        SELECT 1
                        FROM acta.runtimes m WITH (INDEX (ix_runtimes_lane), FORCESEEK)
                        WHERE
                            m.lane_id = @lane_id
                            AND m.lane_id IS NOT NULL
                            AND m.status_code IN (
                                10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                                30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                            )
                    )
                    SET @status = 15 /* JobStatusCode.Blocked */;

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, lane_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                VALUES (
                    @job_id, @ns_id, @lane_id, @status,
                    COALESCE(@p_priority_override, @def_priority),
                    COALESCE(@p_next_run_at_utc, DATEADD(SECOND, COALESCE(@p_delay_seconds, 0), @now)),
                    0, 0, NULL,
                    @now, 0
                );

                INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
                SELECT
                    50 /* TagScopeCode.Job */,
                    @job_id,
                    @ns_id,
                    t.name,
                    t.value,
                    t.value_search
                FROM @p_tag_batch t;
            END;

        SELECT
            0 AS ordinal,
            COALESCE(@job_id, @existing_id) AS job_id,
            CASE WHEN @job_id IS NOT NULL THEN @p_job_ref ELSE @existing_ref END AS job_ref,
            CASE
                WHEN @job_id IS NOT NULL
                    THEN 1 /* EnqueueJobAction.Inserted */
                ELSE 2 /* EnqueueJobAction.Deduplicated */
            END AS action;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO

-- Lock order: the batch's lanes in id order, then job rows (docs/internals/sql-execution-policy.md,
-- "Lane lock order").
CREATE OR ALTER PROCEDURE acta.enqueue_jobs
    @p_batch acta.enqueue_jobs_batch READONLY,
    @p_tag_batch acta.enqueue_tags_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @entry_trancount INT = @@TRANCOUNT;
    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

        -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
        -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
        -- on error rethrow and let the caller roll back the whole transaction.

        DECLARE @resolved TABLE (
            ordinal INT PRIMARY KEY,
            ns_id INT NOT NULL,
            ns_status TINYINT NOT NULL,
            def_id INT NOT NULL,
            def_priority SMALLINT NOT NULL,
            def_audit_level TINYINT NOT NULL,
            def_status TINYINT NOT NULL,
            def_tenant_req TINYINT NOT NULL,
            tenant_id INT NULL,
            lane VARCHAR(128) NULL,
            lane_id BIGINT NULL,
            lane_head BIT NOT NULL DEFAULT 0
        );

        INSERT INTO @resolved (ordinal, ns_id, ns_status, def_id, def_priority, def_audit_level, def_status, def_tenant_req, lane)
        SELECT
            b.ordinal,
            ns.id,
            ns.status_code,
            jd.id,
            jd.priority_code_effective,
            jd.audit_level_code_effective,
            jd.status_code,
            jd.tenant_requirement_code,
            COALESCE(b.lane, jd.lane)
        FROM @p_batch b
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = b.job_name;

        IF (SELECT COUNT(*) FROM @resolved) < (SELECT COUNT(*) FROM @p_batch)
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE ns_status <> 10 /* NamespaceStatusCode.Active */
            )
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE def_status <> 10 /* DefinitionStatusCode.Active */
            )
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE tenant_name IS NOT NULL
            )
            BEGIN
                UPDATE r
                SET tenant_id = t.id
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN acta.tenants t
                    ON
                        t.tenant_name = b.tenant_name
                        AND t.status_code = 10 /* TenantStatusCode.Active */
                WHERE b.tenant_name IS NOT NULL;

                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b
                        WHERE
                            b.tenant_name IS NOT NULL
                            AND NOT EXISTS (
                                SELECT 1 FROM acta.tenants t
                                WHERE t.tenant_name = b.tenant_name
                            )
                    )
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;
                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b JOIN acta.tenants t ON t.tenant_name = b.tenant_name
                        WHERE b.tenant_name IS NOT NULL AND t.status_code <> 10 /* TenantStatusCode.Active */
                    )
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        -- Missing lanes are inserted in name order without a range lock, then every lane is locked one row
        -- at a time in id order (docs/internals/sql-execution-policy.md, "Lane lock order").
        DECLARE @lanes TABLE (
            ns_id INT NOT NULL,
            name VARCHAR(128) NOT NULL,
            id BIGINT NULL,
            PRIMARY KEY (ns_id, name)
        );

        INSERT INTO @lanes (ns_id, name)
        SELECT DISTINCT r.ns_id, r.lane
        FROM @resolved r
        WHERE r.lane IS NOT NULL;

        DECLARE @laned BIT = CASE WHEN EXISTS (SELECT 1 FROM @lanes) THEN 1 ELSE 0 END;
        DECLARE @lanes_pending BIT = @laned;
        DECLARE @lane_cursor BIGINT, @lane_next BIGINT, @lane_locked BIGINT;

        -- Ready versus Blocked is read after the lane locks, which a SNAPSHOT transaction (level 5) never sees.
        IF @lanes_pending = 1
            AND (SELECT s.transaction_isolation_level FROM sys.dm_exec_sessions s WHERE s.session_id = @@SPID) = 5
            THROW 50011, 'ACTA:ENQ_LANE_ISOLATION:Enqueue rejected: a laned enqueue cannot run in a SNAPSHOT caller transaction.', 1;

        WHILE @lanes_pending = 1
            BEGIN
                SET XACT_ABORT OFF;
                BEGIN TRY
                    INSERT INTO acta.lanes (namespace_id, name, created_at_utc)
                    SELECT e.ns_id, e.name, @now
                    FROM @lanes e
                    WHERE NOT EXISTS (
                        SELECT 1
                        FROM acta.lanes l
                        WHERE
                            l.namespace_id = e.ns_id
                            AND l.name = e.name
                    )
                    ORDER BY e.name;
                END TRY
                BEGIN CATCH
                    SET XACT_ABORT ON;
                    IF ERROR_NUMBER() NOT IN (2601, 2627)
                        THROW;
                END CATCH;
                SET XACT_ABORT ON;

                UPDATE e
                SET id = l.id
                FROM @lanes e
                LEFT JOIN acta.lanes l
                    ON
                        l.namespace_id = e.ns_id
                        AND l.name = e.name;

                SET @lanes_pending = CASE WHEN EXISTS (SELECT 1 FROM @lanes WHERE id IS NULL) THEN 1 ELSE 0 END;
                SET @lane_cursor = 0;
                WHILE @lanes_pending = 0
                    BEGIN
                        SET @lane_next = NULL;
                        SELECT TOP (1) @lane_next = e.id
                        FROM @lanes e
                        WHERE e.id > @lane_cursor
                        ORDER BY e.id;

                        IF @lane_next IS NULL
                            BREAK;

                        SET @lane_locked = NULL;
                        SELECT @lane_locked = l.id
                        FROM acta.lanes l WITH (UPDLOCK, ROWLOCK)
                        WHERE l.id = @lane_next;

                        IF @lane_locked IS NULL
                            SET @lanes_pending = 1;
                        SET @lane_cursor = @lane_next;
                    END;
            END;

        UPDATE r
        SET lane_id = e.id
        FROM @resolved r
        INNER JOIN @lanes e
            ON
                e.ns_id = r.ns_id
                AND e.name = r.lane;

        DECLARE @existing TABLE (
            ordinal INT PRIMARY KEY,
            id BIGINT NOT NULL,
            job_ref UNIQUEIDENTIFIER NOT NULL
        );

        -- Skip when no row has a key: the dedup probes' HOLDLOCK range locks (held to commit) would
        -- otherwise serialize every concurrent keyless enqueue on the namespace.
        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE deduplication_key IS NOT NULL
            )
            BEGIN
                -- Each probe seeks its dedup index, the index's filter restated: under HOLDLOCK a scan locks every row
                -- it reads and escalates to a table lock on jobs, which a stale row estimate makes the cheaper plan.
                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK, FORCESEEK, INDEX (ux_jobs_deduplication_key_child))
                    ON
                        j.parent_id = b.parent_id
                        AND j.deduplication_key = b.deduplication_key
                        AND j.parent_id IS NOT NULL
                        AND j.deduplication_key IS NOT NULL
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NOT NULL;

                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK, FORCESEEK, INDEX (ux_jobs_deduplication_key_root))
                    ON
                        j.namespace_id = r.ns_id
                        AND j.deduplication_key = b.deduplication_key
                        AND j.parent_id IS NULL
                        AND j.deduplication_key IS NOT NULL
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NULL;
            END;

        DECLARE @parents TABLE (
            ordinal INT PRIMARY KEY,
            lineage_root_id BIGINT NOT NULL,
            correlation_key VARCHAR(64) NULL,
            tenant_id INT NULL
        );

        INSERT INTO @parents (ordinal, lineage_root_id, correlation_key, tenant_id)
        SELECT
            b.ordinal,
            COALESCE(pj.lineage_root_id, pj.id),
            pj.correlation_key,
            pj.tenant_id
        FROM @p_batch b
        INNER JOIN acta.jobs pj WITH (UPDLOCK, ROWLOCK, FORCESEEK) ON pj.id = b.parent_id
        INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
        WHERE
            b.parent_id IS NOT NULL
            AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
        ORDER BY pj.id DESC;

        IF (
            SELECT COUNT(*) FROM @parents) < (
            SELECT COUNT(*) FROM @p_batch
            WHERE parent_id IS NOT NULL
        )
            BEGIN
                THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.def_tenant_req = 10 /* DefinitionTenantRequirementCode.Required */
                    AND r.tenant_id IS NULL
                    AND p.tenant_id IS NULL
            )
            BEGIN
                THROW 50007,
                'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: one or more rows target a definition that requires a tenant and carry none.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                WHERE
                    r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */
                    AND b.tenant_name IS NOT NULL
            )
            BEGIN
                THROW 50008,
                'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: one or more rows target a definition that forbids a tenant and name one.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.tenant_id IS NOT NULL
                    AND p.tenant_id IS NOT NULL
                    AND r.tenant_id <> p.tenant_id
                    AND b.tenant_override = 0
            )
            BEGIN
                DECLARE
                    @tenant_msg NVARCHAR(2048) = 'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: one or more child rows name a'
                    + ' TenantName that differs from the parent tenant without an explicit override.';
                THROW 50009, @tenant_msg, 1;
            END;

        -- A child may not wait behind an unfinished ancestor in its own lane: the ancestor waits for it.
        DECLARE @ancestor_lane_hits INT = 0;
        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                WHERE
                    r.lane_id IS NOT NULL
                    AND b.parent_id IS NOT NULL
            )
            BEGIN
                WITH ancestors AS (
                    SELECT r.lane_id, a.id, a.parent_id
                    FROM @resolved r
                    INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                    INNER JOIN acta.jobs a ON a.id = b.parent_id
                    WHERE r.lane_id IS NOT NULL
                    UNION ALL
                    SELECT c.lane_id, a.id, a.parent_id
                    FROM acta.jobs a
                    INNER JOIN ancestors c ON a.id = c.parent_id
                )

                SELECT @ancestor_lane_hits = COUNT(*)
                FROM ancestors c
                INNER JOIN acta.runtimes ar ON ar.job_id = c.id
                WHERE
                    ar.lane_id = c.lane_id
                    AND ar.status_code IN (
                        10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                        30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                    )
                -- A lineage has no depth bound, so neither has the walk.
                OPTION (MAXRECURSION 0);
            END;

        IF @ancestor_lane_hits > 0
            BEGIN
                DECLARE
                    @ancestor_msg NVARCHAR(2048) = 'ACTA:ENQ_ANCESTOR_LANE:Enqueue rejected: one or more child rows name the lane of'
                    + ' an unfinished ancestor, so they would wait behind the ancestor that waits for them.';
                THROW 50010, @ancestor_msg, 1;
            END;

        DECLARE @map TABLE (
            job_ref UNIQUEIDENTIFIER PRIMARY KEY,
            id BIGINT NOT NULL
        );

        -- An unlaned batch runs the plain inserts; only a laned one pays for batch order and lane heads.
        -- Both runtimes inserts force nested loops so the foreign-key checks seek their parent rows
        -- (docs/internals/sql-execution-policy.md, "Foreign keys in set-based writes").
        IF @laned = 0
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                OUTPUT INSERTED.job_ref, INSERTED.id INTO @map (job_ref, id)
                SELECT
                    b.job_ref,
                    p.lineage_root_id,
                    b.parent_id,
                    b.deduplication_key,
                    COALESCE(b.correlation_key, p.correlation_key),
                    r.ns_id,
                    r.def_id,
                    CASE
                        WHEN r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(r.tenant_id, p.tenant_id)
                    END,
                    b.input_format_id,
                    b.input,
                    b.concurrency_key,
                    r.def_audit_level,
                    @now
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                LEFT JOIN @existing e ON e.ordinal = b.ordinal
                WHERE e.ordinal IS NULL;

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                SELECT
                    m.id,
                    r.ns_id,
                    10 /* JobStatusCode.Ready */,
                    COALESCE(b.priority_override, r.def_priority),
                    COALESCE(b.next_run_at_utc, DATEADD(SECOND, COALESCE(b.delay_seconds, 0), @now)),
                    0,
                    0,
                    NULL,
                    @now,
                    0
                FROM @map m
                INNER JOIN @p_batch b ON b.job_ref = m.job_ref
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                OPTION (LOOP JOIN);
            END
        ELSE
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    concurrency_key, audit_level_code,
                    created_at_utc
                )
                OUTPUT INSERTED.job_ref, INSERTED.id INTO @map (job_ref, id)
                SELECT
                    b.job_ref,
                    p.lineage_root_id,
                    b.parent_id,
                    b.deduplication_key,
                    COALESCE(b.correlation_key, p.correlation_key),
                    r.ns_id,
                    r.def_id,
                    CASE
                        WHEN r.def_tenant_req = 20 /* DefinitionTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(r.tenant_id, p.tenant_id)
                    END,
                    b.input_format_id,
                    b.input,
                    b.concurrency_key,
                    r.def_audit_level,
                    @now
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                LEFT JOIN @existing e ON e.ordinal = b.ordinal
                WHERE e.ordinal IS NULL
                -- Identity values follow this order, so job-id order equals the caller's batch order, which
                -- is the order a lane runs in.
                ORDER BY b.ordinal;

                -- A lane's head is its first inserted row, the lowest ordinal the dedup probe kept, and only
                -- when no unfinished member is already there; every other laned row waits as Blocked. The
                -- probe runs under the lane locks, before this batch has any runtimes row.
                UPDATE r
                SET lane_head = 1
                FROM @resolved r
                INNER JOIN (
                    SELECT MIN(h.ordinal) AS ordinal
                    FROM @resolved h
                    LEFT JOIN @existing x ON x.ordinal = h.ordinal
                    WHERE
                        h.lane_id IS NOT NULL
                        AND x.ordinal IS NULL
                    GROUP BY h.lane_id
                ) f ON f.ordinal = r.ordinal
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM acta.runtimes x WITH (FORCESEEK)
                    WHERE
                        x.lane_id = r.lane_id
                        AND x.lane_id IS NOT NULL
                        AND x.status_code IN (
                            10 /* JobStatusCode.Ready */, 15 /* JobStatusCode.Blocked */, 20 /* JobStatusCode.Suspended */,
                            30 /* JobStatusCode.Paused */, 50 /* JobStatusCode.Executing */
                        )
                );

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, lane_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                SELECT
                    m.id,
                    r.ns_id,
                    r.lane_id,
                    CASE
                        WHEN r.lane_id IS NULL OR r.lane_head = 1 THEN 10 /* JobStatusCode.Ready */
                        ELSE 15 /* JobStatusCode.Blocked */
                    END,
                    COALESCE(b.priority_override, r.def_priority),
                    COALESCE(b.next_run_at_utc, DATEADD(SECOND, COALESCE(b.delay_seconds, 0), @now)),
                    0,
                    0,
                    NULL,
                    @now,
                    0
                FROM @map m
                INNER JOIN @p_batch b ON b.job_ref = m.job_ref
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                OPTION (LOOP JOIN);
            END;

        INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT
            50 /* TagScopeCode.Job */,
            m.id,
            r.ns_id,
            t.name,
            t.value,
            t.value_search
        FROM @p_tag_batch t
        INNER JOIN @p_batch b ON b.ordinal = t.ordinal
        INNER JOIN @map m ON m.job_ref = b.job_ref
        INNER JOIN @resolved r ON r.ordinal = t.ordinal;

        SELECT
            b.ordinal,
            COALESCE(m.id, e.id) AS job_id,
            COALESCE(m.job_ref, e.job_ref) AS job_ref,
            CASE
                WHEN m.id IS NOT NULL
                    THEN 1 /* EnqueueJobAction.Inserted */
                ELSE 2 /* EnqueueJobAction.Deduplicated */
            END AS action
        FROM @p_batch b
        LEFT JOIN @map m ON m.job_ref = b.job_ref
        LEFT JOIN @existing e ON e.ordinal = b.ordinal
        ORDER BY b.ordinal;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO


